// V195 PATIENT ID LOCK RESTORE:
// Locked format: BranchCode-DDMMYYYY-Serial, e.g. KNE-31122026-001 / JPE-31122026-001.
// No random suffix, no YYMMDD format. Serial is branch+date wise 001, 002, 003...
const PATIENT_ID_BRANCH_CODES={
 'kishanganj':'KNE','jalpaiguri':'JPE','cooch behar':'COB','coochbehar':'COB','falakata':'FLK','birpara':'BIR'
};
function lockedBranchCode(br){
 let name=String(br||'').trim();
 let key=name.toLowerCase().replace(/\s+/g,' ');
 if(PATIENT_ID_BRANCH_CODES[key])return PATIENT_ID_BRANCH_CODES[key];
 let cfg=(C.branches||[]).find(b=>String(b.name||'').toLowerCase()===key);
 return (cfg?.code||name.replace(/[^A-Za-z]/g,'').slice(0,3)||'PAT').toUpperCase();
}
window["lockedBranchCode"]=lockedBranchCode;
function lockedDateCode(d){
 let v=String(d||today()).slice(0,10);
 let m=v.match(/^(\d{4})-(\d{2})-(\d{2})$/);
 return m?`${m[3]}${m[2]}${m[1]}`:v.replace(/\D/g,'').slice(0,8);
}
window["lockedDateCode"]=lockedDateCode;
function nextPatientSerial(code,dateCode){
 let max=0;
 try{
  (load('patients')||[]).forEach(p=>{
   let id=String(p.patientId||'');
   let m=id.match(new RegExp('^'+code+'-'+dateCode+'-?(\\d{3})$'));
   if(m)max=Math.max(max,Number(m[1]||0));
  });
 }catch(e){}
 /* TK-CHECKED (2026-07-26): the phone remembers every serial IT has already
    given out for this branch+date and uses max(list, memory)+1
    (PatientIdGenerator, V133 duplicate-ID fix). The web only looked at the
    patient list it happened to have loaded, so two registrations done back to
    back . before the list refreshed . could both get -001. The same memory is
    kept here. Read + write only; nothing else in the flow changes. */
 try{
  const key='rk_pid_serial_'+code+'-'+dateCode;
  const seen=Number(localStorage.getItem(key)||0);
  if(seen>max)max=seen;
  localStorage.setItem(key,String(max+1));
 }catch(e){}
 return String(max+1).padStart(3,'0');
}
