const OLD_PATIENT_ID_PREFIX_MAP={CBE:'COB',COB:'COB',KNE:'KNE',KIS:'KNE',JPE:'JPE',JAL:'JPE',FLK:'FLK',BIR:'BIR'};
function normalizePatientIdValue(id,branch,date){
 let raw=String(id||'').trim().toUpperCase();
 let dateCode=lockedDateCode(date), serial='001', code=lockedBranchCode(branch);
 let m=raw.match(/^([A-Z]{3})[-_]?([0-9]{8})[-_]?([0-9]{3})$/);
 if(m){code=OLD_PATIENT_ID_PREFIX_MAP[m[1]]||lockedBranchCode(branch)||m[1];dateCode=m[2];serial=m[3]}
 else if(raw){
  let m2=raw.match(/^([A-Z]{3}).*?([0-9]{8}).*?([0-9]{3})$/);
  if(m2){code=OLD_PATIENT_ID_PREFIX_MAP[m2[1]]||lockedBranchCode(branch)||m2[1];dateCode=m2[2];serial=m2[3]}
 }
 return `${code}-${dateCode}-${serial}`;
}
window["normalizePatientIdValue"]=normalizePatientIdValue;
function normalizePatientRecord(r){
 if(!r||typeof r!=='object')return r;
 let x={...r};
 let correct=normalizePatientIdValue(x.patientId,x.branch,x.visitDate||x.registrationDate||x.date);
 if(!x.patientId||String(x.patientId)!==correct)x.patientId=correct;
 return x;
}
