function wlv1AddrDefaultTag(address){
  const p=wlv1AddrParse(address);
  const structured=p.THANA||p.VILLAGE||p.POST||p.DISTRICT;
  if(structured)return structured;
  const raw=String(address||'').trim();
  if(!raw)return '';
  return raw.split(',')[0].trim();
}
