function wlv1EditAddressTag(mobile,stage){
  const mm=mob(mobile);
  const frow=load('followups').find(f=>mob(f.mobile)===mm)||{};
  const address=frow.address||'';
  const parts=wlv1AddrParse(address);
  const current=wlv1AddrSavedTag(mobile)||(String(stage||'')==='Inquiry'?'':wlv1AddrDefaultTag(address));
  const optKeys=['THANA','VILLAGE','POST','DISTRICT'].filter(k=>parts[k]);
  const options=optKeys.map(k=>`<button type="button" class="wlv1Pick ${parts[k]===current?'on':''}" onclick="wlv1PickAddressTagVal(this,'${esc(parts[k])}')">${esc(parts[k])}</button>`).join('');
  modal(`<h2>Address Tag</h2><div class="card">${options?`<label>Pick from address</label><div class="wlv1PickRow" data-wlv1group="addrtag">${options}</div>`:''}<label>Or type your own</label><input id="wlv1AddrTagInput" class="input" value="${esc(current)}" oninput="wlv1Caps(this)"><div class="actions"><button onclick="wlv1SaveAddressTag('${esc(mm)}','${esc(stage||'')}')">Save</button><button class="ghost" onclick="closeModal()">Cancel</button></div></div>`);
}
window["wlv1EditAddressTag"]=wlv1EditAddressTag;
function wlv1PickAddressTagVal(btn,val){
  const box=btn.closest('.wlv1PickRow');
  if(box)Array.from(box.querySelectorAll('.wlv1Pick')).forEach(b=>b.classList.remove('on'));
  btn.classList.add('on');
  const inp=document.getElementById('wlv1AddrTagInput');
  if(inp)inp.value=val;
}
window["wlv1PickAddressTagVal"]=wlv1PickAddressTagVal;
function wlv1SaveAddressTag(mobile,stage){
  const val=($('#wlv1AddrTagInput')?.value||'').trim();
  if(!val)return toast('Enter an address tag');
  const id=mob(mobile);
  if(id.length!==10)return toast('Invalid mobile');
  const patch={value:val,updatedBy:user?.mobile||'',updatedAt:new Date().toISOString()};
  const updated=upd('address_tags',id,patch);
  if(!updated)add('address_tags',{id,mobile:id,...patch});
  toast('Address tag saved');closeModal();
  try{followup(stage||'Inquiry')}catch(_e){}
}
window["wlv1SaveAddressTag"]=wlv1SaveAddressTag;
const paymentOptions=(sel='')=>['CASH','UPI'].map(v=>`<option ${payMode(sel)===v?'selected':''}>${v}</option>`).join('');
/* 🔴🔴🔴🆕🔒 V435 (TK-রিপোর্ট ১৮.০৮.২০২৬ — সব পর্দা ধীর)। **প্রোফাইলে মেপে পাওয়া:**
   এই দুটো তালিকা **প্রতিবার নতুন করে** বানানো হত, আর `atob()` (লেখা খোলা) সাতবার
   করে চলত। তালিকা দুটো ডাকা হয় `isSeededRecord()`-এর ভিতর থেকে — আর সেটা
   `cleanRows()` হয়ে **প্রতিটা সারির প্রতিটা ঘরের জন্য** চলে, প্রতিটা `load()`-এ।
   ৩০০০ রোগী ⇒ এক-একটা `load()`-এ প্রায় **দেড় লাখ** বার `atob()`। প্রোফাইলে
   Search পর্দায় শুধু `atob` একাই **৪৪%** সময় খাচ্ছিল।
   **সমাধান:** লেখাগুলো স্থির, তাই **একবারই** খুলে রাখা হয়। ⛔ ফল হুবহু একই —
   একই সাতটা শব্দ, একই চারটে নম্বর; কোন সারি বাদ যাবে সেই নিয়ম এক অক্ষরও বদলায়নি। */
const __SEEDED_WORDS=['ZGVtbw==','ZHVtbXk=','c2FtcGxl','c3VtaXRh','c29iaXRh','dGVzdCBwYXRpZW50','dGVzdCBzdGFmZg=='].map(x=>atob(x));
const __SEEDED_MOBILES=['888'+'888'+'8885','333'+'333'+'1245','999'+'999'+'9999','123'+'456'+'7890'];
const __SEEDED_WORDS_SET=new Set(__SEEDED_WORDS);
const __SEEDED_MOBILES_SET=new Set(__SEEDED_MOBILES);
const seededWords=()=>__SEEDED_WORDS;
const seededMobiles=()=>__SEEDED_MOBILES;
function seedText(r){return String([r?.name,r?.patientId,r?.remarks,r?.product,r?.customer,r?.disease,r?.address].filter(Boolean).join(' ')).toLowerCase()}
window["seedText"]=seedText;
function isSeededRecord(r){
 // V218 production workflow fix: a mobile number alone must never delete a real clinic entry.
 // Earlier demo cleanup removed 9999999999/1234567890 even when staff used them for live testing,
 // so Save showed success but the row disappeared before local/cloud write.
 // BUG FIX: previously checked a JOINED string of name+remarks+address+etc, which could
 // accidentally form a seed phrase across field boundaries (e.g. a name ending in "Test"
 // followed by remarks starting with "Patient..." joined into "...test patient..." and
 // wrongly matched, silently deleting a real doctor/patient entry). Now each field is
 // checked SEPARATELY so unrelated fields can never combine into a false match.
 if(!r||typeof r!=='object')return false;
 let fields=[r?.name,r?.patientId,r?.remarks,r?.product,r?.customer,r?.disease,r?.address].filter(Boolean).map(f=>String(f).toLowerCase());
 // BUG FIX (Final Stabilization): this used to match via f.includes(w), a
 // SUBSTRING check. That silently deleted any real record whose name (or
 // remarks/address/etc) merely CONTAINED one of these words anywhere inside
 // a longer, legitimate value — e.g. a real patient literally named
 // "Sumita Kumari Das" or "Sobita Rani" (both common real first names in
 // this clinic's service area) would match "sumita"/"sobita" and have
 // their entire record silently filtered out of every load(), making it
 // look like the save failed or the patient vanished. Seed/demo rows were
 // always inserted with the field set to EXACTLY the marker word (e.g.
 // name="Demo"), never as part of a longer real value, so requiring an
 // exact (trimmed) match keeps catching real seed data while no longer
 // matching real patient names that happen to contain these words.
 /* 🔴 V435 (TK-রিপোর্ট ১৮.০৮.২০২৬ — সব পর্দা ধীর)। এই ফাংশনটা **প্রতিটা সারির
    জন্য** চলে, প্রতিটা `load()`-এ। আগে এখানে `mob()` ও `seedText()` **সবসময়**
    চলত, অথচ ওদুটো শুধু দ্বিতীয় শর্তটার জন্য দরকার — আর সেই শর্তে যেতে হলে
    আগে নম্বরটা ওই চারটে ডেমো-নম্বরের একটা হতে হয় (হাজারে একটাও নয়)।
    এখন ঠিক আগের `||` / `&&`-এর ক্রমেই ধাপে ধাপে দেখা হয়, দরকার না হলে
    ভারী কাজটা আর করা হয় না। শব্দ মেলানোও এখন তালিকা(Set) ধরে — একই সাতটা শব্দ।
    ⛔ উত্তর হুবহু আগের মতোই — কোন সারি বাদ যাবে, এক অক্ষরও বদলায়নি। */
 if(fields.some(f=>__SEEDED_WORDS_SET.has(f.trim())))return true;
 let m=mob(r?.mobile||'');
 if(!__SEEDED_MOBILES_SET.has(m))return false;
 let hasClinicMeta=!!(r.createdAt||r.updatedAt||r.createdBy||r.receivedBy||r.registeredBy);
 if(hasClinicMeta)return false;
 let t=seedText(r);
 return (t===''||/^(demo|dummy|sample|test patient|test staff|sumita|sobita)$/i.test(t.trim()));
}
window["isSeededRecord"]=isSeededRecord;
function cleanRows(a){return (Array.isArray(a)?a:[]).filter(x=>!isSeededRecord(x)&&!isSeededRecord(x.record||{}))}
window["cleanRows"]=cleanRows;
async function purgeSeededData(){TABLES.forEach(t=>{let a=rawLoad(t),b=cleanRows(a);if(b.length!==a.length){save(t,b);try{if(sb){let ids=a.filter(x=>!b.includes(x)).map(x=>x.id).filter(Boolean);if(ids.length)sb.from(t).delete().in('id',ids)}}catch(e){}}})}
window["purgeSeededData"]=purgeSeededData;

const fileData=inp=>new Promise(res=>{
 let f=inp?.files?.[0];
 if(!f)return res('');
 if(!String(f.type||'').startsWith('image/')){toast('Please select an image');return res('')}
 let r=new FileReader();
 r.onerror=()=>res('');
 r.onload=()=>{
  let raw=String(r.result||'');
  // V161 registration-photo safe fix: compress every camera/gallery photo hard enough
  // so even large photos do not block Patient Registration save.
  let img=new Image();
  img.onload=()=>{
   try{
    let max=520, w=img.width||max, h=img.height||max;
    if(w>h&&w>max){h=Math.round(h*max/w);w=max}else if(h>=w&&h>max){w=Math.round(w*max/h);h=max}
    let c=document.createElement('canvas'), ctx=c.getContext('2d');
    let out='';
    for(let attempt=0;attempt<6;attempt++){
     c.width=w;c.height=h;ctx=c.getContext('2d');ctx.drawImage(img,0,0,w,h);
     let quality=Math.max(0.34,0.68-(attempt*0.08));
     out=c.toDataURL('image/jpeg',quality);
     if(out.length<=160000)break;
     w=Math.max(220,Math.round(w*0.82));h=Math.max(220,Math.round(h*0.82));
    }
    if(out&&out.length>180000)toast('Photo auto-compressed for safe save');
    res(out||'');
   }catch(e){
    // Photo error must never stop registration. Return blank photo safely.
    res('');
   }
  };
  img.onerror=()=>res('');
  img.src=raw;
 };
 r.readAsDataURL(f);
});
