function withMeta(t,r,isNew=false){
 let now=new Date().toISOString(),x={...(r||{})};
 if(isNew&&!x.createdAt)x.createdAt=now;
 if(!x.updatedAt)x.updatedAt=now;
 if(user?.mobile&&!x.createdBy&&(isNew||['enquiries','patients','followups','medical','payments','products','doctor_visits','briefings'].includes(t)))x.createdBy=user.mobile;
 if(user?.mobile&&!x.receivedBy&&t==='enquiries')x.receivedBy=user.mobile;
 if(user?.mobile&&!x.registeredBy&&t==='patients')x.registeredBy=user.mobile;
 if(user?.mobile&&!x.receivedBy&&t==='payments')x.receivedBy=user.mobile;
 return x;
}
