const normalizeCloudRows=rows=>(Array.isArray(rows)?rows:[]).map(normalizeCloudRow);
function ensureSupabaseSdk(){
 if(window.supabase)return Promise.resolve(true);
 if(!C.supabaseUrl||!C.supabaseKey)return Promise.resolve(false);
 if(window.__RK_SUPABASE_LOADING)return window.__RK_SUPABASE_LOADING;
 window.__RK_SUPABASE_LOADING=new Promise(res=>{
  try{
   let done=false;
   let finish=v=>{if(done)return;done=true;res(v)};
   let sc=document.createElement('script');
   sc.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';
   sc.async=true;
   sc.onload=()=>finish(!!window.supabase);
   sc.onerror=()=>finish(false);
   document.head.appendChild(sc);
   setTimeout(()=>finish(!!window.supabase),4500);
  }catch(e){res(false)}
 });
 return window.__RK_SUPABASE_LOADING;
}
window["ensureSupabaseSdk"]=ensureSupabaseSdk;

