/* 🔒 V235 (TK, Ghost Record — web permanence): কম্পিউটারের অ্যাপ (web) এতদিন
   deleted_records tombstone টেবিলে **লিখত** কিন্তু কখনো **পড়ত না** — শুধু
   cloud-authoritative mode-এর ভরসায় মুছে-ফেলা রেকর্ড আড়াল করত। এখন ফোনের
   (DeletedGuard.isDeleted) মতোই web-ও tombstone মেনে চলে: প্রতি pull-এ একটিমাত্র
   bulk অনুরোধে deleted_records-এর id-গুলো নামিয়ে (প্রতি record আলাদা অনুরোধ নয় —
   Free Plan-এ বাড়তি চাপ নেই), merge-এর পরে ওই মুছে-ফেলা সারিগুলো বাদ দেওয়া হয়।
   ফলে productionCloudAuthoritative flag বন্ধ থাকলেও মুছে-ফেলা রেকর্ড আর কোনোভাবে
   ফিরে আসতে পারে না। fail-open: tombstone পড়া ব্যর্থ হলে আগের আচরণই (কিছু বাদ যায় না)। */
let wlv1WebDeletedSet=new Set();
async function wlv1WebSyncDeleted(){
  try{
    if(!sb)return;
    /* 🔵🔒 V441 (19.08.2026, TK-অনুমোদিত): আগে `limit(5000)`-এর পরে থাকা
       tombstone কখনো নামত না। এখন ছোট 1000-row page ধরে **সব** id পড়ে। কোনো
       page ব্যর্থ হলে নতুন অসম্পূর্ণ Set বসানো হয় না — আগের নিরাপদ Set-ই থাকে। */
    const pageSize=1000, ids=[];
    for(let from=0;;from+=pageSize){
      let {data,error}=await sb.from('deleted_records').select('id').order('id',{ascending:true}).range(from,from+pageSize-1);
      if(error||!Array.isArray(data))return;
      data.forEach(x=>{if(x&&x.id!=null)ids.push(String(x.id))});
      if(data.length<pageSize)break;
    }
    wlv1WebDeletedSet=new Set(ids);
  }catch(e){}
}
function wlv1WebNotDeleted(t,rows){
  try{
    if(!wlv1WebDeletedSet||!wlv1WebDeletedSet.size)return rows;
    return (rows||[]).filter(r=>!(r&&r.id&&wlv1WebDeletedSet.has(String(t)+'|'+String(r.id))));
  }catch(e){ return rows; }
}
window["wlv1WebNotDeleted"]=wlv1WebNotDeleted;
function unsyncedLocalRowsForCloudReset(t,remoteRows){
 // V219 production candidate fix:
 // If staff saves a row before Supabase SDK/background init finishes, the first cloud pull must NOT wipe it.
 // Earlier V217/V218 reset local data from cloud immediately; a new Enquiry saved during that window disappeared
 // from list/search and never reached Supabase. Keep only truly new local rows created after this app boot.
 try{
  let remoteIds=new Set((Array.isArray(remoteRows)?remoteRows:[]).map(r=>r&&r.id).filter(Boolean));
  let bootTime=Number(window.__RK_APP_BOOT_TIME||Date.now());
  return cleanRows(rawLoad(t)).filter(r=>r&&r.id&&!remoteIds.has(r.id)&&rowStamp(r)>=bootTime);
 }catch(e){return []}
}
window["unsyncedLocalRowsForCloudReset"]=unsyncedLocalRowsForCloudReset;
function resetLocalTableFromCloud(t,rows){
 // Supabase is the source of truth, but local rows created in the current boot and not yet pushed are protected.
 try{
  let remote=normalizeTableRows(t,cleanRows(rows||[]));
  let keep=mergeById(unsyncedLocalRowsForCloudReset(t,remote),protectedRows(t));
  let merged=normalizeTableRows(t,mergeById(remote,keep));
  RAM_STORE[t]=merged;
  /* 🔴 V918 — জমা-ঘরে জায়গা না থাকলেও এই সারিগুলো যেন হারিয়ে না যায়:
     লেখা ব্যর্থ হলে টেবিলটা RAM-ভিত্তিক ধরা হয় (উপরের `RAM_ONLY` টীকা),
     আর পুরো কাজটা আগের মতোই সফল ধরা হয় — নইলে এখানেই থেমে যেত। */
  try{ localStorage.setItem('rk_'+t,JSON.stringify(stripLargePhotos(RAM_STORE[t]))); wlv1RamOnlyClear(t); }
  catch(_e){ try{ emergencyPhotoStorageCleanup(); localStorage.setItem('rk_'+t,JSON.stringify(stripLargePhotos(RAM_STORE[t]))); wlv1RamOnlyClear(t); }catch(__e){ wlv1RamOnlyMark(t); } }
  if(!keep.length)clearPendingCloud(t); else markPendingCloud(t);
  return true
 }catch(e){return false}
}
window["resetLocalTableFromCloud"]=resetLocalTableFromCloud;
function startCloudVisibilityLoop(reason=''){
 // V195 selective safe fix: any staff entry must become visible to all staff of the same branch.
 // Only cloud pull/merge is strengthened; UI/design/workflow/role rules are not changed.
 try{
  if(!sb||!user)return false;
  /* 🟢🔒 V399 (TK-অনুমোদিত): আগে এখানে `true` (force) ছিল — অর্থাৎ **প্রতিবার
     অ্যাপ/পাতা খুললেই** সব টেবিল পুরো নামত, ৬০ মিনিটের নিয়ম মানত না। এটাই
     সবচেয়ে বড় খরচের কারণ ছিল। এখন সাধারণ পড়া — ৬০ মিনিটের নিয়ম মানে, আর
     শুধু নতুন/বদলানো সারি আনে। ⛔ "Sync Now" ও রাত ২টার সিঙ্ক আগের মতোই
     force=true নিয়ে চলে, তাই সেখানে কিছুই বদলায়নি। */
  pullCloudAllForVisibility(reason||'start', false);
  // LOCAL-FIRST: the old every-15-seconds full cloud pull is removed (it was
  // constantly downloading the whole database and draining the free quota).
  // Daytime = local only. Cloud sync now happens on app start (once above),
  // automatically at 2 AM each night, and whenever the user taps "Sync Now".
  startNightlyCloudSync();
  // 🔴🔒 V462 (20.08.2026, TK-অনুমোদিত — Web live-refresh, ধাপ ১ শুধু
  // Payment) — Android-এর LiveRefresh.Watch-এর একই দর্শনে, কিন্তু ওয়েবে
  // ইতিমধ্যে-প্রমাণিত `wlv1PaymentCloudPull()` পুনর্ব্যবহার করে (নতুন কোনো
  // fetch/merge লজিক লেখা হয়নি) — এই ফাংশনটার নিজস্ব ৪৫-সেকেন্ড থ্রটল
  // আগে থেকেই আছে, তাই বারবার ডাকা সম্পূর্ণ নিরাপদ।
  startPaymentLiveRefresh();
  startQueueLiveRefresh();
  startFollowUpLiveRefresh();
  return true;
 }catch(e){return false}
}
window["startCloudVisibilityLoop"]=startCloudVisibilityLoop;
// LOCAL-FIRST nightly sync: once a day around 2 AM, push anything saved on this
// phone up to the cloud and pull everyone else's latest down. Runs quietly.
function startNightlyCloudSync(){
 if(window.__RK_NIGHTLY_TIMER)return;
 window.__RK_NIGHTLY_TIMER=setInterval(async()=>{
  try{
   if(!sb||!user)return;
   let d=new Date(), dayKey=d.toISOString().slice(0,10);
   if(d.getHours()===2 && window.__RK_LAST_NIGHTLY!==dayKey){
    window.__RK_LAST_NIGHTLY=dayKey;
    /* 🔵🔒 V451 EGRESS-SAFE (19.08.2026, TK-approved):
       Daily 2 AM must NOT full-push all tables. On ordinary nights only rows/tables
       that are actually pending are pushed. Once every 7 days the existing full
       safety sync is intentionally kept, so a missed local pending marker can still
       be recovered without paying the full-database cost every single night. */
    const __weeklySafety=wlv1NeedWeeklyFull();
    await flushPendingCloud(__weeklySafety ? undefined : 'pending');
    await pullCloudAllForVisibility('nightly-2am', true);
   }
  }catch(e){}
 },60000);
}
window["startNightlyCloudSync"]=startNightlyCloudSync;

