// storage-এ টেনে আনা হয়, তারপর `followup(tab)` আবার ডাকা হলে সেই একই
// পুরনো, প্রমাণিত `followStats()`-ই নতুন ডেটা থেকে সঠিক তালিকা বানায়।
// ⛔ **যাচাই করা ঝুঁকি ও সুরক্ষা:** এই পাতায় একটামাত্র `<input>` আছে
//    (Search বক্স, `wlv1FuSearch`) — কেউ তাতে টাইপ করা অবস্থায় থাকলে
//    রিফ্রেশ তার লেখা মুছে দিতে পারত। তাই সার্চ-বক্স ফাঁকা না থাকলে এই
//    সাইকেলে রিফ্রেশ **এড়িয়ে যাওয়া হয়** (পরের ৩০ সেকেন্ডে আবার চেষ্টা)।
// ⛔ "Enquiry"/"Registration" মূল বোতাম আসলে **তৈরি-করার ফর্ম**
//    (`enquiryForm()`/`registration()` — অনেক `<input>`, নাম/মোবাইল/
//    ঠিকানা টাইপ করা হয়) — সেখানে অটো-রিফ্রেশ বসালে টাইপ-করা তথ্য মোছার
//    সত্যিকারের ঝুঁকি থাকত, তাই **ইচ্ছাকৃতভাবে সেখানে যোগ করা হয়নি**।
let __wlv1FuPullAt=0;
async function wlv1FollowUpCloudPull(){
  try{
    if(Date.now()-__wlv1FuPullAt<45000) return false;
    __wlv1FuPullAt=Date.now();
    let ok=false; try{ ok=await initCloudClientOnly(); }catch(e){ ok=false; }
    if(!ok||!sb) return false;
    // গত ৩ ঘণ্টায় বদলানো সারি — পুরো টেবিল না, খরচ বাঁচাতে।
    const since=new Date(Date.now()-3*3600*1000).toISOString();
    const grab=async(table)=>{
      /* 🖼️🔒 V493 (TK-নির্দেশ ৪): আগে select('*') ছিল — অর্থাৎ প্রতি ৪৫ সেকেন্ডে
         গত ৩ ঘণ্টায় বদলানো সব সারি **রোগীর base64 ছবি-সহ** নামত, অথচ এই pull
         শুধু তালিকা তাজা রাখে, ছবি দেখায় না। এখন ছবি-ছাড়া ঘর।
         ⛔ mergeById field-wise ({...a,...r}) — তাই আগে থেকে জমা ছবি মুছবে না। */
      /* 🔴 V579 — টেবিলটার (গোটা) সই না বদলালে এই তিন-ঘণ্টার তালিকাটাও
         নামানোর দরকার নেই। ⛔ সই দেখা হয় **ছাঁকনি ছাড়া** — কারণ তিন ঘণ্টার
         জানলাটা প্রতিবার একটু করে সরে, তাই ছাঁকনি-সহ সই মিথ্যে "বদলেছে"
         দেখাত। ছাঁকনি ছাড়া সই স্থির: সত্যিই কেউ কিছু বদলালে তবেই এগোয়। */
      try{ if(await wlv1CloudUnchanged('fu|'+table, table, null)) return null;
           const __c=(typeof RT_NO_PHOTO_COLS!=='undefined'&&RT_NO_PHOTO_COLS[table])||'*';
           const r=await sb.from(table).select(__c).gte('updatedAt',since).limit(500);
           if(r&&!r.error&&Array.isArray(r.data)){ wlv1SigCommit('fu|'+table); return r.data; }
           return null; }
      catch(e){ return null; }
    };
    const [fu,enq,pt]=await Promise.all([grab('followups'),grab('enquiries'),grab('patients')]);
    let changed=false;
    const put=(t,rows)=>{
      if(!Array.isArray(rows)||!rows.length) return;
      try{
        const one=wlv1WebNotDeleted(t,normalizeCloudRows(rows));
        if(!one||!one.length) return;
        save(t, mergeById([].concat(protectedRows(t),one), load(t)), {skipCloud:true});
        changed=true;
      }catch(e){}
    };
    put('followups',fu); put('enquiries',enq); put('patients',pt);
    return changed;
  }catch(e){ return false; }
}
window["wlv1FollowUpCloudPull"]=wlv1FollowUpCloudPull;

function startFollowUpLiveRefresh(){
 if(window.__RK_FOLLOWUP_LIVE_TIMER) return;
 window.__RK_FOLLOWUP_LIVE_TIMER=setInterval(async()=>{
  try{
   if(!sb||!user) return;
   if(String(currentView||'')!=='Follow-up') return;
   const h=new Date().getHours();
   if(h>=22 || h<6) return;
   const changed=await wlv1FollowUpCloudPull();
   // 🔴🔒 V482 — `wlv1FuRedraw()` ব্যবহার করা হচ্ছে (পুরো পাতা না) — এটা
   // শুধু তালিকার বাক্স (#followRows) renew করে, সার্চ-বক্সের টাইপ-করা
   // লেখা/কার্সার একটুও ছোঁয় না (এই ফাংশন আগে থেকেই এই কারণে বানানো,
   // মন্তব্য দ্রষ্টব্য: "so the search box keeps focus while typing")।
   if(changed && String(currentView||'')==='Follow-up'){
     wlv1FuRedraw(__wlv1FuCurrentTab);
   }
  }catch(e){}
 },30000);
}
window["startFollowUpLiveRefresh"]=startFollowUpLiveRefresh;

// Manual "Sync Now": staff can push+pull with the cloud any time they choose.
async function syncNow(){
 try{
  if(!sb){toast('Cloud not ready — try again in a moment');return;}
  /* 🔵🔒 V495: "Sync Now" মানে স্টাফ **নিজে** টাটকা তথ্য চাইছেন — তাই জমানো
     উত্তর (২০ সেকেন্ডের dedupe) আগে মুছে ফেলা হয়, যাতে সবকিছু সত্যিই নতুন
     করে আসে। ⛔ অন্য কোনো নিয়ম বদলায়নি। */
  try{ if(typeof wlv1DedupeClear==='function') wlv1DedupeClear(); }catch(_e){}
  toast('Syncing with cloud…');
  /* 🔵🔒 V452 WORKING FIX (19.08.2026, TK-approved, Free Plan safety):
     Repeated manual Sync Now must not re-download/re-upload the whole database.
     Normally it now sends only genuinely pending work and pulls only rows changed
     since the last successful sync. Changed photo rows are still fetched with
     their photo, so the visible result stays current. The existing 7-day safety
     reconciliation is preserved: when it is due, this same button performs one
     full push+pull and records that full pass. No table/schema/workflow change. */
  const __manualFull=wlv1NeedWeeklyFull();
  await flushPendingCloud(__manualFull ? undefined : 'pending');
  // V352: one small medicine-default refresh after the normal cloud client is
  // ready. It uses its own local cache and never delays a Prescription screen.
  try{await rxDefaultsRefreshFromCloud(true,true)}catch(_e){}
  await pullCloudAllForVisibility(__manualFull?'manual-sync-full':'manual-sync-delta', true);
  toast('Sync complete ✓');
  try{ if(String(currentView||'').toLowerCase().includes('dashboard'))dashboard(); }catch(_e){}
 }catch(e){ toast('Sync failed — your data is safe on this phone, will retry'); }
}
window["syncNow"]=syncNow;

/* ============================================================================
   🔵🔒 V950 (০১.০৯.২০২৬, TK-নির্দেশ: *"Sync Now এটা কম্পিউটারে উপরের রিফ্রেশ
   বোতাম ক্লিক করলে যেন হয়ে যায়"* — ব্রাউজারের নিজের রিফ্রেশ বোতাম/F5)
   ----------------------------------------------------------------------------
   **আগে কী হত:** ব্রাউজার রিফ্রেশে অ্যাপ শুধু *জমে থাকা* কাজ পাঠাত আর সাধারণ
   (delta) পড়া করত — "Sync Now"-এর মতো পূর্ণ সিঙ্ক হত না। তাই ডেটাবেসে হাতে
   বদলানো কিছু (যেমন আজকের পেশেন্ট-কোড শোধরানো) সঙ্গে সঙ্গে দেখা যেত না।

   **এখন:** পাতা রিফ্রেশ/নতুন করে খোলা হলে ঠিক `syncNow()`-ই চলে।

   ⚠️ TK-কে আগে ঝুঁকিটা বলা হয়েছিল (প্রতিবার পূর্ণ সিঙ্ক = বেশি খরচ), TK
      জেনেই নির্দেশ দিয়েছেন। তাই খরচ যেন হাতছাড়া না হয়, দুটো পাহারা রাখা হলো:
        ১) পরপর রিফ্রেশ চাপলে **২ মিনিটে একবারের বেশি** নয়
        ২) লগইন না থাকলে বা নেট না থাকলে কিছুই হয় না
   ⛔ `syncNow()`-এর ভিতরে এক অক্ষরও বদলায়নি — সেই প্রমাণিত ফাংশনটাই ডাকা হয়
      (তার নিজের সাপ্তাহিক-পূর্ণ/delta নিয়মও অটুট)।
   ⛔ ফোনের অ্যাপে কিছুই বদলায়নি — এটা শুধু ব্রাউজারের জন্য।              */
async function wlv1SyncOnBrowserRefresh(){
  try{
    if(!user) return false;
    if(typeof navigator!=='undefined' && navigator.onLine===false) return false;
    var KEY='rk_refresh_sync_at';
    var last=0; try{ last=Number(localStorage.getItem(KEY)||0) }catch(_e){ last=0 }
    if(Date.now()-last < 2*60*1000) return false;
    try{ localStorage.setItem(KEY,String(Date.now())) }catch(_e){}
    var ok=await initCloudClientOnly();
    if(!ok||!sb) return false;
    await syncNow();
    return true;
  }catch(e){ return false }
}
window["wlv1SyncOnBrowserRefresh"]=wlv1SyncOnBrowserRefresh;
(function wlv1RefreshSyncInstall(){
  try{
    if(window.__WLV1_REFRESH_SYNC) return;
    window.__WLV1_REFRESH_SYNC = true;
    /* লগইন হওয়া ও ক্লাউড তৈরি হওয়ার একটু সময় দেওয়া হয়, নইলে খুব আগে ডেকে
       নিঃশব্দে ফিরে আসত। ⛔ পর্দা আঁকা আটকায় না (setTimeout-এ)। */
    setTimeout(function(){ wlv1SyncOnBrowserRefresh(); }, 2500);
  }catch(e){}
})();

/* ============================================================================
   🟢🔒 V399 (16.08.2026, TK-অনুমোদিত: "হ্যাঁ, কাজ শুরু করুন, তবে খুব সাবধানে")
   — Supabase Egress কমানো: **শুধু নতুন/বদলানো তথ্য নামবে** (delta sync)
     আর প্রথমবারের পূর্ণ পড়া **পাতা-ধরে-পাতা** হবে (limit 2000-এ আর আটকাবে না)।

   কেন দরকার (মাপা তথ্য, 16.08.2026):
     • Egress ২.০৪/৫ GB · দিনে ~০.৭ GB · ৯৯.৯% PostgREST (ডেটাবেস পড়া)
     • অথচ পুরো ডেটাবেস মাত্র ১০২ MB ⇒ একই তথ্য বারবার নামছে
     • `followups`-এ ৩২৭৩ সারি, কিন্তু পুরনো কোড `limit(2000)` ⇒ **১২৭৩টি
       ফলো-আপ ওয়েব কোনোদিন নামাত না** (নতুন ব্রাউজারে দেখাই যেত না)।

   TK-এর CSV প্রমাণে (16.08.2026 · 02:20 PM IST) যাচাই হয়েছে: ৯টি টেবিলের
   একটি সারিতেও `updatedAt` ফাঁকা নেই ⇒ delta নিরাপদ। শুধু `trash`-এ ঘরটাই
   নেই (১৮১ সারি) ⇒ ওটা আগের মতোই পুরোটাই নামে।

   সুরক্ষা (একটিও বাদ দেওয়া হয়নি):
     ১. এই ব্রাউজারে টেবিল ফাঁকা হলে → **পূর্ণ** পড়া (ছবি সহ)
     ২. রাত ২টার সিঙ্ক ও "Sync Now" → **পূর্ণ** পড়া (আগের হুবহু নিয়ম)
     ৩. delta পড়া ব্যর্থ হলে → সঙ্গে সঙ্গে পূর্ণ পড়া, তারপর দরকারে পুরনো
        `select('*').limit(2000)` পথ — কখনো চুপচাপ পুরনো তথ্য নিয়ে বসে থাকে না
     ৪. ঘড়ির ভুল সামলাতে delta সবসময় **১ দিন পিছিয়ে** ধরে
     ৫. delta-র সময় স্থানীয় সারি **কখনো মোছা হয় না** (শুধু নতুনগুলো বসে);
        মুছে-ফেলা সারি আগের মতোই tombstone (`wlv1WebNotDeleted`) দিয়ে বাদ যায়
   ============================================================================ */
const WLV1_SYNC_SINCE_KEY='rk_sync_since';
const WLV1_PAGE=1000;                       /* এক ডাকে সর্বোচ্চ সারি */
const WLV1_PAGE_GUARD=60;                   /* সর্বোচ্চ ৬০×১০০০ = ৬০,০০০ সারি */
const WLV1_DELTA_OVERLAP_MS=24*60*60*1000;  /* ১ দিন পিছিয়ে (ঘড়ির ভুল সামলাতে) */
const WLV1_NO_STAMP_TABLES=['trash'];       /* যে টেবিলে `updatedAt` ঘরটাই নেই */
/* 🔵🔒 V451 TRASH-ON-DEMAND (19.08.2026, TK-approved):
   `trash.record`-এ সম্পূর্ণ deleted snapshot (ছবি-সহ) থাকে এবং `updatedAt` নেই।
   তাই login / nightly / manual bulk pull / realtime-এ Trash টানা হবে না।
   Master Trash Bin খুললেই একবার cloud-authoritative refresh হবে; Restore/Delete
   করার ঠিক আগেও ঐ এক Trash id cloud থেকে verify করা হবে। SQL/schema বদল নেই। */
const WLV1_ON_DEMAND_CLOUD_TABLES=['trash'];
function wlv1IsOnDemandCloudTable(t){ return WLV1_ON_DEMAND_CLOUD_TABLES.indexOf(String(t||''))>=0; }
window["wlv1IsOnDemandCloudTable"]=wlv1IsOnDemandCloudTable;
/* 🔵🔒 V418 (Egress): সপ্তাহে একবার পুরোটা মিলিয়ে নেওয়ার হিসাব।
   ⛔ মনে-রাখা তারিখ নষ্ট/ফাঁকা হলে **পূর্ণ পড়াই** ধরা হয় — সন্দেহ হলে বেশি
      পড়া হবে, কম নয়। তাই কোনো অবস্থাতেই তথ্য পিছিয়ে থাকার ভয় নেই। */
const WLV1_FULL_EVERY_DAYS=7;
const WLV1_LAST_FULL_KEY='rk_last_full_sync';
function wlv1NeedWeeklyFull(){
  try{
    var v=localStorage.getItem(WLV1_LAST_FULL_KEY)||'';
    var at=Number(v);
    if(!v||!isFinite(at)||at<=0) return true;
    return (Date.now()-at) > WLV1_FULL_EVERY_DAYS*24*60*60*1000;
  }catch(e){ return true; }
}
function wlv1MarkFullSync(){ try{ localStorage.setItem(WLV1_LAST_FULL_KEY,String(Date.now())); }catch(e){} }
function wlv1SinceMap(){ try{ return JSON.parse(localStorage.getItem(WLV1_SYNC_SINCE_KEY)||'{}')||{}; }catch(e){ return {}; } }
function wlv1SinceGet(t){ try{ return String(wlv1SinceMap()[t]||''); }catch(e){ return ''; } }
function wlv1SinceSet(t,iso){ try{ var m=wlv1SinceMap(); m[t]=String(iso||''); localStorage.setItem(WLV1_SYNC_SINCE_KEY,JSON.stringify(m)); }catch(e){} }
function wlv1MaxUpdatedAt(rows){
  var best='';
  (rows||[]).forEach(function(r){ var v=String((r&&r.updatedAt)||''); if(v>best) best=v; });
  return best;
}
/* পাতা-ধরে-পাতা পড়া। sinceIso দিলে শুধু তার পরে বদলানো সারি। */
async function wlv1FetchPaged(ct,sel,sinceIso,noStamp){
  var out=[],from=0;
  for(var i=0;i<WLV1_PAGE_GUARD;i++){
    var q=sb.from(ct).select(sel);
    if(sinceIso&&!noStamp) q=q.gt('updatedAt',sinceIso);
    q=noStamp ? q.order('id',{ascending:true})
              : q.order('updatedAt',{ascending:true,nullsFirst:true});
    var r=await q.range(from,from+WLV1_PAGE-1);
    if(r&&r.error) return {error:r.error,rows:out};
    var d=(r&&Array.isArray(r.data))?r.data:[];
    out=out.concat(d);
    if(d.length<WLV1_PAGE) break;
    from+=WLV1_PAGE;
  }
  return {error:null,rows:out};
}
/* 🔴🔒 V494 (২১.০৮.২০২৬, TK-যাচাই ৪) — **ব্যর্থতার আসল কারণ চেনা।**
   V493-এ সরু পড়া ব্যর্থ হলেই **হুবহু একই query আবার** পাঠানো হত, তারপর
   select('*')। একই query দ্বিতীয়বার পাঠিয়ে কোনো লাভ নেই — নেট খারাপ থাকলে
   সেটাও ব্যর্থ হয়, শুধু একটা বাড়তি অনুরোধ খরচ হয়।
   এখন কারণ দেখে সিদ্ধান্ত: ঘরের নাম ভুল হলে (PostgREST 42703 / "column")
   তবেই select('*') — কারণ তখন ওটাই সত্যিই কাজে দেয়। নেট-সমস্যা হলে আর
   চেষ্টা নয়; পুরনো local তথ্য অটুট থাকে ও পরে নিজে থেকেই আবার চেষ্টা হয়। */
function wlv1IsColumnError(err){
  try{
    if(!err) return false;
    if(String(err.code||'')==='42703') return true;
    var m=String(err.message||err.msg||err.details||'').toLowerCase();
    return m.indexOf('column')>=0 || m.indexOf('does not exist')>=0 || m.indexOf('unknown field')>=0;
  }catch(e){ return false; }
}
window["wlv1IsColumnError"]=wlv1IsColumnError;
/* এক টেবিল পড়া — full নাকি delta, সেটা এখানেই ঠিক হয়।
   🔵🔒 V418 (Egress — TK-এর Supabase কোটা পেরিয়ে যাওয়ার পর ধরা পড়েছে):
   আগে রাত ২টার সিঙ্কে **প্রতিটা কম্পিউটার পুরো ডেটাবেস ছবি সহ আবার নামাত**
   (~২০ MB × প্রতিটা যন্ত্র × প্রতি রাত)। এখন `photoDelta` দিলে ছবি আসে ঠিকই,
   কিন্তু **শুধু যে সারিগুলো বদলেছে সেগুলোর** — তাই ছবি আগের চেয়ে তাড়াতাড়ি
   আসে, অথচ খরচ প্রায় শূন্য।
   ⛔ `forceFull` (Sync Now / প্রথমবার / সপ্তাহের পূর্ণ মিল) আগের হুবহু নিয়মেই চলে। */
async function wlv1CloudRead(ct,t,forceFull,photoDelta){
  var narrow=RT_NO_PHOTO_COLS[ct];
  var localCount=(load(t)||[]).length;
  var noStamp=WLV1_NO_STAMP_TABLES.indexOf(ct)>=0;
  var wantPhoto=(!narrow)||localCount===0||!!forceFull||!!photoDelta;
  var sel=wantPhoto?'*':narrow;
  var since='';
  if(!forceFull && !noStamp && localCount>0){
    var last=wlv1SinceGet(t);
    if(last){
      var back=new Date(Date.parse(last)-WLV1_DELTA_OVERLAP_MS);
      if(!isNaN(back.getTime())) since=back.toISOString();
    }
  }
  var res=await wlv1FetchPaged(ct,sel,since,noStamp);
  var isDelta=!!since && !res.error;
  if(res.error && since){ res=await wlv1FetchPaged(ct,sel,'',noStamp); isDelta=false; }
  /* 🔴🔒 V494 (TK-যাচাই ৪): V493-এ এখানে ছবি-ছাড়া ঘর দিয়ে **আবার** পড়া হত —
     কিন্তু উপরের লাইনটাই ঠিক ওই একই ঘর (sel === RT_NO_PHOTO_COLS) দিয়ে পড়ে
     ফেলেছে, তাই ওটা ছিল নিছক ডুপ্লিকেট। সরানো হলো।
     এখন '*' শুধু তখনই, যখন ব্যর্থতার কারণ **ঘরের নাম ভুল** — নেট-সমস্যায় নয়। */
  if(res.error && !wantPhoto && wlv1IsColumnError(res.error)){
    res=await wlv1FetchPaged(ct,'*','',noStamp); isDelta=false;
  }
  /* 🔴🔒 V494 (TK-যাচাই ৪): এই শেষ ভরসাটা আগে **সব ব্যর্থতাতেই** চলত, তাই নেট
     খারাপ থাকলেও ছবিসহ ২০০০ সারি চাওয়া হত — লাভ শূন্য, খরচ অনেক।
     এখন শুধু দুই অবস্থায়: ছবি সত্যিই দরকার (wantPhoto), অথবা ঘরের নাম ভুল।
     নেট-সমস্যা হলে আর চেষ্টা নয় — নিচে res.error ফেরে, ডাকার জায়গা পুরনো
     local তথ্য অটুট রাখে ও পরের বার আবার চেষ্টা করে (V223 §C1 অটুট)। */
  if(res.error && (wantPhoto || wlv1IsColumnError(res.error))){
    var r0=await sb.from(ct).select('*').limit(2000);
    res={error:r0.error,rows:(Array.isArray(r0.data)?r0.data:[])}; isDelta=false;
  }
  if(!res.error){
    var mx=wlv1MaxUpdatedAt(res.rows);
    /* 🔒 V399 সুরক্ষা: কোনো ফোনের ঘড়ি ভুল থাকলে সারিতে **ভবিষ্যতের** সময় বসে
       যেতে পারে। তখন মনে-রাখা বিন্দুটা সামনে লাফিয়ে গিয়ে পরের সারিগুলো বাদ
       পড়ত। তাই এই বিন্দু কখনো "এখন"-এর চেয়ে সামনে যেতে দেওয়া হয় না। */
    var nowIso=new Date().toISOString();
    if(mx && mx>nowIso) mx=nowIso;
    if(!noStamp){
      if(!isDelta) wlv1SinceSet(t, mx || nowIso);
      else if(mx) wlv1SinceSet(t, mx);
    }
  }
  return {error:res.error,rows:res.rows,isDelta:isDelta};
}
