function pgMissingColumnName(err){
 let msg=String(err?.message||err?.details||err||'');
 let m=msg.match(/column\s+"?([A-Za-z0-9_]+)"?\s+(?:of relation\s+"?[A-Za-z0-9_]+"?\s+)?does not exist/i)||msg.match(/Could not find the '([^']+)' column/i);
 return m?m[1]:'';
}
window["pgMissingColumnName"]=pgMissingColumnName;
const CLOUD_REQUIRED_COLS={
 enquiries:['id','branch','mobile','name','date'],patients:['id','branch','mobile','name','date'],payments:['id','branch','mobile','date','amount'],followups:['id','branch','mobile','stage'],medical:['id','patientId','type'],products:['id'],doctor_visits:['id'],doctor_visits:['id'],doctor_visits:['id'],briefings:['id'],trash:['id']
};
const cloudTrimMissing=(t,rows,missing)=>{
 let required=new Set(CLOUD_REQUIRED_COLS[t]||['id']);
 return (rows||[]).map(r=>{
  let o={};
  Object.keys(r||{}).forEach(k=>{if(k!==missing||required.has(k))o[k]=r[k]});
  return o;
 });
};
async function cloudUpsertAdaptive(ct,t,rows){
 let payload=rows;
 let missingSeen=new Set();
 for(let attempt=0;attempt<10;attempt++){
  let {error}=await sb.from(ct).upsert(payload,{onConflict:'id'});
  if(!error)return {ok:true};
  let miss=pgMissingColumnName(error);
  if(!miss||missingSeen.has(miss))return {ok:false,error};
  missingSeen.add(miss);
  payload=cloudTrimMissing(t,payload,miss);
 }
 return {ok:false,error:'adaptive retry limit'};
}
window["cloudUpsertAdaptive"]=cloudUpsertAdaptive;
