// পূর্ণ রিফ্রেশ হয় — এটা প্যাচ করার চেয়ে ঝুঁকি বেশি। যেহেতু Delete (এবং তাই
// trash-এন্ট্রি তৈরি) patients/followups এডিটের তুলনায় অনেক কম ঘন ঘন হয়,
// তাই এখানকার আসল Egress-খরচ এমনিতেই কম — তাই এই টেবিল যেমন ছিল তেমনই
// (select='*') রাখা হলো।
const RT_NO_PHOTO_COLS={
 followups:'address,age,branch,callCount,convertedPatientId,createdAt,createdBy,date,disease,history,id,lastCallDate,lastRemark,mobile,name,nextFollow,patientId,refId,registrationDate,sex,stage,status,timeType,updatedAt,visitDate',
 patients:'address,age,bill,branch,complaint,completeApprovedBy,completeRequestedBy,createdAt,createdBy,date,decision,diagnosis,discount,disease,doctorAdvice,doctorComplete,doctorFullNote,id,medicalHistory,mobile,name,occupation,patientId,previousCost,previousResult,previousTreatment,queue,refBy,refDoctor,refDoctorMobile,refundRestoredBy,registeredBy,registrationDate,sex,sinceWhen,stage,timeType,treatmentDuration,updatedAt,visitDate',
 medical:'id,patientId,type,date,selected,days,details,nextFollow,diagnosis,decision,doctorFullNote,name,mobile,branch,createdBy,createdAt,updatedAt'
};
function wireRealtime(){
 try{
  if(!sb||rtWired)return;
  rtWired=true;
  TABLES.forEach(t=>{
   if(wlv1IsOnDemandCloudTable(t)) return; // Trash snapshot is intentionally not streamed; refresh on Trash Bin open
   CLOUD_TABLE_ALIASES(t).forEach(ct=>{
    sb.channel('rt_'+ct).on('postgres_changes',{event:'*',schema:'public',table:ct},(payload)=>{
     // 🟢🔒 B623 (Egress ফিক্স, 11.08.2026, TK-নির্দেশ) — Supabase Free-plan egress-এর
     //   মূল খরচ ছিল এখানেই: আগে **যেকোনো একজন কিছু সেভ করলেই** প্রতিটা খোলা কম্পিউটার
     //   ওই পুরো টেবিলের ২০০০ সারি আবার ডাউনলোড করত। কিন্তু live-মেসেজেই (payload.new)
     //   যে সারিটা বদলেছে সেটা **ফ্রি-তে চলে আসে** — তাই এখন শুধু ওই এক সারিটাই লোকাল
     //   ক্যাশে বসানো হয়, নতুন কোনো ডাউনলোড নেই (egress ~০, ~৯৫%+ কম)।
     //   ⛔ নিরাপত্তা: (১) mergeById শুধু ওই এক id আপডেট/যোগ করে — বাকি সব রোগী/তথ্য
     //      অটুট। (২) protectedRows আগে বসে, তাই এই ফোনে সদ্য-করা (unsynced) এডিট
     //      কখনো চাপা পড়ে না। (৩) মোছা (DELETE) হলে id ধরে বাদ। (৪) init/nightly/
     //      manual পূর্ণ-sync আগের মতোই চলে (throttled) — কোনো ইভেন্ট মিস হলেও পরের
     //      sync ধরে নেয়, তাই তথ্য কখনো হারায় না। ⛔ RT_NO_PHOTO_COLS আর লাগে না (কোনো
     //      re-fetch নেই); রেখে দেওয়া হলো, ভবিষ্যতে দরকার হলে।
     try{
      var ev=payload&&payload.eventType;
      if(ev==='DELETE'){
       var oldId=payload.old&&payload.old.id;
       if(oldId){var cur=load(t)||[];var next=cur.filter(function(r){return !(r&&String(r.id)===String(oldId));});if(next.length!==cur.length){save(t,next,{skipCloud:true});refreshDashboardSoft();}}
       return;
      }
      var raw=payload&&payload.new;
      if(!raw||!raw.id)return;
      var one=wlv1WebNotDeleted(t,normalizeCloudRows([raw]));   // camelCase-এ আনা + tombstone বাদ
      if(!one||!one.length)return;
      var merged=mergeById([].concat(protectedRows(t),one),load(t)); // protected আগে → সদ্য এডিট চাপা পড়ে না
      save(t,merged,{skipCloud:true});
      refreshDashboardSoft();
     }catch(e){}
    }).subscribe();
   });
  });
 }catch(e){}
}
window["wireRealtime"]=wireRealtime;

/* 🟢 B627 (11.08.2026, TK-নির্দেশ): লগ-আউটের সময় লাইভ সংযোগ (realtime) পরিষ্কার
   বন্ধ করা। আগে লগ-আউট হলেও realtime চ্যানেল চালু থেকে যেত — তাই ট্যাব খোলা
   থাকলে egress চলতেই থাকত। এখন লগ-আউটে সংযোগ বন্ধ; আবার লগইন করলে wireRealtime()
   নিজে থেকে চালু হয় (rtWired=false করা হলো বলে)। ⛔ কোনো ডেটা/লজিক/ফিচার বদলায় না। */
function stopRealtime(){
 try{
  if(sb){
   if(typeof sb.removeAllChannels==='function'){ sb.removeAllChannels(); }
   else if(typeof sb.getChannels==='function' && typeof sb.removeChannel==='function'){
    (sb.getChannels()||[]).forEach(function(ch){ try{ sb.removeChannel(ch); }catch(_e){} });
   }
  }
 }catch(_e){}
 rtWired=false;
}
window["stopRealtime"]=stopRealtime;

/* 🔒 খাতার সারি B168 (TK-এর ৫ নম্বর সন্দেহ): এই সাধারণ Delete-টা **ক্লাউডে
   কিছুই মুছত না** — শুধু এই কম্পিউটার থেকে সরাত, তাই পরের merge-এ রেকর্ডটা
   আবার ফিরে আসতে পারত। ⛔ যাচাই করে দেখা গেছে এই ফাংশনটা এখন কোথাও ব্যবহার
   হয় না (পুরো ফাইলে একটাও কল নেই), তাই আজ কোনো কাজের পথ বদলায়নি — কিন্তু
   ভবিষ্যতে কেউ এটা জুড়ে দিলে যাতে বিপদ না হয়, সেজন্য এখনই ফোনের নিয়মে আনা
   হলো: আগে Trash, তারপর ক্লাউডে সত্যিই মোছা, তারপর এই কম্পিউটার থেকে —
   কোনো ধাপ ব্যর্থ হলে **কিছুই মোছা হয় না**। */
const delSoft=async(t,id)=>{
 if(!isMaster())return toast('Delete only Master Admin');
 let a=load(t),i=a.findIndex(x=>x.id===id);
 if(i<0)return toast('Record not found');
 let rec=a[i];
 let tr={id:wlv1TrashIdFor(t,id),table:t,record:rec,deletedAt:new Date().toISOString(),deletedBy:user.mobile};
 add('trash',tr);
 let okT=false; try{ okT=await directCloudUpsertRow('trash',tr) }catch(e){ okT=false }
 if(!okT)return toast('Trash-এ রাখা গেল না — কিছুই মোছা হয়নি');
 let gone=await wlv1CloudDeleteRow(t,id);
 if(!gone)return toast('Cloud-এ মোছা গেল না — কিছুই মোছা হয়নি');
 a.splice(i,1);save(t,a);
 try{ await wlv1MarkDeletedCloud(t,id) }catch(e){}
 toast('Moved to Trash');dashboard()
};
function toast(s){let el=$('#toast');el.textContent=s;el.style.display='block';setTimeout(()=>el.style.display='none',2600)}
/* V386 — পপ-আপের রঙিন হেডার: অ্যান্ড্রয়েডের `native/PremiumAlert.kt`-এর
   `severityOf()` (লাইন ৫৯-৭৯) ও `iconFor()` (লাইন ৮৪-১১৩) হুবহু নকল।
   ⛔ কোনো পপ-আপের লেখা · বোতাম · কাজ বদলায়নি — শুধু শিরোনামের `<h2>`-তে
      একটা ক্লাস (anSevG/anSevY/anSevR) বসে, যাতে CSS সবুজ/হলুদ/লাল হেডার আঁকে।
   ⛔ `.modalBack`-এর ক্লাস বদলানো হয়নি (নইলে বাইরে চেপে বন্ধ করা ভেঙে যেত)। */
function anSeverityOf(title){
  var t=String(title||''), l=t.toLowerCase();
  if(l.indexOf('request')>=0 || t.indexOf('\u0985\u09a8\u09c1\u09b0\u09cb\u09a7')>=0) return 'Y';
  var R=['delete','delete forever','permanently','reject','remove','final confirmation','restore cloud','sure?'];
  for(var i=0;i<R.length;i++) if(l.indexOf(R[i])>=0) return 'R';
  if(t.indexOf('\u09ae\u09c1\u099b')>=0 || t.indexOf('\u09a7\u09cd\u09ac\u0982\u09b8')>=0) return 'R';
  var Y=['already exists','already in the system','confirm','logout','restore','problem','crash','error','warning','overpay'];
  for(var j=0;j<Y.length;j++) if(l.indexOf(Y[j])>=0) return 'Y';
  if(t.indexOf('\u09ac\u09c7\u09b6\u09bf \u09b9\u09df\u09c7 \u09af\u09be\u099a\u09cd\u099b\u09c7')>=0 || t.indexOf('\u09ac\u09be\u09a4\u09bf\u09b2')>=0) return 'Y';
  if(t.charAt(0)==='\u26a0') return 'Y';
  return 'G';
}
function anDialogIcon(title){
  var t=String(title||''), l=t.toLowerCase(), c=t.charCodeAt(0)||0;
  /* প্রথম অক্ষর ইতিমধ্যেই ইমোজি হলে কিছু যোগ হয় না (PremiumAlert.kt:89-96) */
  if((c>=0xD800&&c<=0xDBFF)||(c>=0x2190&&c<=0x21FF)||(c>=0x2600&&c<=0x27BF)||(c>=0x2B00&&c<=0x2BFF)) return '';
  var M=[['password','\uD83D\uDD11'],['delete','\uD83D\uDDD1\uFE0F'],['restore','\u267B\uFE0F'],['logout','\uD83D\uDEAA'],
         ['photo','\uD83D\uDCF7'],['remark','\uD83D\uDCDD'],['note','\uD83D\uDCDD'],['payment','\uD83D\uDCB0'],['income','\uD83D\uDCB0'],
         ['arrived','\u2705'],['approve','\u2705'],['confirm','\u2705'],['crash','\u26A0\uFE0F'],['error','\u26A0\uFE0F'],['problem','\u26A0\uFE0F'],
         ['branch','\uD83D\uDCCB'],['select','\uD83D\uDCCB'],['call','\uD83D\uDCDE'],['document','\uD83D\uDCC4']];
  if(t.indexOf('\u09ae\u09c1\u099b')>=0) return '\uD83D\uDDD1\uFE0F';
  for(var i=0;i<M.length;i++) if(l.indexOf(M[i][0])>=0) return M[i][1];
  return '\u2139\uFE0F';
}
window["anSeverityOf"]=anSeverityOf;window["anDialogIcon"]=anDialogIcon;
/* ⌨️🔒 V757 (২৭.০৮.২০২৬, TK-নির্দেশ ছবিসহ: "এরকম যেন সাজেস্ট না করে" —
   ফোনে V752-এ করা হয়েছে, কম্পিউটারেও একই নিয়ম দরকার)।

   **আসল অবস্থা (গুনে দেখা):** কম্পিউটারে ২৩৬টা ঘরের মধ্যে মাত্র ১৬টায়
   ব্রাউজারের সাজেশন বন্ধ ছিল। বাকিগুলোয় ব্রাউজার/Google-এর জমানো পুরনো
   লেখা (নাম · নম্বর) ভেসে উঠত — ফোনের সমস্যাটারই কম্পিউটার-রূপ।

   এখন পর্দা বা পপ-আপ আঁকা হলেই ভিতরের সব ঘরে একবার বন্ধ করে দেওয়া হয়।
   ⛔ **পাসওয়ার্ডের ঘর ছোঁয়া হয় না** (`type=password`) — নইলে ব্রাউজারে
      সেভ করা লগইন পাসওয়ার্ড আর আসত না, TK-এর অসুবিধা হত।
   ⛔ **লগইনের নম্বরের ঘরও (`#lm`) বাদ** — একই কারণে।
   ⛔ টাইপ করা · সেভ · কোনো ডিজাইন — কিছুই বদলায় না।
   ⛔ কখনো ব্যতিক্রম ছোড়ে না। */
function wlv1NoSuggest(root){
 try{
  var box=root||document;
  var els=box.querySelectorAll?box.querySelectorAll('input,textarea'):[];
  for(var i=0;i<els.length;i++){
   var e=els[i];
   try{
    if(String(e.type||'').toLowerCase()==='password')continue;
    if(e.id==='lm'||e.id==='lp')continue;
    e.setAttribute('autocomplete','off');
    e.setAttribute('autocorrect','off');
    e.setAttribute('spellcheck','false');
    e.setAttribute('data-lpignore','true');
    e.setAttribute('data-form-type','other');
   }catch(_e){}
  }
 }catch(_e){}
}
window["wlv1NoSuggest"]=wlv1NoSuggest;
/* ⌨️🔴🔒 V774 (২৮.০৮.২০২৬) — **কম্পিউটারেও ঠিক একই ফাঁক ছিল।**

   TK: *"যেকোনো পর্দাতে মোবাইল নাম্বার সাজেস্ট… বেশ কয়েকবার কমপ্লেন করেছি।"*

   **আসল কারণ (ফোনের V774-এর হুবহু একই):** `wlv1NoSuggest()` চলত শুধু পর্দা
   বা পপ-আপ **আঁকার সময়** — অর্থাৎ ওই মুহূর্তে যে ঘরগুলো ছিল কেবল সেগুলোতেই।
   কিন্তু এই অ্যাপে বহু ঘর **পরে** যোগ হয় (➕ Add Medicine · নতুন সারি ·
   তালিকা আঁকার পরে বসা ঘর)। সেগুলোতে সাজেশন-বন্ধ কখনোই পৌঁছাত না।

   **সমাধান:** একটাই `MutationObserver` — পাতায় নতুন ঘর বসলেই সঙ্গে সঙ্গে
   তাকেও বন্ধ করে দেয়। ⛔ শুধু **নতুন বসা অংশটুকুই** দেখা হয়, তাই খরচ নগণ্য।
   ⛔ পাসওয়ার্ড ও লগইনের ঘর আগের মতোই বাদ (ব্রাউজারে সেভ করা পাসওয়ার্ড
      যেন নষ্ট না হয়)। ⛔ পুরোটা try/catch — কিছু ভুল হলেও পাতা ভাঙে না। */
var __wlv1NoSuggestWatching = false;
function wlv1NoSuggestWatch(){
 try{
  if(__wlv1NoSuggestWatching) return;
  if(typeof MutationObserver !== 'function' || !document.body) return;
  __wlv1NoSuggestWatching = true;
  new MutationObserver(function(list){
   try{
    for(var i=0;i<list.length;i++){
     var added = list[i].addedNodes;
     for(var j=0;j<added.length;j++){
      var n = added[j];
      if(!n || n.nodeType !== 1) continue;           // শুধু আসল element
      var tag = String(n.tagName||'').toUpperCase();
      if(tag==='INPUT' || tag==='TEXTAREA'){
       wlv1NoSuggestOne(n);            // নিজেই একটা ঘর
      } else if(n.querySelectorAll){
       // ভিতরে ঘর থাকতে পারে — সেগুলোও

       wlv1NoSuggest(n);
      }
     }
    }
   }catch(_e){}
  }).observe(document.body, {childList:true, subtree:true});
 }catch(_e){}
}
/* একটামাত্র ঘরের জন্য — `wlv1NoSuggest`-এর ভিতরের নিয়ম হুবহু এক। */
function wlv1NoSuggestOne(e){
 try{
  if(String(e.type||'').toLowerCase()==='password')return;
  if(e.id==='lm'||e.id==='lp')return;
  e.setAttribute('autocomplete','off');
  e.setAttribute('autocorrect','off');
  e.setAttribute('spellcheck','false');
  e.setAttribute('data-lpignore','true');
  e.setAttribute('data-form-type','other');
 }catch(_e){}
}
window["wlv1NoSuggestWatch"]=wlv1NoSuggestWatch;
window["wlv1NoSuggestOne"]=wlv1NoSuggestOne;
try{
 if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded', function(){ wlv1NoSuggestWatch(); });
 } else { wlv1NoSuggestWatch(); }
}catch(_e){}

window["toast"]=toast;function modal(html){
      const root=$id('modalRoot'); if(!root)return;
      const hasClose=/closeModal\s*\(|>\s*Close\s*</i.test(String(html||''));
      root.innerHTML=`<div class="modalBack" onclick="if(event.target.className==='modalBack')closeModal()"><div class="modal">${html}${hasClose?'':`<div class="actions"><button class="ghost" onclick="closeModal()">Close</button></div>`}</div></div>`;
      /* 🔴 V436 — পপ-আপের ভিতরের তারিখ-ঘরগুলোতেও একই dd/mm/yyyy ব্যবস্থা */
      try{ wlv1AutoDateBoxes(root); }catch(e){}
      /* ⌨️ V757 — পপ-আপের ঘরগুলোতেও ব্রাউজারের সাজেশন বন্ধ (ফোনের
         PremiumAlert.paint-এর মতোই এক জায়গা থেকে সব পপ-আপ ঢাকে)। */
      try{ wlv1NoSuggest(root); }catch(e){}
      /* শিরোনামে severity-ক্লাস + (দরকার হলে) ইমোজি — অ্যান্ড্রয়েডের নিয়মে */
      try{
        const h=root.querySelector('.modal>h2');
        if(h && !h.classList.contains('anSevG') && !h.classList.contains('anSevY') && !h.classList.contains('anSevR')){
          const raw=h.textContent||'';
          const sv=anSeverityOf(raw);
          h.classList.add('anSev'+sv);
          try{ h.parentNode.classList.add('anSev'+sv); }catch(_e){}
          /* RMP পপ-আপ = অ্যান্ড্রয়েডের `premiumDialogShell` (DoctorVisitActivity.kt:1294)
             — গ্রেডিয়েন্ট নয়, নিরেট #145A32 হেডার ও ১dp #145A32 কিনারা। */
          try{ if(h.classList.contains('anRmp')) h.parentNode.classList.add('anRmp'); }catch(_e){}
          const ic=anDialogIcon(raw);
          if(ic) h.textContent=ic+'  '+raw;
        }
      }catch(e){}
    }
window.modal=modal;function closeModal(){$('#modalRoot').innerHTML=''}
