/* মাস্টারের জন্য ছাঁকনি। কিছু বাছা না-থাকলে `null` ফেরে — মানে "তালিকা নয়,
   বার্তা দেখাও"। স্টাফ/ডাক্তারের সারি অপরিবর্তিত ফেরত যায়। */
function wlv1BranchGate(rows, opt){
  if(!isMaster()) return rows||[];
  var v=wlv1BranchGet();
  if(v==='') return null;
  if(v==='All') return rows||[];
  var pick=(opt&&typeof opt.pick==='function')?opt.pick:function(x){ return (x&&x.branch)||''; };
  /* 🔴🔴🆕🔒 V436 (TK-রিপোর্ট ১৮.০৮.২০২৬, ছবিসহ — *"এন্ড্রয়েড ফোনে দেখাচ্ছে
     কিন্তু ডেক্সটপে দেখাচ্ছে না"*: Jalpaiguri-র রোগী ফোনের CHECK-UP Queue-তে
     আছে, ওয়েবে "No Patient In Queue")।
     **কারণ:** এই ছাঁকনিটা ব্রাঞ্চ **হুবহু অক্ষরে অক্ষরে** মেলাত। ফোনে মেলানো
     সহনশীল (`branch.trim().uppercase()`)। তাই `"Jalpaiguri "` / `"JALPAIGURI"`
     ধরনের ছোট গরমিলে ওয়েবে সারি বাদ পড়ে যেত। এই একটাই ছাঁকনি **অনেকগুলো
     পর্দা** ব্যবহার করে (Doctor Queue সহ), তাই এক জায়গায় ঠিক করলেই সব ঠিক।
     এখন প্রজেক্টের নিজের `sameBranch()` — ব্রাঞ্চ ঠিক লেখা থাকলে ফল আগের
     মতোই, শুধু বানানের গরমিলে আর কেউ বাদ পড়বে না। */
  return (rows||[]).filter(function(x){ return sameBranch(pick(x), v); });
}
window["wlv1BranchGate"]=wlv1BranchGate;
/* "এখনো বাছা হয়নি" অবস্থার বার্তা — খালি সাদা পর্দা যেন কখনো না আসে। */
