var WLV1_REMARK_KEY='wlv1_remark_pending';
function wlv1RemarkPendingRead(){
  try{ var a=JSON.parse(localStorage.getItem(WLV1_REMARK_KEY)||'[]'); return Array.isArray(a)?a:[] }catch(_e){ return [] }
}
function wlv1RemarkPendingWrite(a){ try{ localStorage.setItem(WLV1_REMARK_KEY, JSON.stringify(a||[])) }catch(_e){} }
function wlv1RemarkPendingAdd(m){
  var k=mob(m); if(!k||k.length!==10) return;
  var now=Date.now(), keep=wlv1RemarkPendingRead().filter(function(r){
    return r && r.m!==k && (now-Number(r.t||0)) < 30*24*60*60*1000;
  });
  keep.push({m:k, t:now, n:(followByMobile(k)||{}).name||''});
  wlv1RemarkPendingWrite(keep);
}
window["wlv1RemarkPendingAdd"]=wlv1RemarkPendingAdd;
function wlv1RemarkPendingRemove(m){
  var k=mob(m); if(!k) return;
  wlv1RemarkPendingWrite(wlv1RemarkPendingRead().filter(function(r){ return r && r.m!==k }));
}
