function runWhenIdle(fn,delay=3500){
 try{
  if('requestIdleCallback' in window){requestIdleCallback(fn,{timeout:delay+2500});return}
 }catch(e){}
 setTimeout(fn,delay);
}
window["runWhenIdle"]=runWhenIdle;
function boot(){
 let s=null;try{s=localStorage.getItem('rk_session')}catch(e){}
 // Native-login handoff: LoginActivity (Step 1 of the native rebuild) authenticates
 // natively, then opens this WebView with ?nativeSession=<base64 JSON of the same
 // {mobile,name,branch,role} shape the JS login() already produces>. Picking it up
 // here means staff who logged in on the native screen are not asked to log in a
 // second time just because a screen still lives in the WebView for now.
 try{
  let qp=new URLSearchParams(window.location.search||'');
  let ns=qp.get('nativeSession');
  if(ns){
   let decoded=JSON.parse(decodeURIComponent(escape(atob(ns))));
   if(decoded&&decoded.role){s=JSON.stringify(decoded);localStorage.setItem('rk_session',s)}
  }
 }catch(e){}
 if(s){try{user=JSON.parse(s)}catch(e){try{localStorage.removeItem('rk_session')}catch(_){}}}
 if(user&&!user.role){user=null;try{localStorage.removeItem('rk_session')}catch(e){}}
 try{document.body.classList.add('fastBoot')}catch(e){}
 // Native Dashboard deep-link: ?openModule=enquiry|registration|followup|payment|doctorvisit
 // opens straight into that screen instead of the WebView's own Dashboard first.
 let openModule=null;
 try{openModule=new URLSearchParams(window.location.search||'').get('openModule')}catch(e){}
 setTimeout(()=>{try{
  if(!user){publicSite();return}
  if(openModule==='enquiry')enquiryForm();
  else if(openModule==='registration')registration({});
  else if(openModule==='followup')followup('Inquiry');
  else if(openModule==='payment')paymentHome();
  else if(openModule==='doctorvisit')doctorVisit('home');
  else dashboard();
 }catch(e){console.error('Boot render failed',e);publicSite()}},0);
 // V249 mobile hard speed fix: public website must not start Supabase/realtime/cleanup on first load.
 // Cloud sync starts only after login and only after the screen becomes usable.
 if(user){startFastCloudSync('boot-fast',1000)}
}
window["boot"]=boot;


function startFastCloudSync(reason='manual',delay=600){
 try{
  if(!user)return;
  setTimeout(()=>{runWhenIdle(async()=>{
   try{
    await initCloudClientOnly();
    if(sb){
     /* 🔵🔒 V451 EGRESS-SAFE (19.08.2026, TK-approved): login/browser refresh
        retries only pending local work. A full-table push here caused every
        refresh/login to read large cloud tables again before upsert. */
     await flushPendingCloud('pending');
     await pullCloudAllForVisibility(reason);
     try{repairBranchWorkflowRows()}catch(_e){}
     startCloudVisibilityLoop(reason);
     try{wireRealtime()}catch(e){}
     try{refreshBriefingsFromCloud().then(()=>{if(currentView==='dashboard')dashboard()})}catch(e){}
    }
   }catch(e){console.warn('Fast cloud sync skipped',e)}
  },800)},delay);
 }catch(e){}
}
window["startFastCloudSync"]=startFastCloudSync;
function playBriefingSoundOnce(){
 try{
  let key='rk_brief_sound_'+today()+'_'+mob(user?.mobile||'');
  if(localStorage.getItem(key))return;
  localStorage.setItem(key,'1');
  let AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
  let ctx=new AC(),osc=ctx.createOscillator(),gain=ctx.createGain();
  osc.frequency.value=880;gain.gain.value=0.04;osc.connect(gain);gain.connect(ctx.destination);osc.start();setTimeout(()=>{try{osc.stop();ctx.close()}catch(e){}},180);
 }catch(e){}
}
window["playBriefingSoundOnce"]=playBriefingSoundOnce;
function notifyBriefingIfNeeded(){try{if(user&&!isMaster()&&activeBriefings().length)playBriefingSoundOnce()}catch(e){}}
window["notifyBriefingIfNeeded"]=notifyBriefingIfNeeded;

/* ============================================================================
   TK-REQUESTED (2026-07-27): "ঘন্টায় যখন কিছু আসে চুপিসারে কেন আসে, notification
   sound কেন হয় না?" -- the same alert the phone app now gives.

   When the number of things waiting for this user goes UP, the computer plays
   the short beep the app already uses and shows a desktop notification. It
   speaks only when the number is higher than the last time it spoke, so the
   same notice never rings twice, and a number going down stays silent.

   What is counted is exactly what the phone's bell counts:
     . unseen briefings meant for this user (already in memory, no cloud call)
     . Master only: pending Backdate / Payment-Edit approval requests
   Nothing is written anywhere, and any failure is swallowed silently -- the
   dashboard must never be held up by this.
   ========================================================================== */
async function wlv1NoticeCount(){
  let c = 0;
  try{ c += activeBriefings().length }catch(e){}
  try{
    if(typeof isMaster==='function' && isMaster() && typeof sb!=='undefined' && sb){
      const grab = async (t)=>{ try{ const {data,error}=await sb.from(t).select('id').eq('status','pending').limit(200); return (!error&&Array.isArray(data))?data.length:0 }catch(e){ return 0 } };
      const [b,e2,r3] = await Promise.all([grab('payment_backdate_requests'), grab('payment_edit_requests'), grab('referral_edit_requests')]);
      c += b + e2 + r3;
    }
  }catch(e){}
  return c;
}
window["wlv1NoticeCount"]=wlv1NoticeCount;
function wlv1NoticeAlert(count,fresh){
  try{
    let AC=window.AudioContext||window.webkitAudioContext;
    if(AC){let ac=new AC(),osc=ac.createOscillator(),g=ac.createGain();osc.frequency.value=880;g.gain.value=0.05;osc.connect(g);g.connect(ac.destination);osc.start();setTimeout(()=>{try{osc.stop();ac.close()}catch(e){}},220)}
  }catch(e){}
  try{
    if(!('Notification' in window)) return;
    const show=()=>{ try{ new Notification('🔔 '+fresh+' new notice',{body:count+' waiting in the bell'}) }catch(e){} };
    if(Notification.permission==='granted') show();
    else if(Notification.permission!=='denied') Notification.requestPermission().then(p=>{ if(p==='granted') show() });
  }catch(e){}
}
window["wlv1NoticeAlert"]=wlv1NoticeAlert;
async function wlv1NoticeWatch(){
  try{
    if(!user) return;
    const key='rk_notice_seen_'+mob(user?.mobile||'');
    const count=await wlv1NoticeCount();
    const last=Number(localStorage.getItem(key)||0);
    if(count>last) wlv1NoticeAlert(count,count-last);
    localStorage.setItem(key,String(count));
  }catch(e){}
}
window["wlv1NoticeWatch"]=wlv1NoticeWatch;

