function logout(){try{localStorage.removeItem('rk_session')}catch(e){}try{stopRealtime()}catch(e){}try{if(window.MOD&&typeof window.MOD.signOut==='function')window.MOD.signOut()}catch(e){}user=null;try{var _s=document.getElementById('wlv1Side');if(_s)_s.remove();document.body.classList.remove('hasDeskNav');}catch(e){}publicSite()}
// 🔴 B315 (03.08.2026, TK-নির্দেশ): লগআউট চাপলে সরাসরি লগআউট না হয়ে আগে
// নিশ্চিত করা হয় — ঠিক TK-এর চাওয়া লেখাতেই ("Are you sure you want to
