window["wlv1TileTheme"]=wlv1TileTheme;
function card(icon,title,count,fn){
 let showCount=false;
 if(typeof count==='number') showCount=count>0;
 else if(count!==''&&count!=null) showCount=String(count).trim()!==''&&String(count).trim()!=='0';
 let c=showCount?`<span class="count">${esc(count)}</span>`:'';
 let t=wlv1TileTheme(title);
 // TK APPROVED (2026-07-27): the dashboard tiles are now plain white cards
 // with a hairline border -- exactly the "Model 1" look TK picked on the phone,
 // because the module names were hard to read on the coloured cards. The
 // coloured chip (t[2]) stays, so every module is still known by its colour.
 // Nothing else about the tile changes: same button, same class list, same
 // onclick, same count badge, same order.
 return `<button class="card module wlv1Tile" style="background:#FFFFFF;border-color:#E6EBF2" onclick="${fn}" aria-label="${esc(title)}">${c}<span class="wlv1Chip" style="background:${t[2]}">${icon}</span><b class="wlv1TileLabel">${title}</b></button>`;
}
window["card"]=card;
function userPhotoMap(){try{return JSON.parse(localStorage.getItem('rk_userPhotos')||'{}')}catch(e){return {}}}
window["userPhotoMap"]=userPhotoMap;
