window["canEditOwnUserPhoto"]=canEditOwnUserPhoto;
function userAvatar(){
 let ph=currentUserPhoto();
 let nm=String(dashboardPersonName()||user?.name||'PC').trim();let parts=nm.split(/\s+/).filter(Boolean);let init=(parts[0]?.[0]||'P')+(parts.length>1?(parts[parts.length-1]?.[0]||''):'');
 let inner=ph?`<img src="${esc(ph)}" alt="">`:`<span>${esc(init.toUpperCase())}</span>`;
 let cls=ph?'userAvatar':'userAvatar initials';
 let action=canEditOwnUserPhoto()?` onclick="openUserPhotoSheet('${mob(user?.mobile)}')" title="Photo"`:'';
 return `<div class="${cls}"${action}>${inner}${canEditOwnUserPhoto()?'<em class="avatarCam">📷</em>':''}</div>`;
}
