 m=mob(m||user?.mobile);let photos=userPhotoMap(),has=!!photos[m];
 if(m!==mob(user?.mobile)&&!isMaster())return toast('Only Master Admin can change photo');
 if(m===mob(user?.mobile)&&has&&!isMaster())return toast('Photo already locked. Contact Master Admin.');
 wlv1UserPhotoPage(m);
