window["masterUserPhotoManager"]=masterUserPhotoManager;
/* 🟢🔒 V926 (৩১.০৮.২০২৬, TK ডেমো প্রুফ দেখে "হ্যাঁ পাশ, বসিয়ে দিন") —
   "Pending Call"-এর গোনা এখন **ফোনের অ্যাপের হুবহু নিয়মে**।
   **আসল অমিল (কোড ধরে যাচাই, আন্দাজ নয়):** ফোনের ড্যাশবোর্ড-ব্যানার গোনে
   `nextFollow.isNotBlank() && nextFollow <= today` — অর্থাৎ **আজ + বকেয়া**
   (DashboardActivity.kt-এর `isDue`, TK-অনুমোদিত V590-এর নিয়ম)। কম্পিউটার
   গোনত `nextFollow === today()` — **শুধু ঠিক আজকের**। তাই দুই জায়গার
   সংখ্যা কখনোই মিলত না, আর একদিন বাদ পড়া কল কম্পিউটারে চিরতরে হারিয়ে যেত।
   ⛔ তারিখ ফাঁকা হলে (কল ঠিক করাই নেই) আগের মতোই গোনা হয় না।
   ⛔ Converted/Closed বাদ দেওয়ার নিয়ম এক অক্ষরও বদলায়নি। */
function wlv1CallDue(x){
  var d=String((x&&x.nextFollow)||'');
  if(!d) return false;
  if(d>today()) return false;
  try{ if(isConvertedOrClosed(x)) return false }catch(_e){}
  return true;
}
window["wlv1CallDue"]=wlv1CallDue;
function wlv1CallLate(x){
  var d=String((x&&x.nextFollow)||'');
  return !!d && d<today();
}
window["wlv1CallLate"]=wlv1CallLate;
function headerBell(){
 let n=0;
 try{n=mergeFollow(scoped(load('followups'))).filter(wlv1CallDue).length}catch(e){n=0}
 // 🔔 TK-অনুমোদিত (১৫.০৮.২০২৬): ঘন্টা এখন **পূর্ণ Notifications পাতা** খোলে
 // (Android-এর মতো)। ⛔ ব্যাজের সংখ্যা গোনার নিয়ম উপরে এক অক্ষরও বদলায়নি।
 // ⛔ পুরনো `pendingBellMenu()` মোছা হয়নি — নতুনটা কোনো কারণে না চললে ওটাই চলে।
 return `<button class="iconOnly bellOnly" onclick="(typeof wlv1NotificationsPage==='function')?wlv1NotificationsPage():pendingBellMenu()" aria-label="Notifications">🔔${n>0?`<span class="bellBadge">${n}</span>`:''}</button>`;
}
window["headerBell"]=headerBell;
function pendingBellMenu(){
 /* 🟢🔒 V926 — গোনা এখন ফোনের নিয়মে (আজ + বকেয়া)। */
 let f=mergeFollow(scoped(load('followups'))).filter(wlv1CallDue);
 let stages=['Inquiry','Patient','Treatment'].filter(t=>f.some(x=>x.stage===t));
 if(!stages.length){modal(`<h2>Pending Calls</h2><div class="card mut">আজ কোনো Pending Call নেই</div>`);return}
 let lateAll=f.filter(wlv1CallLate).length;
 let opts=stages.map(t=>`<button class="menuBtn" onclick="closeModal();todayPendingCall('${t}')"><span>📞</span><b>${stageLabel(t)}</b><small>${f.filter(x=>x.stage===t).length}</small></button>`).join('');
 modal(`<h2>Pending Calls${lateAll>0?` — ${lateAll} overdue`:''}</h2><div class="grid menuGrid">${opts}</div>`);
}
window["pendingBellMenu"]=pendingBellMenu;
/* 🔔🖥️ Notifications — পূর্ণ পাতা (TK-অনুমোদিত প্রুফ, ১৫.০৮.২০২৬, "খুব সাবধানে")।
   Android-এর `native/NotificationsActivity.kt` (২৮৬ লাইন) + `activity_notifications.xml`
   পুরো পড়ে হুবহু মিলিয়ে — একই বিভাগ-ভাগ, একই রং, একই শিরোনাম/উপ-শিরোনামের লেখা,
   শিরোনামে মোট সংখ্যা `Notifications (N)`, খালি হলে "No pending items"।
   ⛔ **সৎভাবে জানানো — ফোনের ৫টা বিভাগের ২টা ব্রাউজারে বানানো অসম্ভব** (TK-কে আগেই
      জানানো হয়েছে, তিনি জেনেই অনুমতি দিয়েছেন):
        · 📝 Remark Pending — ফোনের `PendingRemarkStore` (ডায়ালার-নির্ভর, ফোনেই থাকে)
        · ☎️ Callback Pending — ফোনের **কল-লগ** (`BranchSimHelper`) — ব্রাউজার কল-লগ দেখতেই পারে না
      (খাতাতেও আগে থেকেই লেখা: "কল-লগ অটো-গোনা — ব্রাউজারে অসম্ভব")।
   ⛔ **কম্পিউটারের নিজস্ব "Today Pending Call" মুছে ফেলা হয়নি** — ওটা স্টাফরা ব্যবহার
      করেন, তাই নতুন পাতায় চতুর্থ বিভাগ হিসেবে রাখা হলো (ফোনের ঘন্টায় এটা নেই)।
   ⛔ কোনো নতুন ক্লাউড-কল যোগ হয়নি — সব তথ্য **ইতিমধ্যে লোকালে থাকা** তালিকা থেকে,
      আর ব্রাঞ্চের ছাঁকনি অ্যাপের নিজের প্রমাণিত `scoped()` (যেটা ঘন্টার সংখ্যাও ব্যবহার করে)।
   ⛔ পুরনো `pendingBellMenu()` **অক্ষত রাখা হলো** (নিরাপত্তা-জাল)।                     */
function wlv1NbRow(icon,bg,title,sub,onclick){
  return '<div class="nbRow" onclick="'+onclick+'"><div class="nbIco" style="background:'+bg+'">'+icon+'</div>'
    +'<div><div class="nbT">'+esc(title)+'</div><div class="nbS">'+esc(sub)+'</div></div></div>';
}
/* 🟢 V410: কত জনের বেশি হলে তালিকা গুটিয়ে রাখা হবে (ফোনের `COLLAPSE_OVER`-এর হুবহু এক)। */
const WLV1_NB_COLLAPSE_OVER = 10;
function wlv1NbToggle(which){
  try{
    if(which==='call') window.__wlv1NbExpandCall = !window.__wlv1NbExpandCall;
    else window.__wlv1NbExpandExp = !window.__wlv1NbExpandExp;
    wlv1NotificationsPage();   /* ⛔ শুধু আবার আঁকা — ক্লাউড থেকে নতুন কিছু আনা হয় না */
  }catch(e){}
}
window["wlv1NbToggle"]=wlv1NbToggle;
function wlv1NotificationsPage(){
  var html='', total=0;
  var t=today();
  // ১) 🔔 Notices — ঘন্টার ব্যাজ যা গোনে, হুবহু তাই।
  var notices=0; try{ notices=activeBriefings().length }catch(e){ notices=0 }
  if(notices>0){
    total+=notices;
    html+='<div class="nbSec" style="color:#3b82f6"><i style="background:#3b82f6"></i>🔔 Notices</div>'
      + wlv1NbRow('📋','#e8f2ff',(notices===1?'1 new notice':notices+' new notices'),'Tap to view','briefingHome()');
  }
  // ডাক্তার/RMP-র দুই বিভাগ — একই তালিকা থেকে, শুধু তারিখ আলাদা।
  var dv=[]; try{ dv=scoped(load('doctor_visits')||[]).filter(function(x){return !isSeededRecord(x)}) }catch(e){ dv=[] }
  var callToday=dv.filter(function(x){return String(x.nextCallDate||'').slice(0,10)===t})
                  .sort(function(a,b){return String(a.name||'').localeCompare(String(b.name||''))});
  var expToday =dv.filter(function(x){return String(x.expectedPatientDate||'').slice(0,10)===t})
                  .sort(function(a,b){return String(a.name||'').localeCompare(String(b.name||''))});
  // ২) 📞 Call Doctor Today
  /* 🟢🔒 V410 (TK-নির্দেশ, ১৭.০৮.২০২৬) — লম্বা তালিকা গুটিয়ে রাখা।
     আজ ১৩৮ জন, ২২ অগাস্ট ৩০৮ জন — একসাথে দেখালে স্টাফ তালিকাটাই এড়িয়ে যান।
     ⇒ ১০ জনের বেশি হলে এক লাইনে, চাপলে খোলে। ⛔ গোনা (উপরের সংখ্যা) অপরিবর্তিত।
     ⛔ ফোনের `NotificationsActivity`-তেও হুবহু একই নিয়ম বসানো হয়েছে। */
  if(callToday.length){
    total+=callToday.length;
    html+='<div class="nbSec" style="color:#16A36D"><i style="background:#16A36D"></i>📞 Call Doctor Today</div>';
    if(callToday.length>WLV1_NB_COLLAPSE_OVER && !window.__wlv1NbExpandCall){
      html+=wlv1NbRow('📞','#e8fff4',(callToday.length+' doctors to call today'),'Tap to open the full list',
        "wlv1NbToggle('call')");
    }else{
      callToday.forEach(function(d){
        html+=wlv1NbRow('📞','#e8fff4',(d.name||'UNKNOWN'),(normMob(d.mobile||'')+' · Next Call Date is today'),
          "wlv1NbOpenDoctor('"+esc(String(d.mobile||''))+"')");
      });
      if(callToday.length>WLV1_NB_COLLAPSE_OVER){
        html+=wlv1NbRow('▲','#eef1f5','Hide this list','Show it as one line again',"wlv1NbToggle('call')");
      }
    }
  }
  // ৩) 🧑‍⚕️ Patient Expected Today
  if(expToday.length){
    total+=expToday.length;
    html+='<div class="nbSec" style="color:#6941C6"><i style="background:#6941C6"></i>🧑‍⚕️ Patient Expected Today</div>';
    if(expToday.length>WLV1_NB_COLLAPSE_OVER && !window.__wlv1NbExpandExp){
      html+=wlv1NbRow('🧑‍⚕️','#f1e9ff',(expToday.length+' doctors expecting a patient today'),'Tap to open the full list',
        "wlv1NbToggle('exp')");
    }else{
      expToday.forEach(function(d){
        html+=wlv1NbRow('🧑‍⚕️','#f1e9ff',(d.name||'UNKNOWN'),(normMob(d.mobile||'')+' · Expected patient today'),
          "wlv1NbOpenDoctor('"+esc(String(d.mobile||''))+"')");
      });
      if(expToday.length>WLV1_NB_COLLAPSE_OVER){
        html+=wlv1NbRow('▲','#eef1f5','Hide this list','Show it as one line again',"wlv1NbToggle('exp')");
      }
    }
  }
  /* 🟢🔒 V926 — গোনা এখন ফোনের নিয়মে (আজ + বকেয়া), আর বকেয়ার সংখ্যাটা
     আলাদা করে দেখানো হয় — নইলে "Today" লেখাটা মিথ্যে হয়ে যেত।
     ⛔ ফোনের চেহারা অক্ষত: বড় পর্দায় (≥900px) নতুন সাজের সারি, ছোট পর্দায়
        হুবহু আগের `wlv1NbRow` — দুটোর কাজ ও গন্তব্য এক। */
  var f=[]; try{ f=mergeFollow(scoped(load('followups'))).filter(wlv1CallDue) }catch(e){ f=[] }
  var stages=['Inquiry','Patient','Treatment'].filter(function(s){return f.some(function(x){return x.stage===s})});
  if(stages.length){
    total+=f.length;
    var lateAll=f.filter(wlv1CallLate).length;
    var wide=false; try{ wide=(window.innerWidth>=900) }catch(_e){ wide=false }
    if(wide){
      html+='<div class="nbSecPro"><i></i><b>\u{1F4DE} Pending Calls</b>'
        +(lateAll>0?'<span class="od">'+lateAll+' overdue</span>':'')+'</div>';
      var ICO={Inquiry:'\u{1F465}',Patient:'\u{1F463}',Treatment:'\u{1F464}'};
      stages.forEach(function(s){
        var rows=f.filter(function(x){return x.stage===s});
        var late=rows.filter(wlv1CallLate).length, tod=rows.length-late;
        html+='<div class="nbRowPro" onclick="todayPendingCall(\''+s+'\')">'
          +'<div class="ico">'+(ICO[s]||'\u{1F4DE}')+'</div>'
          +'<div class="txt"><b>'+esc(typeof stageLabel==='function'?stageLabel(s):s)+'</b>'
          +'<small>'+tod+' today \u00b7 '+late+' overdue</small></div>'
          +'<div class="cnt"><b>'+rows.length+'</b><small>CALLS</small></div>'
          +'<div class="arw">\u203a</div></div>';
      });
    }else{
      html+='<div class="nbSec" style="color:#E5484D"><i style="background:#E5484D"></i>\u{1F4DE} Pending Calls'
        +(lateAll>0?' \u2014 '+lateAll+' overdue':'')+'</div>';
      stages.forEach(function(s){
        var n=f.filter(function(x){return x.stage===s}).length;
        html+=wlv1NbRow('\u{1F4DE}','#ffe9e9',((typeof stageLabel==='function'?stageLabel(s):s)+' — '+n),'Tap to open the list',
          "todayPendingCall('"+s+"')");
      });
    }
  }
  // 🔧 নিজের ভুল ধরা পড়ল ও ঠিক করা হলো (১৫.০৮.২০২৬): এখানে `home()` লেখা ছিল, কিন্তু
  // এই প্রজেক্টে ঐ নামে কোনো ফাংশনই নেই — Back বোতাম চাপলে কিছুই হত না।
  // অ্যাপের আসল নাম `dashboard()` (লাইন ২০৬১-এ window-তে বসানো), সেটাই বসানো হলো।
  var head='<div class="actions" style="margin:0">'
    +'<button class="small ghost" onclick="briefingHome()">📜 Notices</button></div>';
  var body = total>0 ? html : '<div class="card mut" style="margin-top:10px">No pending items</div>';
  page('Notifications'+(total>0?' ('+total+')':''), '<div class="card wlv1NbCard">'+head+body+'</div>', true);
}
window["wlv1NotificationsPage"]=wlv1NotificationsPage;
function wlv1NbOpenDoctor(m){
  // Android-এর `putExtra("searchMobile", …)`-এর সমতুল্য — সার্চে নম্বর বসিয়ে পাতা খোলা।
  try{ safeSessionSet('doctorVisitSearch', String(m||'')) }catch(e){}
  try{ doctorVisit('home') }catch(e){ toast('Could not open') }
}
window["wlv1NbOpenDoctor"]=wlv1NbOpenDoctor;

function briefings(){return load('briefings')}
window["briefings"]=briefings;
function saveBriefings(x){save('briefings',x||[])}
window["saveBriefings"]=saveBriefings;
function briefingTargetsHit(b){let m=mob(user?.mobile),role=String(user?.role||'').toLowerCase(),br=String(user?.branch||'');let t=b.targets||{};let roles=(t.roles||[]).map(x=>String(x).toLowerCase());let branches=(t.branches||[]).map(String);let mobiles=(t.mobiles||[]).map(mob);return !!(t.all||t.allStaff||mobiles.includes(m)||roles.includes(role)||branches.some(x=>sameBranch(x,br)))}
window["briefingTargetsHit"]=briefingTargetsHit;
function hasSeenBrief(b){return (b.seen||[]).map(mob).includes(mob(user?.mobile))}
window["hasSeenBrief"]=hasSeenBrief;
function isBriefingDeletedForMe(b){let m=mob(user?.mobile);return !!(b.deletedAt||(b.hiddenFor||[]).map(mob).includes(m))}
window["isBriefingDeletedForMe"]=isBriefingDeletedForMe;
// 🔔🔒 V490 (20.08.2026, TK-নির্দেশ): নতুন Enquiry · Registration · Advance-এর
// স্বয়ংক্রিয় নোটিশ (ডেটাবেসেই তৈরি হয়, তাই ফোন-ওয়েব দুটোতেই আসে)।
// সাধারণ নোটিশ শুধু আজকেরটা দেখায়; TK-এর নির্দেশ — "যতক্ষণ সিন না করবে,
// সর্বোচ্চ ১ সপ্তাহ" — তাই এই তিনটে ৭ দিন পর্যন্ত থাকে। নামগুলো SQL-এর
// auto_notice_titles() ও অ্যান্ড্রয়েডের BriefingModel.isAutoNotice()-এর হুবহু এক।
const AUTO_NOTICE_TITLES=['new enquiry','new registration','advance received'];
const AUTO_NOTICE_DAYS=7;
function isAutoNotice(b){return AUTO_NOTICE_TITLES.includes(String(b?.title||'').trim().toLowerCase())}
/* ══════════════════════════════════════════════════════════════════════════
   🔴🔴🔒 V511 (২১.০৮.২০২৬, TK-নির্দেশ ছবিসহ) — স্বয়ংক্রিয় নোটিশে **👁 View**।

   TK-এর কথা: *"এটা একটা নতুন এনকোয়ারি হয়েছে, এখন অ্যাকশন কি হতে পারে? আমার
   হিসাবে তো অ্যাকশন হতে হয় ভিউ... ভিউতে চাপ দিলে রিডাইরেক্ট করবে নাম্বারটা
   যেখানে থাকতে হবে — এনকোয়ারি হলে ফলোআপের ইনকয়ারি সেকশনে, রেজিস্ট্রেশন হলে
   ভিজিট সেকশনে, অ্যাডভান্স হলে কত টাকা এডভান্স করল সেখানে।"*

   ⛔ ফোনের `BriefingAdapter`/`BriefingActivity`-র হুবহু একই নিয়ম।
   ⛔ এই তিন নোটিশে **Reply নেই** (কী রিপ্লাই দেবেন?) — View · Seen · Delete।
   ⛔ হাতে লেখা Briefing ও অনুমোদনের নোটিশ এক অক্ষরও বদলায়নি।
   ══════════════════════════════════════════════════════════════════════════ */
/* নম্বর খোঁজার নিয়ম — ফোনের `MOBILE_PATTERN`-এর হুবহু একই।
   ⚠️ `+917099468221` (গায়ে গায়ে লাগানো) — ফোনে ঠিক এই ধরনটাই আগে ধরা পড়ত না,
      তাই View চিরকাল লুকানো থাকত। এখানে সেই ভুল যাতে না হয়। */
function wlv1NoticeMobile(b){
  try{
    var m=String((b&&b.message)||'').match(/(?:^|[^0-9])(?:\+?91[\-\s]?)?([6-9][0-9]{9})(?![0-9])/);
    return m?m[1]:'';
  }catch(e){ return ''; }
}
window["wlv1NoticeMobile"]=wlv1NoticeMobile;

/* ══════════════════════════════════════════════════════════════════════════
   🟢🔒 V692 (২৬.০৮.২০২৬, TK-নির্দেশ ছবিসহ) — ⚠️ **Overdue Follow-up Alert-এ
   Reply নয়, View।**

   TK-এর কথা (হুবহু): *"Overdue Call Alert এ Reply কেন আসবে, সেখানে View
   থাকতে হবে, আর View তে চাপলে যেন দেখা যায়।"*
   TK-এর বাছা (জিজ্ঞাসা করে): **শুধু ওই ৩+ দিন দেরি হওয়া লোকগুলোই** —
   নোটিশে যত জন লেখা, ঠিক তত জন; ব্রাঞ্চের সব Overdue নয়।

   ⛔ ফোনের `BriefingModel.isOverdueAlert()` / `BriefingAdapter` /
      `BriefingActivity.openOverdueAlert()`-এর হুবহু একই নিয়ম (§৬.৬)।
   ⛔ `isAutoNotice()`-এ ঢোকানো হয়নি ইচ্ছে করেই — ওটা নোটিশ ৭ দিন টিকিয়ে
      রাখে, আর এই সতর্কতা রোজ আসে বলে সাতটা জমে যেত।
   ══════════════════════════════════════════════════════════════════════════ */
