/* View চাপলে — নোটিশের ধরন অনুযায়ী ঠিক জায়গায়।
   ⛔ ব্রাঞ্চ: নোটিশটা অন্য ব্রাঞ্চের হলে মাস্টারের ছাঁকনি সেই ব্রাঞ্চে বদলে
      দেওয়া হয় (TK-অনুমোদিত, ২১.০৮.২০২৬), আর ছোট করে জানিয়ে দেওয়া হয়।
      স্টাফের ব্রাঞ্চ নিজের — ছোঁয়া হয় না। */
function wlv1NoticeView(id){
  try{
    var b=briefings().find(function(x){return String(x.id)===String(id)});
    if(!b)return toast('Notice not found');
    var mm=wlv1NoticeMobile(b);
    if(!mm)return toast('No mobile number in this notice');
    var t=String(b.title||'').trim().toLowerCase();
    /* ব্রাঞ্চ বদল — শুধু মাস্টার, শুধু দরকার হলে */
    try{
      if(isMaster()){
        var want=String(b.branch||'').trim();
        var now=String(wlv1BranchGet()||'').trim();
        if(want && !/^all$/i.test(want) && !/^all$/i.test(now) &&
           want.toLowerCase()!==now.toLowerCase()){
          wlv1BranchSet(want);
          toast('Branch switched to '+want);
        }
      }
    }catch(e){}
    if(t==='advance received'){ summaryByMobile(mm); return; }
    /* Enquiry / Registration → Follow-up-এ, যে সেকশনে নম্বরটা আছে সেখানেই */
    var d=today();
    __followDateFilter={mode:'',from:'',to:''};
    var stage='Inquiry';
    try{
      ['Inquiry','Patient','Treatment'].some(function(st){
        var hit=followStats(st).rows.some(function(r){return mob(r.mobile)===mob(mm)});
        if(hit){ stage=st; return true; }
        return false;
      });
    }catch(e){}
    window.__RK_PINNED_FOLLOW_MOBILE = mm;
    followup(stage);
  }catch(e){ toast('Could not open') }
}
window["wlv1NoticeView"]=wlv1NoticeView;
window["isAutoNotice"]=isAutoNotice;
function autoNoticeFresh(b){let d=String(b?.date||'').trim();if(!/^\d{4}-\d{2}-\d{2}$/.test(d))return false;let diff=(new Date(today()+'T00:00:00')-new Date(d+'T00:00:00'))/86400000;return diff>=0&&diff<=AUTO_NOTICE_DAYS}
