function briefingReplyLine(b,r){let can=isMaster()||mob(r.by)===mob(user?.mobile);let txt=r.deletedAt?'This reply was deleted':esc(r.text||'');let del=(!r.deletedAt&&can)?` <button class="small ghost redText" onclick="deleteBriefReply('${b.id}','${r._id}',${r._idx})">Delete</button>`:'';return `<div class="briefReply ${r.deletedAt?'mut':''}"><b>${esc(codeName(r.by)||r.by||'User')}</b>: ${txt} <small>${esc(String(r.at||'').slice(0,16).replace('T',' '))}</small>${del}</div>`}
window["briefingReplyLine"]=briefingReplyLine;
function briefingDeleteButton(b){return `<button class="ghost redText" onclick="deleteBriefing('${b.id}')">Delete</button>`}
