function briefingToProductRow(b){return {id:b.id,kind:'briefing',product:JSON.stringify(b),customer:'BRIEFING',mobile:(b.targets?.mobiles||[]).join(','),qty:0,price:0,total:0,deposit:0,mode:'BRIEFING',date:b.date||today(),branch:b.branch||'',receivedBy:briefingSummary(b),createdBy:b.createdBy||user?.mobile||'',createdAt:b.createdAt||new Date().toISOString(),updatedAt:b.updatedAt||new Date().toISOString()}}
