async function cloudUpsertBriefing(row){
 let ok=await directCloudUpsertRow('briefings',row);
 if(ok)return true;
 // Fallback: if the new briefings table/SQL is not available yet, store the same data in existing products table.
 // This keeps Admin -> Staff delivery working without disturbing other modules.
 return await directCloudUpsertRow('products',briefingToProductRow(row));
}
