/* WEB APP . the native More screen shows the app version at the bottom, so the
   web menu shows it too. It reads the version stamped on index.html (?v=...),
   which is what actually changes when a new build is put on Netlify. */
function wlv1AppVersion(){
  try{
    const tag = [...document.querySelectorAll('script[src]')]
      .map(x=>x.getAttribute('src'))
      .find(x=>x && x.indexOf('app.js')>=0) || '';
    const m = tag.match(/[?&]v=([^&]+)/);
    return m ? m[1] : 'web';
  }catch(e){ return 'web'; }
}
window["wlv1AppVersion"]=wlv1AppVersion;
