// 🔒 V448 (19.08.2026): Reject/Restore-এর durable truth শুধু বর্তমান status নয়।
// পুরনো generic heal/view এক সময় status=Active লিখে দিলেও append-only history-তে
// শেষ explicit workflow decision থাকে। সেই শেষ Reject/Restore-ই এখানে জয়ী হবে।
function wlv1InquiryDecisionMs(h){
 let raw=String((h&&h.time)||'').trim()||String((h&&h.date)||'').trim();
 if(!raw)return null;
 let ms=Date.parse(raw); if(Number.isFinite(ms))return ms;
 let m=raw.match(/^(\d{2})[.\/](\d{2})[.\/](\d{4})$/);
 if(m){ms=Date.UTC(Number(m[3]),Number(m[2])-1,Number(m[1]));if(Number.isFinite(ms))return ms;}
 return null;
}
function wlv1InquiryHistoryEndsTerminal(row){
 let h=Array.isArray(row&&row.history)?row.history:[];
 let termSeen=false, activeSeen=false, newestTerm=null, newestActive=null, v448ActiveSeen=false;
 for(let i=0;i<h.length;i++){
  let x=h[i]||{}, st=String(x.status||'').trim().toLowerCase(), r=String(x.remark||'').trim().toLowerCase();
  let active=['active','restored','continued','continue'].includes(st) ||
    r.startsWith('restored & moved to') || r==='restored from reject list' ||
    r==='continue entry' || r==='continued' || r==='continued (keep active)';
  let terminal=['cancelled','incomplete','rejected','closed'].includes(st) ||
    r==='rejected' || r==='marked incomplete' || r==='entry cancelled' ||
    r==='5-call limit — closed' || r==='5-call limit - closed' ||
    r==='cancelled after 5 calls' || r==='cancelled (duplicate number, never visited)' ||
    r==='cancelled by staff (signal 3-tap)' || r==='deleted';
  if(!active&&!terminal)continue;
  let ms=wlv1InquiryDecisionMs(x);
  if(active){activeSeen=true;if(String(x.decisionVersion||'').toUpperCase()==='V448')v448ActiveSeen=true;if(ms!==null&&(newestActive===null||ms>newestActive))newestActive=ms;}
  if(terminal){termSeen=true;if(ms!==null&&(newestTerm===null||ms>newestTerm))newestTerm=ms;}
 }
 if(!termSeen)return false;
 if(!activeSeen)return true;
 // V407 merged duplicate history with jsonb_agg(distinct ...) without ORDER BY,
 // so array position cannot decide which action was later. Use timestamps; if
 // chronology is equal/unknown, stay terminal-safe until an explicit Restore.
 if(newestTerm!==null&&newestActive!==null)return newestTerm>=newestActive;
 if(newestTerm!==null&&newestActive===null)return true;
 if(newestTerm===null&&newestActive!==null&&v448ActiveSeen)return false;
 return true;
}
window["wlv1InquiryHistoryEndsTerminal"]=wlv1InquiryHistoryEndsTerminal;

function wlv1RepairLegacyRejectedInquiryDuplicates(){
 try{
  let fs=load('followups')||[], es=load('enquiries')||[], closed=new Set();
  fs.forEach(f=>{
   if(!f||String(f.stage||'').toLowerCase()!=='inquiry')return;
   let mm=mob(f.mobile); if(!mm)return;
   if(wlv1IsTerminalFollowStatus(f.status)||wlv1InquiryHistoryEndsTerminal(f))closed.add(mm);
  });
  es.forEach(e=>{let mm=mob(e&&e.mobile);if(mm&&wlv1IsTerminalFollowStatus(e&&e.status))closed.add(mm)});
  if(!closed.size)return false;
  let now=new Date().toISOString(), fc=false, ec=false;
  fs=fs.map(f=>{
   let mm=mob(f&&f.mobile);
   if(!f||String(f.stage||'').toLowerCase()!=='inquiry'||!closed.has(mm)||wlv1IsTerminalFollowStatus(f.status))return f;
   let hist={date:today(),time:isoNow(),remark:'Recovered rejected duplicate',staff:'System repair',nextFollow:'',status:'Cancelled',decisionVersion:'V450'};
   let r={...f,status:'Cancelled',nextFollow:'',updatedAt:now,history:[...(f.history||[]),hist]};
   protectNewRow('followups',r);fc=true;return r;
  });
  es=es.map(e=>{
   let mm=mob(e&&e.mobile),stage=String(e&&e.stage||'').toLowerCase();
   if(!e||stage!=='inquiry'||!closed.has(mm)||wlv1IsTerminalFollowStatus(e.status))return e;
   let r={...e,status:'Cancelled',stage:'Cancelled',nextFollow:'',updatedAt:now,cancelledAt:e.cancelledAt||now,cancelledBy:e.cancelledBy||'System repair'};
   protectNewRow('enquiries',r);ec=true;return r;
  });
  if(fc)save('followups',fs);
  if(ec)save('enquiries',es);
  if(fc||ec){try{_invalidateFollowLookupCache()}catch(_e){}}
  return fc||ec;
 }catch(_e){return false}
}
window["wlv1RepairLegacyRejectedInquiryDuplicates"]=wlv1RepairLegacyRejectedInquiryDuplicates;
