function isConvertedOrClosed(x){let st=String(x?.status||'').toLowerCase(),sg=String(x?.stage||'').toLowerCase();return ['closed','registered','converted','cancelled','rejected','incomplete'].includes(st)||['registered','converted','closed'].includes(sg)||(sg==='inquiry'&&!!x?.convertedPatientId)}
window["isConvertedOrClosed"]=isConvertedOrClosed;
/* 🖥️🔴🔒 V549 (২২.০৮.২০২৬) — **এক নম্বরে দুজন রোগী: একজনের রেজিস্ট্রেশন
   যেন অন্যজনের সারি বন্ধ করে না দেয়** (ফোনে V536-এ যা করা হয়েছিল, ওয়েবেও তাই)।

   রেজিস্ট্রেশন শেষ হলে ওই মোবাইলের **সব** enquiry ও Inquiry-followup সারিকে
   "Registered/Closed" করে দেওয়া হত — শুধু মোবাইল মিলিয়ে। একই নম্বরে স্বামী-স্ত্রী
   দুজন রোগী থাকলে একজনকে রেজিস্টার করলেই **অন্যজনের এনকোয়ারিও বন্ধ** হয়ে যেত।

   নিয়মটা ফোনের `PatientIdentity.provablyOtherPatient`-এর হুবহু নকল —
   **প্রমাণ ছাড়া কাউকে বাদ দেওয়া হয় না**:
     • নম্বরটাতে স্টাফ নিজে "Different Patient — Same Mobile" বলেননি → আগের
       আচরণ **হুবহু অপরিবর্তিত** (তাই রোজকার ৯৯% ক্ষেত্রে কিচ্ছু বদলায় না);
     • বলে থাকলে তবেই — যে সারির `refId`/`convertedPatientId` **অন্য একজন
       রোগীর দিকে দেখাচ্ছে**, বা নাম **স্পষ্টতই অন্য কারো**, শুধু সেটাই বাদ যায়।
   ⛔ কোনো সারি মোছা/বদলানো হয় না — শুধু ছোঁয়া হয় না। */
function wlv1MobileHasSeparateIdentity(mm){
  try{
    var d=mob(mm); if(!d) return false;
    return (load('patients')||[]).some(function(x){
      return mob(x&&x.mobile)===d && wlv1IsDeclaredSeparateRowId(x&&x.id, d);
    });
  }catch(e){ return false }
}
function wlv1ProvablyOtherPatient(row,mm,p){
  try{
    if(!row||!p) return false;
    if(!wlv1MobileHasSeparateIdentity(mm)) return false;   // নম্বরটা ভাগ করা নয় → আগের নিয়ম
    var mine=String(p.id||'');
    var link=String(row.refId||row.convertedPatientId||'');
    if(link && mine && link!==mine) return true;
    var rn=String(row.name||'').trim().toUpperCase();
    var pn=String(p.name||'').trim().toUpperCase();
    return !!(rn && pn && rn!==pn);
  }catch(e){ return false }
}
window["wlv1MobileHasSeparateIdentity"]=wlv1MobileHasSeparateIdentity;
window["wlv1ProvablyOtherPatient"]=wlv1ProvablyOtherPatient;
function closeEnquiryAfterRegistration(m,p){
 try{
  let mm=mob(m),now=new Date().toISOString(),hist={date:today(),time:isoNow(),remark:'Converted to Patient Registration',staff:user?.name||user?.mobile||'Staff',status:'Registered'};
  let changedE=[];
  let es=load('enquiries').map(e=>{if(mob(e.mobile)===mm&&!wlv1ProvablyOtherPatient(e,mm,p)){let row={...e,status:'Registered',stage:'Registered',nextFollow:'',convertedPatientId:p?.id||e.convertedPatientId||'',convertedAt:e.convertedAt||now,updatedAt:now};changedE.push(row);return row}return e});
  changedE.forEach(r=>protectNewRow('enquiries',r));
  save('enquiries',es);
  let changedF=[];
  let fs=load('followups').map(f=>{
   if(mob(f.mobile)===mm&&String(f.stage||'')==='Inquiry'&&!wlv1ProvablyOtherPatient(f,mm,p)){
    // V256 final workflow fix: converted enquiry must not remain under Inquiry tab.
    // Keep history/data, but move it out of Inquiry with Closed status. Visit/Patient row is separate.
    let row={...f,previousStage:f.previousStage||'Inquiry',stage:'Registered',status:'Closed',nextFollow:'',lastRemark:'Converted to Patient Registration',convertedPatientId:p?.id||f.convertedPatientId||'',convertedAt:f.convertedAt||now,updatedAt:now,history:[...(f.history||[]),hist]};
    changedF.push(row);return row
   }
   return f
  });
  changedF.forEach(r=>protectNewRow('followups',r));
  save('followups',fs);
  changedE.forEach(r=>{try{directCloudUpsertRow('enquiries',r)}catch(_){}});
  changedF.forEach(r=>{try{directCloudUpsertRow('followups',r)}catch(_){}});
 }catch(e){console.warn('Close enquiry after registration skipped',e)}
}
window["closeEnquiryAfterRegistration"]=closeEnquiryAfterRegistration;



// V257 final branch/cloud workflow repair: selected branch data must be visible to Master Admin and all users of that branch.
// This is a workflow safety layer only. It does not change design, payment formula, print layout, or patient ID formula.
function forceCloudVisibleRows(rows){
 try{
  (Array.isArray(rows)?rows:[]).forEach(item=>{
   if(!item||!item.table||!item.row)return;
   protectNewRow(item.table,item.row);
   try{directCloudUpsertRow(item.table,item.row)}catch(_e){markPendingCloud(item.table)}
  });
  setTimeout(()=>{try{flushPendingCloud('pending');pullCloudAllForVisibility('v257-force-visible')}catch(_e){}},1200);
  setTimeout(()=>{try{flushPendingCloud('pending');pullCloudAllForVisibility('v257-force-visible-2')}catch(_e){}},3500);
 }catch(e){}
}
window["forceCloudVisibleRows"]=forceCloudVisibleRows;
function repairBranchWorkflowRows(){
 try{
  let changed=false,now=new Date().toISOString();
  let enquiries=load('enquiries'),patients=load('patients'),followups=load('followups');
  /* 🔴🔴🔴🆕🔒 V435 (TK-রিপোর্ট ১৮.০৮.২০২৬ — *"কোন অপশন থেকে অন্য কোন অপশনে যেতে
     অনেক সময় লাগছে, মনে হচ্ছে কোন কাজই করছে না"*)। **ব্রাউজারে মেপে পাওয়া আসল
     কারণ:** এই "নিজে থেকে ঠিক করা" (self-heal) ফাংশনটা **প্রতিটা রোগীর জন্য
     পুরো ফলো-আপ তালিকা ও পুরো এনকোয়ারি তালিকা** আগাগোড়া খুঁজত। ৩০০০ রোগী ×
     ৬০০০ সারি ⇒ প্রায় **১ কোটি ৮০ লাখ** বার নম্বর-মেলানো। প্রোফাইলে দেখা গেছে
     `mob()` একাই মোট সময়ের **৫০.৮%** খেয়ে ফেলছিল। Doctor Queue-এর মতো পর্দা
     এটাকে **প্রতিবার খোলার সময়** ডাকে — তাই সব পর্দাতেই দেরি হত।
     **সমাধান (ফল এক অক্ষরও বদলায়নি):**
       (১) `mob()`-এর উত্তর মনে রাখা হয় — একই লেখার জন্য বারবার হিসাব হয় না
           (এটা একটা বিশুদ্ধ ফাংশন, তাই উত্তর সবসময় হুবহু একই);
       (২) "কোন নম্বরের সারি কোথায়" — সেটার একটা তালিকা (index) **একবারই**
           বানানো হয়; `findIndex`-এর **প্রথম-মিল** নিয়মটা হুবহু রাখা হয়েছে
           (refId-এর প্রথম ও মোবাইলের প্রথম — দুটোর মধ্যে যেটা আগে, সেটাই);
       (৩) ভিতরের দুটো পুরো-তালিকা-পাল্টানো (map) তখনই চলে যখন ওই নম্বরের
           সত্যিই কিছু বদলানোর আছে — নইলে ওই পাসটা কিছুই বদলাত না, তাই বাদ
           দিলেও ফল একই।
       (৪) তথ্য সত্যিই বদলালে তালিকাটা আবার নতুন করে বানানো হয় (`__idxDirty`),
           তাই কখনো বাসি তথ্যে কাজ হয় না।
     ⛔ কোন সারি তৈরি হবে · কোনটা ঠিক হবে · কোন ঘরে কী বসবে — কিছুই বদলায়নি। */
  const __mobMemo=new Map();
  const __M=v=>{const k=String(v==null?'':v);let r=__mobMemo.get(k);if(r===undefined){r=mob(k);__mobMemo.set(k,r)}return r};
  let __idxDirty=true,__idxStage='',__byRef=null,__byMob=null;
  /* ⛔ অবস্থানটা **শেষ থেকে দূরত্ব** হিসেবে রাখা হয় (`len - i`)। কারণ নিচে নতুন
     সারি সবসময় **সামনে** (`unshift`) বসে — তাতে সবার আসল অবস্থান ১ করে বাড়ে,
     কিন্তু শেষ থেকে দূরত্ব একই থাকে। ফলে নতুন সারি বসলেও পুরো তালিকাটা আর
     নতুন করে বানাতে হয় না, অথচ উত্তর হুবহু একই থাকে। */
  const __buildIdx=stage=>{
    __byRef=new Map();__byMob=new Map();
    const L=followups.length;
    for(let i=0;i<L;i++){
      const f=followups[i]||{};
      if(String(f.stage||'')!==stage)continue;
      if(f.refId!==undefined&&!__byRef.has(f.refId))__byRef.set(f.refId,L-i);
      const m=__M(f.mobile);if(m&&!__byMob.has(m))__byMob.set(m,L-i);
    }
    __idxStage=stage;__idxDirty=false;
  };
  /* নতুন সারি সামনে বসল — সেটা এখন index 0, অর্থাৎ ওই refId ও ওই মোবাইলের
     জন্য **সবচেয়ে আগের**। তাই ওই দুটো চাবি নতুন মান পায়, বাকি সব আগের মতোই। */
  const __idxNoteUnshift=(stage,refId,mm)=>{
    if(__idxDirty||__idxStage!==stage||!__byRef)return;
    const L=followups.length;
    if(refId!==undefined)__byRef.set(refId,L);
    if(mm)__byMob.set(mm,L);
  };
  /* `followups.findIndex(f=>(f.refId===ID||mob(f.mobile)===MM)&&f.stage===STAGE)`-এর
     হুবহু একই উত্তর: দুটো "প্রথম মিল"-এর মধ্যে ছোটটা (কোনোটা না থাকলে -1)। */
  const __firstIdx=(stage,refId,mm)=>{
    if(__idxDirty||__idxStage!==stage)__buildIdx(stage);
    const L=followups.length;
    const a=__byRef.has(refId)?(L-__byRef.get(refId)):-1;
    const b=__byMob.has(mm)?(L-__byMob.get(mm)):-1;
    return a<0?b:(b<0?a:Math.min(a,b));
  };
  // 1) Every active enquiry must have an Inquiry follow-up row for same selected branch.
  enquiries.forEach(e=>{
   if(!e||!e.id||isConvertedOrClosed(e))return;
   let mm=__M(e.mobile); if(!mm)return;
   let i=__firstIdx('Inquiry',e.id,mm);
   let base={refId:e.id,mobile:normMob(mm),name:e.name||'',branch:e.branch||'',disease:e.disease||'',address:e.address||'',stage:'Inquiry',date:e.date||today(),registrationDate:e.date||today(),visitDate:e.date||today(),lastRemark:e.remarks||'',nextFollow:e.nextFollow||'',callCount:Number(e.callCount||0),status:e.status||'Active',history:[{date:e.date||today(),time:isoNow(),remark:e.remarks||'',staff:e.receivedBy||e.createdBy||''}],createdBy:e.createdBy||e.receivedBy||'',createdAt:e.createdAt||now,updatedAt:e.updatedAt||now};
   // 🟢 B626 (11.08.2026, TK-নির্দেশ · ডুপ্লিকেট/Reject-ফিরে-আসা রোগ): আগে
   //   uid('fu') দিয়ে র‍্যান্ডম id বসত — লোকাল কপিতে সারি না পেলে প্রতিবার নতুন
   //   একটা তৈরি হত (ভিন্ন id, তাই mergeById মেলাতে পারত না) → একই এনকোয়ারিতে
   //   ১০টা ডুপ্লিকেট। এখন **নির্দিষ্ট (deterministic) id** — একই এনকোয়ারিতে
   //   বারবার চললেও একই id, তাই আর জমে না (mergeById মিলিয়ে দেয়)।
   if(i<0){followups.unshift({id:'fu_inq_'+e.id,...base});changed=true;__idxNoteUnshift('Inquiry',e.id,mm)}
   else{
    let old=followups[i];
    // 🟢 B626: "ঠিক করার" সময় status/stage/converted-ঘরগুলো **পুরনো সারি থেকেই**
    //   রাখা হয় — base(এনকোয়ারি) থেকে নয়। নইলে Reject করা "Cancelled" আবার
    //   "Active" হয়ে যেত (self-heal উল্টে দিত)। শুধু ফাঁকা তথ্য (নাম/ব্রাঞ্চ/রোগ)
    //   ভরে, কিন্তু কাজের-অবস্থা (status) কখনো উল্টায় না।
    let fixed={...old,...base,id:old.id,status:(old.status!==undefined&&old.status!=='')?old.status:base.status,stage:old.stage||base.stage,previousStage:old.previousStage,convertedPatientId:old.convertedPatientId,convertedAt:old.convertedAt,history:(old.history&&old.history.length)?old.history:base.history,createdAt:old.createdAt||base.createdAt,updatedAt:old.updatedAt||base.updatedAt};
    if(JSON.stringify(fixed)!==JSON.stringify(old)){followups[i]=fixed;changed=true;__idxDirty=true}
   }
  });
  /* ধাপ ১ শেষে যে অবস্থাটা দাঁড়াল, ঠিক সেটাই ধাপ ২ দেখে — তাই তালিকা দুটো
     এখানেই বানানো। কোন নম্বরে এখনো Inquiry-সারি আছে, আর কোন নম্বরে এখনো
     না-রূপান্তরিত এনকোয়ারি আছে — শুধু সেগুলোর জন্যই নিচের পাস দুটো চালাতে হয়। */
  let __inqMobs=new Set();
  for(let i=0;i<followups.length;i++){const f=followups[i]||{};if(String(f.stage||'')==='Inquiry'){const m=__M(f.mobile);if(m)__inqMobs.add(m)}}
  let __openEnqMobs=new Set();
  for(let i=0;i<enquiries.length;i++){const e2=enquiries[i];if(e2&&!isConvertedOrClosed(e2)){const m=__M(e2.mobile);if(m)__openEnqMobs.add(m)}}
  // 2) Every registered patient must have Patient/Visit follow-up and must not remain active in Enquiry tab.
  patients.forEach(p=>{
   if(!p||!p.id)return;let mm=__M(p.mobile);if(!mm)return;
   let pi=__firstIdx('Patient',p.id,mm);
   let prow={refId:p.id,mobile:normMob(mm),name:p.name||'',branch:p.branch||'',disease:p.disease||'',address:p.address||'',stage:'Patient',date:p.registrationDate||p.visitDate||p.date||today(),registrationDate:p.registrationDate||p.date||today(),visitDate:p.visitDate||p.registrationDate||p.date||today(),lastRemark:'Registered patient / Visit created',nextFollow:'',callCount:0,status:'Active',history:[{date:today(),time:isoNow(),remark:'Registered patient / Visit created',staff:p.registeredBy||p.createdBy||''}],createdBy:p.createdBy||'',createdAt:p.createdAt||now,updatedAt:p.updatedAt||now};
   // 🟢 B626: Patient-stage self-heal-ও একইভাবে নির্দিষ্ট id — ডুপ্লিকেট বন্ধ।
   if(pi<0){followups.unshift({id:'fu_pat_'+p.id,...prow});changed=true;__idxNoteUnshift('Patient',p.id,mm)}
   else{
    // 🟢 B626: status/stage/converted পুরনো সারি থেকে — উল্টায় না।
    let old=followups[pi];/* 🔴🔒🔒 V875 (৩০.০৮.২০২৬) — TK-এর যাচাইয়ে ধরা পড়া **আমার নিজের ফাঁক**:
       V406-এ এই একই দোষ অন্য দুটো জায়গায় সারানো হয়েছিল, কিন্তু **এই তৃতীয়
       জায়গাটা বাদ পড়ে গিয়েছিল**। এটা ড্যাশবোর্ড খুললেই চলে, তাই পুরোনো
       Patient-সারিতে —
         · পরের কলের তারিখ (nextFollow) **মুছে যেত**
         · শেষ রিমার্ক **"Registered patient / Visit created"** হয়ে যেত
         · কল-গোনা (callCount) **০ হয়ে যেত**
       এখন V406-এর হুবহু প্রমাণিত তিনটে লাইনই এখানেও বসানো হলো।
       ⛔ পুরোনো সারিতে সত্যিই কিছু লেখা থাকলে তবেই রাখা হয়; ফাঁকা হলে আগের
          মতোই। কোনো তথ্য নতুন করে বানানো হয় না। */
    let fixed={...old,...prow,id:old.id,status:(old.status!==undefined&&old.status!=='')?old.status:prow.status,stage:old.stage||prow.stage,callCount:Number(old.callCount||0)>0?old.callCount:prow.callCount,nextFollow:(old.nextFollow||'')!==''?old.nextFollow:prow.nextFollow,lastRemark:(old.lastRemark||'')!==''?old.lastRemark:prow.lastRemark,previousStage:old.previousStage,convertedPatientId:old.convertedPatientId,convertedAt:old.convertedAt,history:(old.history&&old.history.length)?old.history:prow.history,createdAt:old.createdAt||prow.createdAt,updatedAt:old.updatedAt||prow.updatedAt};
    if(JSON.stringify(fixed)!==JSON.stringify(old)){followups[pi]=fixed;changed=true;__idxDirty=true}
   }
   /* ⛔ এই নম্বরে কোনো Inquiry-সারিই না থাকলে নিচের পাসটা আগেও **কিছুই**
      বদলাত না (শর্তটা কারও সঙ্গে মিলত না) — তাই বাদ দিলেও ফল হুবহু একই।
      চালানোর পরে ওই সারিগুলো 'Registered' হয়ে যায়, তাই নম্বরটা তালিকা থেকে
      সরিয়ে দেওয়া হয় — আগেও দ্বিতীয়বার আর মিলত না। */
   if(__inqMobs.has(mm)){
   followups=followups.map(f=>{
    if(__M(f.mobile)===mm&&String(f.stage||'')==='Inquiry'){
     changed=true;return {...f,previousStage:f.previousStage||'Inquiry',stage:'Registered',status:'Closed',nextFollow:'',convertedPatientId:p.id,convertedAt:f.convertedAt||now,updatedAt:now,lastRemark:'Converted to Patient Registration'}
    }
    return f
   });
   /* ⛔ এই পাসটা শুধু **Inquiry**-সারিগুলো বদলায় — **Patient**-সারির অবস্থান বা
      stage কিছুই বদলায় না। তাই ধাপ ২-এর ('Patient') তালিকাটা এখনো ঠিকই আছে;
      শুধু 'Inquiry' তালিকাটা বাসি হয়, সেটাই বাতিল করা হয় (অকারণে বারবার
      পুরো তালিকা নতুন করে বানানো বন্ধ)। */
   __inqMobs.delete(mm);if(__idxStage==='Inquiry')__idxDirty=true;
   }
   /* একই যুক্তি — না-রূপান্তরিত এনকোয়ারি না থাকলে এই পাসটাও কিছুই বদলাত না।
      চালানোর পরে status/stage 'Registered' হয়ে যায় ⇒ `isConvertedOrClosed`
      সত্যি হয়, তাই আগেও দ্বিতীয়বার মিলত না। */
   if(__openEnqMobs.has(mm)){
   enquiries=enquiries.map(e=>{
    if(__M(e.mobile)===mm&&!isConvertedOrClosed(e)){
     changed=true;return {...e,stage:'Registered',status:'Registered',nextFollow:'',convertedPatientId:p.id,convertedAt:e.convertedAt||now,updatedAt:now}
    }
    return e
   });
   __openEnqMobs.delete(mm);
   }
  });
  if(changed){save('enquiries',enquiries);save('followups',followups);forceCloudVisibleRows([...enquiries.map(row=>({table:'enquiries',row})),...followups.map(row=>({table:'followups',row}))]);}
  return changed;
 }catch(e){console.warn('Branch workflow repair failed',e);return false}
}
window["repairBranchWorkflowRows"]=repairBranchWorkflowRows;

function repairConvertedEnquiryRows(){
 try{
  let ps=load('patients'),es=load('enquiries'),fs=load('followups');
  if(!ps.length||!fs.length)return;
  let now=new Date().toISOString(),changed=false,changedF=[];
  let patientByMobile=new Map(ps.map(p=>[mob(p.mobile),p]).filter(x=>x[0]));
  fs=fs.map(f=>{
   let mm=mob(f.mobile),p=patientByMobile.get(mm);
   let e=es.find(x=>mob(x.mobile)===mm&&(String(x.status||'').toLowerCase()==='registered'||String(x.stage||'').toLowerCase()==='registered'||x.convertedPatientId));
   if(p&&String(f.stage||'')==='Inquiry'&&(e||f.convertedPatientId||String(f.status||'').toLowerCase()==='closed'||String(f.status||'').toLowerCase()==='registered')){
    changed=true;
    let row={...f,previousStage:f.previousStage||'Inquiry',stage:'Registered',status:'Closed',nextFollow:'',lastRemark:f.lastRemark||'Converted to Patient Registration',convertedPatientId:f.convertedPatientId||p.id,convertedAt:f.convertedAt||now,updatedAt:now};
    changedF.push(row);return row
   }
   return f
  });
  if(changed){save('followups',fs);changedF.forEach(r=>{try{directCloudUpsertRow('followups',r)}catch(_){}})}
 }catch(e){console.warn('Converted enquiry repair skipped',e)}
}
window["repairConvertedEnquiryRows"]=repairConvertedEnquiryRows;


// V259 Canonical workflow formula: Enquiry -> Registration -> Visit must be visible to Master Admin and same-branch staff.
function patientForMobile(mm){mm=mob(mm);if(typeof window._getFollowLookupCache==='function'){let c=window._getFollowLookupCache();return c.patientsByMobile.get(mm)||null}return wlv1PickPatientRow(load('patients').filter(p=>mob(p.mobile)===mm),(typeof user!=='undefined'&&user&&user.branch)||'')||null}
window["patientForMobile"]=patientForMobile;
function isInquiryVisibleRow(x){
 let mm=mob(x&&x.mobile);if(!mm)return false;
 // 🔴🔒 V445 (19.08.2026): same-mobile duplicate guard.  If any Inquiry
 // follow-up row for this mobile is terminal, an older Active duplicate must
 // not resurrect it in the live Follow-up list.  A real Restore sets every
 // matching row back to Active, so this guard automatically releases then.
 // The set is built ONCE per Follow-up render in _buildFollowLookupCache —
 // never one full-storage scan per card, so the old loading-delay fix stays intact.
 try{let c=window._getFollowLookupCache&&window._getFollowLookupCache();if(c&&c.closedInquiryMobiles&&c.closedInquiryMobiles.has(mm))return false}catch(_e){}
 return !patientForMobile(mm)&&!isConvertedOrClosed(x)
}
