function followRecordDate(x,stage){
 let d=stage==='Inquiry'?(x.date||x.recordDate||x.nextFollow||''):(stage==='Patient'?(x.visitDate||x.date||x.recordDate||x.registrationDate||''):(x.registrationDate||x.recordDate||x.visitDate||x.date||''));
 return String(d||'').slice(0,10);
}
window["followRecordDate"]=followRecordDate;
function currentWeekRange(){
 let d=new Date(today()+'T00:00:00');
 let day=d.getDay(); // 0 Sunday, 1 Monday
 let diff=(day===0?-6:1-day); // Monday start
 let a=new Date(d);a.setDate(d.getDate()+diff);
 let b=new Date(a);b.setDate(a.getDate()+6);
 let fmt=x=>x.toISOString().slice(0,10);
 return [fmt(a),fmt(b)];
}
window["currentWeekRange"]=currentWeekRange;
function currentMonthRange(){
 let d=new Date(today()+'T00:00:00');
 let a=new Date(d.getFullYear(),d.getMonth(),1);
 let b=new Date(d.getFullYear(),d.getMonth()+1,0);
 let fmt=x=>x.toISOString().slice(0,10);
 return [fmt(a),fmt(b)];
}
window["currentMonthRange"]=currentMonthRange;
// 🆕 TK-নির্দেশ (04.08.2026 — "তিনটে জায়গায় কার্যকারিতা এক হবে"): ফোনের
// FollowUpActivity-এর `lastStaffFromHistory()`/`prettyStaff()`-এর হুবহু
// একই নিয়ম — সারির `history`-র সবচেয়ে নতুন (শেষ) এন্ট্রি থেকে যার নামে
// staff লেখা আছে তাই খোঁজা, তারপর codeName() দিয়ে মোবাইল হলে নামে বদলানো
// (নাম হলে অপরিবর্তিত থাকে) — নতুন কোনো ক্লাউড-কল/কলাম লাগেনি, রো-তে
// আগে থেকেই থাকা history ব্যবহার হয়।
function wlv1LastCallBy(row){
  try{
    const h = (row && row.history) || [];
    for(let i=h.length-1;i>=0;i--){
      const s = String((h[i] && h[i].staff) || '').trim();
      if(s) return codeName(s) || s;
    }
  }catch(_e){}
  return '';
}
