function followFilterRange(mode){
 if(mode==='Today')return [today(), today()];               // native fToday
 if(mode==='Overdue')return ['1900-01-01', wlv1Yesterday()]; // native fOverdue
 if(mode==='This Week')return currentWeekRange();
 if(mode==='This Month')return currentMonthRange();
 return ['', ''];
}
