/* V386 — অ্যান্ড্রয়েডের `ic_wifi_calls_0..5.xml`-এর হুবহু নকল (SVG)।
   viewport 32×32, আঁকার মাপ 48×40dp, stroke 2.8 round, রং:
   জ্বলা #1067D8 · নেভানো #D8E4F2। নিচ থেকে জ্বলে — বিন্দু(১) → ভিতরের আর্ক(২)
   → (৩) → (৪) → বাইরের আর্ক(৫)।  ⛔ ফাংশনের নাম · প্যারামিটার · onclick ·
   বাইরের ক্লাস সব আগের মতোই, তাই signalTripleTap আগের মতোই কাজ করে।
   ⛔ callSignal() শুধু fuCard()-এ ব্যবহার হয় (যাচাই করা), অন্য কোনো পর্দায় নয়। */
function callSignal(n,followId,dateStr){
 n=Math.max(0,Math.min(5,Number(n||0)));
 var ON='#1067D8',OFF='#D8E4F2';
 var arcs=[
  [5,'M3,12 Q16,1 29,12'],
  [4,'M6,16 Q16,7 26,16'],
  [3,'M9,20 Q16,13 23,20'],
  [2,'M12,24 Q16,19 20,24']
 ];
 var paths=arcs.map(function(a){return '<path fill="none" stroke="'+(n>=a[0]?ON:OFF)+'" stroke-width="2.8" stroke-linecap="round" d="'+a[1]+'"/>'}).join('');
 paths+='<circle cx="16" cy="27" r="2" fill="'+(n>=1?ON:OFF)+'"/>';
 var svg='<svg class="anFuWifi" viewBox="0 0 32 32" width="48" height="40" aria-label="Enquiry calls: '+n+' of 5">'+paths+'</svg>';
 var dateHtml=dateStr?('<div class="signalEnqDate">'+esc(dateStr)+'</div>'):'';
 return '<div class="signalOuterBox" onclick="signalTripleTap(this,\''+esc(followId||'')+'\')"><div class="signalWrap compactSignal" title="Call Progress '+n+'/5">'+svg+'</div><div class="signalEnqLabel">Enquiry</div>'+dateHtml+'</div>'
}
window["callSignal"]=callSignal;
let __sigTapState={id:'',count:0,at:0};
function signalTripleTap(el,followId){
  if(!followId)return;
  let t=Date.now();
  if(__sigTapState.id!==followId||t-__sigTapState.at>900)__sigTapState={id:followId,count:0,at:t};
  __sigTapState.count++;__sigTapState.at=t;
  if(__sigTapState.count>=3){
    __sigTapState={id:'',count:0,at:0};
    event.stopPropagation();
    signalTapMenu(followId);
  }
}
