function signalContinueEntry(followId){
  let rows=load('followups'),i=rows.findIndex(a=>a.id===followId);
  if(i>-1){
   let x=rows[i], now=new Date().toISOString(), mm=mob(x.mobile), stage=String(x.stage||'Inquiry');
   if(stage==='Inquiry' && mm){
    // V448: explicit Continue is the ONLY deliberate reactivation here.
    // Make it durable across every old duplicate of the same enquiry number.
    let hist={date:today(),time:isoNow(),remark:'Continue Entry',staff:user?.name||user?.mobile||'',status:'Active',decisionVersion:'V448'};
    rows=rows.map(function(f){
      if(String(f.stage||'')==='Inquiry' && mob(f.mobile)===mm)
        return {...f,status:'Active',updatedAt:now,history:[...(f.history||[]),hist]};
      return f;
    });
    save('followups',rows);
    let enqs=load('enquiries').map(function(e){return mob(e.mobile)===mm?{...e,status:'Active',updatedAt:now}:e});
    save('enquiries',enqs);
   }else{
    rows[i]={...x,status:'Active',updatedAt:now,history:[...(x.history||[]),{date:today(),time:isoNow(),remark:'Continued',staff:user?.name||user?.mobile||'',status:'Active'}]};
    save('followups',rows);
   }
   try{_invalidateFollowLookupCache()}catch(_e){}
  }
  closeModal();toast('Continue — সচল রাখা হলো');followup(rows[i]?.stage||'Inquiry');
}
