function wlv1DraftPickCancel(){ wlv1DraftPicks.clear(); draffHome(wlv1DraftPickTab||'home'); }
window["wlv1DraftPickCancel"]=wlv1DraftPickCancel;
function wlv1DraftPickedList(){
  var out=[];
  wlv1DraftPicks.forEach(function(id){ var m=wlv1DraftPickMeta[id]; if(m) out.push({id:id,m:m}); });
  return out;
}
async function wlv1DraftBulkRestore(){
  var picked=wlv1DraftPickedList();
  if(!picked.length) return toast('Nothing selected');
  var names=picked.map(function(p){return '• '+p.m.label}).join('\n');
  if(!confirm('Restore '+picked.length+' record(s)?\n\n'+names)) return;
  var done=0, failed=0;
  for(var i=0;i<picked.length;i++){
    try{ restoreDraftEntry(picked[i].id, picked[i].m.stage, picked[i].m.tab, true); done++; }
    catch(e){ failed++; }
  }
  var tab=wlv1DraftPickTab; wlv1DraftPicks.clear();
  toast(done+' restored'+(failed?' · '+failed+' failed':''));
  draffHome(tab||'home');
}
window["wlv1DraftBulkRestore"]=wlv1DraftBulkRestore;
async function wlv1DraftBulkDelete(){
  var picked=wlv1DraftPickedList();
  if(!picked.length) return toast('Nothing selected');
  var allowed=picked.filter(function(p){return p.m.delOk});
  var blocked=picked.length-allowed.length;
  if(!allowed.length) return toast('Master permission needed — nothing deleted');
  var names=allowed.map(function(p){return '• '+p.m.label}).join('\n');
  var extra=blocked?('\n\n'+blocked+' skipped (Master permission needed).'):'';
  if(!confirm('Delete '+allowed.length+' record(s)?\n\nThey move to Trash Bin (Master can restore).\n\n'+names+extra)) return;
  var done=0, failed=0;
  for(var i=0;i<allowed.length;i++){
    var m=allowed[i].m;
    try{
      var ok=await wlv1DeleteDraftEntry(m.delTable,m.delId,m.mobile,m.branch,m.delDate,m.label,m.cardPaid,true);
      if(ok) done++; else failed++;
    }catch(e){ failed++; }
  }
  var tab=wlv1DraftPickTab; wlv1DraftPicks.clear();
  toast(done+' deleted'+(failed?' · '+failed+' failed':'')+(blocked?' · '+blocked+' skipped':''));
  draffHome(tab||'home');
}
window["wlv1DraftBulkDelete"]=wlv1DraftBulkDelete;
