const WLV1_VISUAL_BN = {'External Piles':'বাহ্যিক অর্শ','Internal Piles':'অভ্যন্তরীণ অর্শ','Fissure':'ফিসার','Fistula Opening':'ফিস্টুলার মুখ','Bleeding':'রক্ত পড়ে','Swelling':'ফোলাভাব'};
const WLV1_DRE_BN = {'Tenderness':'কোমলতা/ব্যথা','Internal Piles':'অভ্যন্তরীণ অর্শ','Fissure':'ফিসার','Fistula':'ফিস্টুলা'};
const WLV1_INVEST_BN = {'MRI':'এমআরআই','USG':'আল্ট্রাসাউন্ড','Colonoscopy':'কোলোনোস্কোপি','Lab Reports':'ল্যাব রিপোর্ট'};
const WLV1_GRADE_BN = {'Grade I':'গ্রেড I','Grade II':'গ্রেড II','Grade III':'গ্রেড III','Grade IV':'গ্রেড IV'};
