  // "আসবে বলেছে → আসার তারিখ" / "Attendance confirmed" দেখাই। ⛔ আসল টাকা-সারি অটুট।
  var pt=String(x.payType||'').toLowerCase();
  if(pt==='chamber_expected'){rows.push({date:x.date||'',time:x.createdAt||x.time||'',dot:'exp',type:'আসবে বলেছে',by:codeName(x.receivedBy||x.createdBy||''),note:'আসার তারিখ: '+wlv1Dot(x.date||'')});return;}
