window["patientHistoryDesktop"]=patientHistoryDesktop;
function isTreatmentPaymentRow(x){
 let t=String(x?.payType||'treatment').toLowerCase(), r=String(x?.remarks||'').toLowerCase(), lbl=String(x?.payLabel||x?.paymentLabel||'').toLowerCase();
 if(t==='registration'||t==='visitfee'||t==='visit_fee'||r.includes('visit fee')||r.includes('registration fee')||lbl.includes('visit fee'))return false;
 return t==='treatment' || !t;
}
window["isTreatmentPaymentRow"]=isTreatmentPaymentRow;
/* 🔒 V452 (19.08.2026, TK-approved A): one patient + one calendar day = one
   Treatment Payment. The daily row may contain both CASH and ONLINE, but the
   two amounts stay separate internally. Legacy same-day rows are grouped only
   for display/accounting; they are not deleted or rewritten here. */
function wlv1PaymentSplit(x){
 let total=Number(x?.amount||0), hasC=x&&Object.prototype.hasOwnProperty.call(x,'cashAmount')&&x.cashAmount!==''&&x.cashAmount!=null,
     hasO=x&&Object.prototype.hasOwnProperty.call(x,'onlineAmount')&&x.onlineAmount!==''&&x.onlineAmount!=null;
 let cash=hasC?Number(x.cashAmount||0):0, online=hasO?Number(x.onlineAmount||0):0;
 if((hasC||hasO)&&(cash>0||online>0))return {cash:Math.max(0,cash),online:Math.max(0,online),total};
 let m=String(x?.mode||'CASH').toUpperCase();
 return (m==='UPI'||m==='ONLINE')?{cash:0,online:total,total}:{cash:total,online:0,total};
}
window["wlv1PaymentSplit"]=wlv1PaymentSplit;
function wlv1SplitMode(cash,online){return Number(cash||0)>0&&Number(online||0)>0?'MIXED':(Number(online||0)>0?'ONLINE':'CASH')}
window["wlv1SplitMode"]=wlv1SplitMode;
function wlv1DailyOwner(x){let a=String(x?.patientId||'').trim(),b=String(x?.patientCode||'').trim();if(a)return 'pid:'+a;if(b)return 'code:'+b;return 'mob:'+mob(x?.mobile||'')+'|'+String(x?.branch||'').toLowerCase()}
function wlv1EventCount(x){return Array.isArray(x?.dailyEvents)&&x.dailyEvents.length?x.dailyEvents.length:1}
function wlv1MergeDailyTreatmentRows(rows){
 let pass=[],groups=new Map();
 (Array.isArray(rows)?rows:[]).forEach(x=>{
  if(!x||!isTreatmentPaymentRow(x)||!String(x.date||'').slice(0,10)){pass.push(x);return}
  let key=wlv1DailyOwner(x)+'|'+String(x.date||'').slice(0,10);
  if(!groups.has(key))groups.set(key,[]);groups.get(key).push(x);
 });
 let merged=[...groups.values()].map(g=>{
  let a=g.slice().sort((x,y)=>String(x.createdAt||x.date||'').localeCompare(String(y.createdAt||y.date||''))||String(x.id||'').localeCompare(String(y.id||'')));
  let base={...a[0]},total=0,cash=0,online=0,events=[],remarks=[];
  a.forEach(r=>{
   let sp=wlv1PaymentSplit(r);total+=Number(r.amount||0);cash+=sp.cash;online+=sp.online;
   if(Array.isArray(r.dailyEvents)&&r.dailyEvents.length)r.dailyEvents.forEach(e=>{if(e)events.push({...e})});
   else events.push({eventId:r.id||'',amount:Number(r.amount||0),mode:(sp.online>0&&sp.cash<=0?'ONLINE':'CASH'),receivedBy:r.receivedBy||'',createdBy:r.createdBy||'',createdAt:r.createdAt||'',remarks:r.remarks||''});
   let q=String(r.remarks||'').trim();if(q&&!remarks.includes(q))remarks.push(q);
  });
  let latest=a[a.length-1]||base;
  return {...base,amount:total,cashAmount:cash,onlineAmount:online,mode:wlv1SplitMode(cash,online),dailyEvents:events,
    remarks:remarks.join(' | '),updatedAt:latest.updatedAt||base.updatedAt,createdAt:latest.createdAt||base.createdAt,
    _dailyEventCount:events.length||a.length,_dailyRawCount:a.length,_dailyRawIds:a.map(r=>r.id).filter(Boolean)};
 });
 return pass.concat(merged);
}
window["wlv1MergeDailyTreatmentRows"]=wlv1MergeDailyTreatmentRows;
function wlv1BuildTreatmentEventRow(p,amt,mode,payDate,payLabel,remarks,extra={}){
 let id=uid('pay'),now=new Date().toISOString(),m=String(mode||'CASH').toUpperCase(),online=(m==='UPI'||m==='ONLINE'),cashAmt=online?0:Number(amt||0),onlineAmt=online?Number(amt||0):0;
 let ev={eventId:id,amount:Number(amt||0),mode:online?'ONLINE':'CASH',receivedBy:extra.receivedBy||user?.mobile||'',createdBy:extra.createdBy||extra.receivedBy||user?.mobile||'',createdAt:now,remarks:remarks||payLabel};
 return {id,payType:'treatment',payLabel,paymentLabel:payLabel,patientId:p.id,patientCode:String(p.patientId||''),mobile:p.mobile,branch:p.branch,name:p.name,date:String(payDate||today()).slice(0,10),amount:Number(amt||0),mode:online?'ONLINE':'CASH',cashAmount:cashAmt,onlineAmount:onlineAmt,dailyEvents:[ev],remarks:remarks||payLabel,receivedBy:ev.receivedBy,createdBy:ev.createdBy,createdAt:now,updatedAt:now,...extra};
}
window["wlv1BuildTreatmentEventRow"]=wlv1BuildTreatmentEventRow;
function wlv1UpsertDailyTreatmentLocal(row){
 let pays=load('payments'),day=String(row.date||'').slice(0,10),owner=wlv1DailyOwner(row);
 let matches=pays.filter(x=>isTreatmentPaymentRow(x)&&String(x.date||'').slice(0,10)===day&&wlv1DailyOwner(x)===owner)
   .sort((x,y)=>String(x.createdAt||x.date||'').localeCompare(String(y.createdAt||y.date||''))||String(x.id||'').localeCompare(String(y.id||'')));
 if(!matches.length){
   let fresh=withMeta('payments',row,true);pays.unshift(fresh);save('payments',pays);return fresh;
 }
 let old=matches[0],osp=wlv1PaymentSplit(old),nsp=wlv1PaymentSplit(row),events=[];
 if(Array.isArray(old.dailyEvents)&&old.dailyEvents.length)events=old.dailyEvents.map(e=>({...e}));
 else events=[{eventId:old.id||'',amount:Number(old.amount||0),mode:(osp.online>0&&osp.cash<=0?'ONLINE':'CASH'),receivedBy:old.receivedBy||'',createdBy:old.createdBy||'',createdAt:old.createdAt||'',remarks:old.remarks||''}];
 (Array.isArray(row.dailyEvents)?row.dailyEvents:[]).forEach(e=>{if(e&&!events.some(q=>String(q.eventId||'')===String(e.eventId||'')))events.push({...e})});
 let cash=osp.cash+nsp.cash,online=osp.online+nsp.online,total=Number(old.amount||0)+Number(row.amount||0);
 let oldRem=String(old.remarks||'').trim(),newRem=String(row.remarks||'').trim(),rem=oldRem&&newRem&&oldRem!==newRem?oldRem+' | '+newRem:(newRem||oldRem);
 let merged=withMeta('payments',{...old,amount:total,cashAmount:cash,onlineAmount:online,mode:wlv1SplitMode(cash,online),dailyEvents:events,remarks:rem,updatedAt:row.updatedAt||new Date().toISOString()},false);
 let oi=pays.findIndex(x=>String(x.id)===String(old.id));if(oi>=0)pays[oi]=merged;save('payments',pays);
 return merged;
}
window["wlv1UpsertDailyTreatmentLocal"]=wlv1UpsertDailyTreatmentLocal;
function treatmentTotals(p){
 // V232 Priority Fix: Patient Tab progress must never include Visit Fee / Registration Fee.
 if(!p)return {bill:0,paid:0,due:0,pct:0,pays:[]};
 // 🔒 V217 (§B216): refund row আগে পুরোপুরি বাদ পড়ত (isTreatmentPaymentRow
 // refund-কে false ধরত) — তাই approved refund-ও এখানে ধরাই পড়ত না, Report
 // Card-এর PAID বাক্স ভুল দেখাত। এখন refund row-ও অন্তর্ভুক্ত, আর যোগফল
 // wlv1PayEffect দিয়ে (approved বিয়োগ, pending/rejected অপ্রভাবিত)।
  /* 🔵🔒 V520: `payOwnedBy` নিজেই এখন মোবাইল-fallback সামলায় ও দুই রোগীর টাকা আলাদা রাখে — তাই এখানকার বাড়তি কাঁচা মোবাইল-মিলটা সরানো হয়েছে (নইলে ওই সুরক্ষা ফাঁকি দিয়ে যেত)। ⛔ এক রোগী হলে ফলাফল অবিকল আগের মতোই, কারণ payOwnedBy ওই ক্ষেত্রে মোবাইল মিললেই true বলে। */
 let raw=load('payments').filter(x=>(isTreatmentPaymentRow(x)||wlv1IsRefundRow(x))&&payOwnedBy(x,p));
 let treats=wlv1MergeDailyTreatmentRows(raw.filter(isTreatmentPaymentRow));
 let refunds=raw.filter(wlv1IsRefundRow),pays=refunds.concat(treats);
 let bill=Number(p.bill||0);
 let paid=pays.reduce((s,x)=>s+wlv1PayEffect(x),0);
 let due=Math.max(0,bill-paid);
 let pct=bill?Math.min(100,Math.round(paid/bill*100)):0;
 return {bill,paid,due,pct,pays,treatmentCount:treats.length};
}
window["treatmentTotals"]=treatmentTotals;
function treatmentPayCard(p){let t=treatmentTotals(p);return `<div class="card payCard"><div class="row"><div><b class="wlv1NameLink" onclick="patientHistoryDesktop('${p.id}')" title="Tap for History">${esc(p.name)}</b><br><span class="mut">ID: ${esc(p.patientId)} · <span class="wlv1CallLink" onclick="event.stopPropagation();contact('${esc(p.mobile)}','call')" title="Tap to call">${esc(normMob(p.mobile||''))}</span></span></div><div class="payCircle" style="--pct:${t.pct}"><b>${t.pct}%</b><small>Paid</small></div></div><div class="payColorStats"><div class="statTotal"><small>Total Bill</small><b>${t.bill?money(t.bill):''}</b></div><div class="statPaid"><small>Paid</small><b>${money(t.paid)}</b></div><div class="statDue"><small>Due</small><b>${money(t.due)}</b></div><div class="statNext"><small>Payments</small><b>${t.treatmentCount}</b></div></div><div class="progress"><div class="bar" style="width:${t.pct}%"></div></div><div class="actions"><button onclick="addTreatmentPayment('${p.id}')">Add Payment</button><button class="ghost" onclick="paymentHistory('${p.id}','treatment')">Payment History</button><button class="small ghost" onclick="summary('${p.id}')">Profile</button><button class="small ghost" onclick="openPrintMenu('${p.id}')">🖨️ Print</button></div></div>`}
window["treatmentPayCard"]=treatmentPayCard;

function patientPayRows(rows){
 rows=rows||[];
 return rows.map(p=>treatmentPayCard(p)).join('')||'<div class="card mut">No patient found for treatment payment</div>';
}
window["patientPayRows"]=patientPayRows;
