window["hiddenPaymentEditTap"]=hiddenPaymentEditTap;

function patientPhotoHtml(p,cls='payPatientPhoto'){
 let ph=p?.photo||'';
 /* 🔒 খাতার সারি B117 (TK পাশ, 29.07.2026): ছবিতে চাপ দিলে বড় হয়ে খুলবে —
    ফোনের অ্যাপে যেটা আছে, কম্পিউটারেও ঠিক সেটাই।
    ⛔ ছবি না থাকলে আগের মতোই ফাঁকা ঘর, কোনো চাপ কাজ করে না।
    ⛔ শুধু `onclick` ও হাতের চিহ্ন যোগ হলো — ছবির মাপ, ক্লাস, চেহারা
       এক অক্ষরও বদলায়নি, তাই কোথাও লেআউট নড়বে না। */
 return ph
   ? `<img class="${cls}" src="${esc(ph)}" style="cursor:zoom-in" onclick="wlv1ZoomPhoto(this.src);event.stopPropagation();">`
   : `<div class="${cls} blank">👤</div>`;
}
/* =====================================================================
   🔒 খাতার সারি B117 — ছবি জুম (কম্পিউটারের অ্যাপ)
   ⛔ ক্লাউডে কোনো অনুরোধ নেই · ডেটাবেসে কিছু লেখা হয় না — ছবিটা যা আগে
      থেকেই পর্দায় আছে, শুধু সেটাই বড় করে দেখানো হয়।
   ⛔ অ্যাপের নিজের `modal()` ছোঁয়া হয়নি — আলাদা একটা স্তর, তাই কোনো
      পপ-আপের কাজ ভাঙার ভয় নেই। যেখানে চাপ দিন বা Esc — বন্ধ হয়ে যায়।
   ===================================================================== */
function wlv1ZoomPhoto(src){
  try{
    if(!src) return;
    var old=document.getElementById('wlv1ZoomBack'); if(old) old.remove();
    var b=document.createElement('div');
    b.id='wlv1ZoomBack';
    b.style.cssText='position:fixed;inset:0;background:rgba(9,18,30,.92);z-index:400;display:grid;place-items:center;padding:24px;cursor:zoom-out';
    var i=document.createElement('img');
    i.src=src;
    i.style.cssText='max-width:92vw;max-height:88vh;border-radius:12px;box-shadow:0 24px 60px rgba(0,0,0,.5)';
    b.appendChild(i);
    function close(){ try{ b.remove(); document.removeEventListener('keydown',esc); }catch(_e){} }
    function esc(e){ if(e.key==='Escape') close(); }
    b.onclick=close;
    document.addEventListener('keydown',esc);
    document.body.appendChild(b);
  }catch(_e){}
}
window["wlv1ZoomPhoto"]=wlv1ZoomPhoto;
window["patientPhotoHtml"]=patientPhotoHtml;
/* 🔒 TK'S DECISION (27.07.2026, ফটো-প্রুফে পাশ): the Remarks box is removed from
   this payment form (phone app: PaymentActivity, same change).
   TK's reason: "পেমেন্ট নেওয়ার সময় সেই পেশেন্টের কোন ধরনের ট্রিটমেন্ট হবে সেটা তো
   আগে থেকে জানা যায় না। ট্রিটমেন্ট হওয়ার পরই না ট্রিটমেন্ট প্রোগ্রেস কি হবে সেটা
   জানা যাবে।" Money is taken BEFORE the treatment, so what is typed here can never
   be that day's real Treatment Progress -- yet the Report Card's Progress column
   reads exactly this text. Progress is written only AFTER treatment, from Chamber
   Attendance's "Treatment Progress" box (or the Report Card's own 3-tap edit).
   The save line below is unchanged: $('#prem') simply no longer exists, so it falls
   back to the payment's own label -- exactly what the phone stores for a blank
   remark, and what the Timeline/Report Card already treat as "no remark written".
   Nothing else on this form moves: TOTAL AMOUNT (with its locked look and 3-tap
   unlock), Amount, Payment Mode, Date and the Save button keep their places. */
function addTreatmentPayment(id){
 let p=load('patients').find(x=>x.id===id);
 if(!p)return toast('Patient link missing. Please retry');
 if(!searchCanSeeFinance(p))return toast('Payment not allowed for other branch');
 let t=treatmentTotals(p),billNum=Number(p.bill||0),locked=billNum>0;
 let nextLabel=nextPaymentLabel(id);
 let hasPaid=t.paid>0;
 /* 🔴 V509 (TK-সিদ্ধান্ত ২১.০৮.২০২৬): DUE-তে চাপ দিয়ে Refund খোলার দরজাটা
    এতদিন শুধু `t.paid > 0` দেখত — আর Visit Fee কখনো `paid`-এ ধরা হয় না।
    তাই যে রোগী **শুধু Visit Fee** দিয়েছেন, তাঁর DUE চাপলে কিছুই হত না।
    এখন Visit Fee-ও ধরা হয় (ফোনের অ্যাপের হুবহু একই নিয়ম)।
    ⛔ PAID-এ চাপ (পুরনো পেমেন্টের তালিকা) আগের ঠিক একই শর্তে — বদলায়নি। */
 let canRefund=wlv1RefundableNow(p)>0;
 let dis=String(p.disease||'').trim(),addr=String(p.address||'').trim();
 __treatPayReceipt='none';
 let disChip=dis?`<span class="ptcDis">🩸 ${esc(dis)}</span>`:'';
 let addrRow=addr?`<div class="ptcAddr">📍 ${wlv1AddrTwo(addr)}</div>`:'';
 let paidPill=`<div class="ptcPill ptcPaid ${hasPaid?'ptcTap':''}" ${hasPaid?`onclick="paymentHistory('${esc(id)}','treatment')"`:''}><small>PAID</small><b>${money(t.paid)}</b><i>&nbsp;</i></div>`;
 let duePill=`<div class="ptcPill ptcDue ${canRefund?'ptcTap':''}" ${canRefund?`onclick="openRefundFormWeb('${esc(id)}')"`:''}><small>DUE</small><b>${billNum>0?money(t.due):'-'}</b><i>&nbsp;</i></div>`;
 modal(`<div class="paymentCompactModal payTreatWrap">
  <div class="payTreatHead">💰 Add Treatment Payment</div>
  <div class="payTreatCard">
   <div class="ptcHead">
    <div class="ptcPhotoWrap">${patientPhotoHtml(p,'ptcPhoto')}</div>
    <div class="ptcHeadInfo">
     <div class="ptcRow1"><b class="ptcName" onclick="closeModal();summary('${esc(id)}')">${esc(p.name||'')}</b>${disChip}</div>
     <div class="ptcRow2"><span class="ptcId" onclick="closeModal();summary('${esc(id)}')">${esc(p.patientId||'')}</span><span class="ptcMob">📞 ${esc(normMob(p.mobile||''))}</span></div>
     ${addrRow}
    </div>
   </div>
   <div class="ptcPills">
    <div class="ptcPill ptcBill ptcTap" onclick="treatBillTap('${esc(id)}')"><small>BILL</small><b id="ptcBillVal">${billNum>0?money(billNum):(t.paid>0?'⚠️ Not Set':money(0))}</b><i>&nbsp;</i></div>
    ${paidPill}${duePill}
   </div>
  </div>
  <div id="treatBillEdit" style="display:none;margin:8px 0 2px"><label>Edit Total Bill</label><input id="bill" class="input" inputmode="numeric" value="${billNum>0?billNum:''}" oninput="var e=document.getElementById('ptcBillVal');if(e)e.textContent='₹'+(this.value||'0')"></div>
  <input id="disc" type="hidden" value="0">
  <label>${esc(nextLabel)} Amount</label>
  <input id="amt" class="input" inputmode="numeric" onblur="lockAmountOnBlur('amt')">
  <label>Payment Mode</label>
  <input id="mode" type="hidden" value="CASH">
  <div class="ptModeRow"><div class="ptModeBox on" data-m="CASH" onclick="treatSetMode('CASH')">💵 CASH</div><div class="ptModeBox" data-m="ONLINE" onclick="treatSetMode('ONLINE')">🏦 ONLINE</div></div>
  <input id="payDateShow" class="input ptDateBox" readonly placeholder="Actual deposit date" onclick="treatPickDate()">
  <input id="payDate" type="hidden" value="">
  <input id="payDateInp" type="date" max="${today()}" style="position:absolute;left:-9999px" onchange="treatOnDate(this.value)">
  <div class="payTreatBtns"><button class="ptBtn ptCancel" onclick="closeModal()">CANCEL</button><button class="ptBtn ptShare" onclick="treatPaySubmit('${esc(id)}','share')">🟢 SHARE</button><button class="ptBtn ptPrint" onclick="treatPaySubmit('${esc(id)}','print')">🖨 PRINT</button><button class="ptBtn ptSave" onclick="treatPaySubmit('${esc(id)}','save')">💾 SAVE</button></div>
 </div>`)
}
window["addTreatmentPayment"]=addTreatmentPayment;
/* 🔒 ওয়েব Treatment Payment — অ্যান্ড্রয়েডের নতুন ডিজাইনে (সবুজ হেডার +
   নাম/ID চাপলে জার্নি + রোগ + ঠিকানা ২-লাইন + BILL/PAID/DUE পিল + ৪ বোতাম)।
   টাকার লজিক (#bill/#disc/#amt/#mode পড়ে saveTreatmentPayment) হুবহু আগের
   মতোই — শুধু চেহারা+বোতাম যোগ; কোনো money-লজিক বদলায়নি। */
var __treatBillTap={id:'',count:0,at:0};
function treatBillTap(id){
 var now=Date.now(),k=String(id||'');
 if(__treatBillTap.id!==k||now-__treatBillTap.at>1400)__treatBillTap={id:k,count:0,at:now};
 __treatBillTap.count++;__treatBillTap.at=now;
 if(__treatBillTap.count===2)toast('Tap 1 more time to edit');
 if(__treatBillTap.count>=3){__treatBillTap={id:'',count:0,at:0};var e=document.getElementById('treatBillEdit');if(e){e.style.display='block';var b=document.getElementById('bill');if(b){b.removeAttribute('readonly');b.focus();}toast('Bill edit unlocked')}}
}
window["treatBillTap"]=treatBillTap;
var __treatPayReceipt='none';
function treatPaySubmit(id,mode){
 __treatPayReceipt=(mode==='print')?'print':(mode==='share'?'share':'none');
 saveTreatmentPayment(id);
}
window["treatPaySubmit"]=treatPaySubmit;
/* 🔒 B570 (08.08.2026, TK-অনুমোদিত প্রুফ): CASH/ONLINE পাশাপাশি টগল বক্স (dropdown নয়)।
   চাপলে হাইলাইট; নির্বাচিত মান লুকানো #mode-এ বসে (saveTreatmentPayment আগের মতোই #mode পড়ে)। */
function treatSetMode(m){
 var h=document.getElementById('mode');if(h)h.value=(m==='ONLINE')?'ONLINE':'CASH';
 [].slice.call(document.querySelectorAll('.ptModeBox')).forEach(function(b){b.classList.toggle('on',b.getAttribute('data-m')===m)});
}
window["treatSetMode"]=treatSetMode;
/* তারিখ: ধূসর "প্রকৃত জমার তারিখ" বক্স; চাপলে ডেট-পিকার। না বাছলে আজকের তারিখ (আগের আচরণ)। */
function treatPickDate(){var e=document.getElementById('payDateInp');if(e){e.showPicker?e.showPicker():e.click()}}
window["treatPickDate"]=treatPickDate;
function treatOnDate(v){if(!v)return;var h=document.getElementById('payDate');if(h)h.value=v;var s=document.getElementById('payDateShow');if(s)s.value=wlv1Dot(v);}
window["treatOnDate"]=treatOnDate;
/* TK (27.07.2026): এই রোগীর আগে কত টাকা জমা পড়েছে (শুধু ট্রিটমেন্টের কিস্তি) — প্রথম পেমেন্ট কিনা সেটা বোঝার জন্য। */
function t_paidSoFar(id){try{const p=load('patients').find(x=>x.id===id)||{id:id};return load('payments').filter(x=>payOwnedBy(x,p)&&isTreatmentPaymentRow(x)).reduce((s,x)=>s+Number(x.amount||0),0)}catch(e){return 0}}
window["t_paidSoFar"]=t_paidSoFar;
/* 🔒 TK'S LOCKED RULE (27.07.2026): "Bill · advance · any payment — যে ব্রাঞ্চের
   স্টাফ তারাই করতে পারবে। অন্য কোনো ব্রাঞ্চের স্টাফ করতে পারবে না। সংশ্লিষ্ট
   ব্রাঞ্চের ডাক্তার করতে পারবে। মাস্টার করতে পারবে।"
   Enquiry and Registration are deliberately cross-branch (one advertised number,
   and a branch picker on the form). Money is not: the cash is handed over at one
   chamber, so if another branch's staff could take it, that branch's Today's
   Collection and Chamber Register would never match the drawer.
   The patient's branch is read from the branch field OR the Patient ID's branch
   code (COB-...), the same two-way check used elsewhere. If a record has neither,
   the payment is ALLOWED -- never lose a real payment over a missing branch. */
function wlv1CanTakeMoney(p){
  try{
    if(!user) return true;
    if(isMaster()) return true;
    const mine=String(user.branch||'').trim();
    if(!mine||mine.toLowerCase()==='all') return true;
    const theirs=String((p&&p.branch)||'').trim();
    if(theirs&&sameBranch(theirs,mine)) return true;
    const code=String((p&&p.patientId)||'').split('-')[0].trim();
    if(code.length===3){
      const myCode=(typeof lockedBranchCode==='function')?String(lockedBranchCode(mine)||''):'';
      return !!myCode&&code.toUpperCase()===myCode.toUpperCase();
    }
    return !theirs;
  }catch(e){ return true; }
}
window["wlv1CanTakeMoney"]=wlv1CanTakeMoney;
function wlv1MoneyBlockMsg(p){
  const br=(String((p&&p.branch)||'').trim()||'another branch').toUpperCase();
  return 'This patient belongs to '+br+'. Only '+br+' staff, its doctor, or Master can take a Bill / Advance / Payment.';
}
window["wlv1MoneyBlockMsg"]=wlv1MoneyBlockMsg;

async function saveTreatmentPayment(id){
 let p=load('patients').find(x=>x.id===id),oldBill=Number(p?.bill||0),bill=Number($('#bill')?.value||0),discount=0,amt=Number($('#amt')?.value||0);
 if(!p)return toast('Patient not found');
 if(!wlv1CanTakeMoney(p))return toast(wlv1MoneyBlockMsg(p));
 if(oldBill>0&&$('#bill')?.hasAttribute('readonly'))bill=oldBill;
 /* TK (27.07.2026), সুরক্ষা: বিল ছাড়া পেমেন্ট এখন চলে বলে ঘরটা ফাঁকা থাকতে পারে — সেক্ষেত্রে পুরনো বিল যেন কখনো মুছে ০ না হয়ে যায়। */
 if(bill<=0&&oldBill>0)bill=oldBill;
 /* TK-DECISION (27.07.2026): কাউন্টারে স্টাফ ব্যস্ত থাকে — প্রথম পেমেন্ট (Advance) বিল ছাড়াই নেওয়া যাবে, বিল পরে বসানো যাবে। শুধু মনে করিয়ে দেওয়া হবে, আটকানো হবে না। দ্বিতীয় কিস্তি থেকে বিল বাধ্যতামূলক — এটাই বিল-হীন রোগী তৈরি হওয়া ঠেকায়। ফোনের অ্যাপেও ঠিক একই নিয়ম। */
 // 🆕 TK-REPORTED (04.08.2026, ছবিসহ — RABINDRA CHANDRA NAHA): এডভান্স আগেই
 // নেওয়া, পরে ডাক্তার বিল ঠিক করার পরে সেই বিলটা বসাতে গিয়ে Save কাজ করছিল
 // না — "Payment amount" ফাঁকা থাকলেই পুরো Save আটকে যেত, যদিও স্টাফ শুধু
 // বিলটাই বসাতে চাইছিলেন, নতুন কোনো টাকা এই মুহূর্তে নিচ্ছিলেন না। TK নিজে
 // নিশ্চিত করেছেন: "শুধু বিল বসিয়ে (০ টাকা পেমেন্ট) Save করা যাবে"।
 // ⛔ ফোনের FollowUpActivity.kt-এর `updateBillOnly()`-এর হুবহু একই আচরণ —
 // কোনো ভুয়ো "₹0 Payment" তৈরি হয় না, শুধু বিল বসে ও Follow-up রিমার্কে
 // অডিট-নোট লেখা হয়। amt>0 হলে (সত্যিকারের পেমেন্ট) নিচের সব নিয়ম অক্ষত।
 if(amt<=0){
  if(bill>0&&bill!==oldBill){
   upd('patients',id,{bill,discount,stage:p.stage||'Treatment Running',updatedAt:new Date().toISOString()});
   // ⛔ updateFollowAction() ব্যবহার করা হয়নি — সেটা নিজে থেকেই Modal বন্ধ
   // করে অন্য পাতায় (followup list) সরিয়ে দেয়, যা এখানে অপ্রয়োজনীয়/
   // বিভ্রান্তিকর হতো (নিচের patientPaymentHome()-এর সাথে সংঘর্ষ করত)।
   // তাই শুধু history/lastRemark-টুকু সরাসরি লেখা হলো, ঠিক
   // updateFollowAction()-এর ভিতরের একই ধরনের অংশের মতোই।
   try{
    let fus=load('followups'),fi=fus.findIndex(x=>mob(x.mobile)===mob(p.mobile)&&x.stage&&x.stage!=='Inquiry');
    if(fi>=0){
     let note=`💰 Bill corrected ${money(oldBill)} → ${money(bill)} by ${user?.name||codeName(user?.mobile||'')||'User'}`;
     fus[fi]={...fus[fi],lastRemark:note,lastRemarkAt:new Date().toISOString(),updatedAt:new Date().toISOString(),history:[...(fus[fi].history||[]),{date:today(),time:isoNow(),remark:note,staff:user?.name||user?.mobile||''}]};
     save('followups',fus);
    }
   }catch(_e){}
   toast('Bill saved');closeModal();
   try{patientPaymentHome()}catch(e){}
   return;
  }
  return toast('Payment amount required');
 }
 const wlv1FirstPay=!(Number(t_paidSoFar(id))>0);
 if(bill<=0&&!wlv1FirstPay)return toast("This patient's Bill has not been created yet — please create the Bill first");
 /* 🔒 V452 (19.08.2026, TK-approved A): duplicate guard must use the ACTUAL
    payment date, not always today. A second genuine payment on the same date is
    added into that date's one Treatment Payment row. */
 let payDate=($('#payDate')?.value)||today();
 if(!wlv1DayGuardOk(id,p.name,payDate))return;
 let up=upd('patients',id,{bill,discount,stage:p.stage||'Treatment Running',updatedAt:new Date().toISOString()});
 /* 🔒 B570: প্রকৃত জমার তারিখ বাছা থাকলে সেটাই, নইলে আজ (আগের আচরণ)। ফোনের ব্যাকডেট নিয়মের সাথে মেলে। */
 /* 🔴🔒 R1 (TK-অনুমোদিত, 09.08.2026): Backdate গেট — পুরনো তারিখে পেমেন্ট নিলে (মাস্টার নয় ও grant নেই)
    সরাসরি না নিয়ে Master-অনুমোদনের জন্য payment_backdate_requests ফাইল হয় (ফোনের PaymentActivity গেটের হুবহু)।
    ⛔ আজকের তারিখে (picker না খুললে #payDate ফাঁকা → today()) কিছুই বদলায় না — same-day পেমেন্ট অটুট। */
 if(payDate!==today() && !isMaster()){
   try{ if(typeof wlv1PullBackdateGrantsFromCloud==='function') await wlv1PullBackdateGrantsFromCloud(); }catch(_e){}
   if(!(typeof wlv1IsBackdateGranted==='function' && wlv1IsBackdateGranted(payDate))){
     let okReq=await wlv1FileBackdateRequest(p,bill,amt,payMode($('#mode')?.value||'CASH'),($('#prem')?.value||''),payDate);
     if(okReq){ toast('পুরনো তারিখের পেমেন্ট — Master-এর অনুমোদনের জন্য পাঠানো হলো'); closeModal(); try{patientPaymentHome()}catch(e){} }
     return;
   }
 }
 let payLabel=nextPaymentLabel(id,payDate),payModeNow=payMode($('#mode')?.value||'CASH');
 let payRow=wlv1BuildTreatmentEventRow(p,amt,payModeNow,payDate,payLabel,$('#prem')?.value||payLabel);
 wlv1UpsertDailyTreatmentLocal(payRow);
 /* 🔁🔒 V839 (TK-নির্দেশ: *"পেমেন্ট করলেও যেন কাজ হয়"*) — টাকা জমা হলে
    রোগী আবার CHECK-UP তালিকায় ফিরবেন। ⛔ দিনে একবারের পাহারা ভিতরে;
    টাকার অঙ্ক · হিসাব · রসিদ কিচ্ছু ছোঁয়া হয়নি। */
 try{ wlv1NvpReopenQueue(p.mobile); }catch(_e){}
 try{if(typeof window.webRmpActivateAfterPayment==='function')window.webRmpActivateAfterPayment(id);}catch(_e){}
 ensureFollow({...p,...(up||{}),bill,discount,stage:'Treatment Running'},'Treatment','', '');
 /* TK (27.07.2026): আটকানো নয়, শুধু মনে করিয়ে দেওয়া। */
 toast(Number(bill||0)>0?'Treatment payment saved':'Advance saved — Total Bill not set yet, please add it later');closeModal();
 /* 🔒 TK-APPROVED (28.07.2026): পেমেন্টের খবর রোগীকে।
    জমা/বাকি আন্দাজে নয় — payments টেবিলের আসল সারি গুনে বের করা হয়
    (nextPaymentLabel যে নিয়মে গোনে ঠিক সেই নিয়মে), তাই রোগী যা পড়বেন
    তা অ্যাপের হিসাবের সঙ্গে হুবহু মিলবে। */
 try{
  let paidNow=load('payments').filter(x=>payOwnedBy(x,p)&&isTreatmentPaymentRow(x)).reduce(function(a,x){return a+Number(x.amount||0)},0);
  wlv1AskSend(p.branch,p.name,p.mobile,p.patientId,'pay',{amount:Number(amt||0),mode:payMode($('#mode')?.value||'CASH'),bill:Number(bill||0),paid:paidNow,date:wlv1Dot((($('#payDate')?.value)||today()))});
 }catch(_e){}
 /* 🔒 B565 (08.08.2026): PRINT বোতামে চাপলে — সেভ *নিশ্চিত* হওয়ার পরে তবেই রসিদ প্রিন্ট (অ্যান্ড্রয়েডের pendingReceiptMode-এর হুবহু আচরণ)। SHARE-এর WhatsApp আগের wlv1AskSend দিয়েই যায়। money-লজিক অপরিবর্তিত। */
 try{if(__treatPayReceipt==='print'){printPaymentReceipt(id);}}catch(_e){} __treatPayReceipt='none';
 try{patientPaymentHome()}catch(e){}
}
