/* 🔴 V437 #16 — ব্রাঞ্চের ফোন নম্বর (config.js-এর তালিকা থেকে; ফোনে BranchCatalog) */
function medBranchPhone(br){try{var b=(C.branches||[]).find(function(z){return sameBranch(z.name,br)});return b&&b.mobile?String(b.mobile):''}catch(e){return ''}}
