function medStaffName(m){try{return codeName(m||'')||m||''}catch(e){return m||''}}
function medicinePayRows(rows){
  /* 🔴 V437 #11 — ফোনে দুটো আলাদা লেখা (MedicinePaymentActivity.kt:449):
     একটাও বিক্রি না থাকলে "No medicine payment yet.", আর ছাঁকনিতে ঢাকা পড়লে
     "No sale in this filter."। ওয়েবে দুই ক্ষেত্রেই একই লেখা উঠত। */
  if(!rows.length){
    var __anyMed=false;
    try{ __anyMed = scoped(load('products')).some(function(x){return x.kind==='medicinePayment'||x.kind==='salinePayment'}); }catch(e){}
    return '<div class="card mut">'+(__anyMed?'No sale in this filter.':'No medicine payment yet.')+'</div>';
  }
  var __sm=medSettledMap();   /* 🆕 V846 */
  return rows.map(function(x){
    var bill=Number(x.bill||x.total||0),dep=Number(x.deposit||0),due=Math.max(0,bill-dep);   /* 🔴 V437 #14 */
    /* 🆕🔒 V846 — দেখানো "Due" এখন এই মুহূর্তের বাকি (পরে জমা-নেওয়া টাকা বাদ)।
       Bill আর Deposit ওই দিনের নিজের অঙ্কই থাকে, তাই পুরনো কাগজের সঙ্গে মেলে। */
    var settled=Number(__sm[x.id]||0),live=medNetDue(x,__sm);
    var online=String(x.mode||'').toUpperCase()!=='CASH'&&String(x.mode||'')!=='';
    var badge='<span class="medBadge '+(online?'medOnl':'medCash')+'">'+(online?'ONLINE':'CASH')+'</span>';
    return '<div class="medCard"><div class="medCardTop"><div class="medNm">'+esc(x.customer||x.mobile||'Walk-in')+badge+'</div><div class="medAmt">'+money(dep)+'</div></div>'+
      '<div class="medMeds2">💊 '+esc(x.product||'-')+'</div>'+
      '<div class="medMeta">🏥 '+esc(x.branch||'-')+'　👤 '+esc(medStaffName(x.receivedBy||x.createdBy||''))+'　⏰ '+esc(fmtDateTime(x.createdAt||x.date||''))+'</div>'+   /* 🔴 V437 #12 — ফোনে তারিখের সঙ্গে সময়ও (displayWithTime) */
      '<div class="medBD">Bill '+money(bill)+' · Deposit '+money(dep)+' · Due '+money(medIsDueSettleId(x.id)?due:live)+'</div>'+
      (settled>0?'<div class="medDueLater">Due collected later: '+money(settled)+'</div>':'')+
      (live>0?'<button class="medDueBtn" onclick="medOpenCollectDue(\''+esc(String(x.id||''))+'\')">💰 COLLECT DUE '+money(live)+'</button>':'')+
      '</div>';
  }).join('');
}
window["medicinePayRows"]=medicinePayRows;
/* 🆕🔒 V846 — বাকি টাকা জমা নেওয়ার পপ-আপ (ফোনের openCollectDue-এর হুবহু যমজ) */
function medOpenCollectDue(id){
  var all=load('products')||[];
  var x=all.filter(function(z){return String(z.id||'')===String(id)})[0];
  if(!x)return toast('Sale not found');
  var live=medNetDue(x,medSettledMap());
  if(!(live>0))return toast('No due left');
  modal('<h2>💰 Collect Due</h2><div class="card">'+
    '<div class="medDueHead">'+esc(x.customer||x.mobile||'Walk-in')+' · Remaining '+money(live)+'</div>'+
    '<label>Amount</label><input id="medDueAmt" class="input" inputmode="numeric" value="'+String(live)+'">'+
    '<label>Mode</label><select id="medDueMode" class="input"><option>CASH</option><option>ONLINE</option></select>'+
    '<div class="actions"><button onclick="medSaveDueCollection(\''+esc(String(id))+'\')">Collect</button>'+
    '<button class="ghost" onclick="closeModal()">Cancel</button></div></div>');
}
window["medOpenCollectDue"]=medOpenCollectDue;
function medSaveDueCollection(id){
  var all=load('products')||[];
  var x=all.filter(function(z){return String(z.id||'')===String(id)})[0];
  if(!x)return toast('Sale not found');
  var live=medNetDue(x,medSettledMap());
  var amt=Number(($('#medDueAmt')||{}).value||0);
  if(!(amt>0))return toast('Enter an amount');
  if(amt>live)return toast('More than the remaining due');
  var mode=(String((($('#medDueMode')||{}).value)||'').toUpperCase()==='ONLINE')?'ONLINE':'CASH';
  /* ⛔ পুরনো সারিতে হাত পড়ে না — আজকের তারিখে নতুন একটা সারি বসে, তাই আজকের
     কালেকশনে টাকাটা ঠিকভাবে ওঠে আর পুরনো দিনের মোট হুবহু আগের মতোই থাকে। */
  add('products',{
    id:'due_'+String(id)+'_'+Date.now(),
    kind:(x.kind==='salinePayment'?'salinePayment':'medicinePayment'),
    customer:x.customer||'Walk-in',
    product:'DUE PAYMENT — '+(x.product||'-'),
    bill:0,total:0,deposit:amt,due:0,mode:mode,
    remarks:'Due collection for sale dated '+String(x.date||''),
    date:today(),branch:x.branch||user.branch,
    receivedBy:user.mobile,createdBy:user.mobile,createdAt:isoNow()
  });
  closeModal();
  toast('Due collected '+money(amt));
  medRenderHistory();
}
window["medSaveDueCollection"]=medSaveDueCollection;
function medTotalHtml(rows){
  if(__medDueOnly){   /* 🆕 V846 */
    var __sm=medSettledMap(),out=0;
    rows.forEach(function(x){out+=medNetDue(x,__sm);});
    return '<div class="medTotBox"><div class="medTotL">TOTAL OUTSTANDING DUE</div><div class="medTotN">'+money(out)+' · '+rows.length+' '+(rows.length===1?'sale':'sales')+'</div><div class="medTotS">All dates · tap a card\'s button to collect</div></div>';
  }
  var tot=0,cash=0,onl=0;rows.forEach(function(x){var d=Number(x.deposit||0);   /* 🔴 V437 #14 */tot+=d;if(String(x.mode||'').toUpperCase()==='CASH'||!x.mode)cash+=d;else onl+=d;});
  var label=__medFilter==='today'?"TODAY'S MEDICINE SALE":__medFilter==='7'?'LAST 7 DAYS SALE':__medFilter==='30'?'LAST 30 DAYS SALE':__medFilter==='pick'?('SALE ON '+esc(wlv1Dot(__medPick))):__medFilter==='range'?('STATEMENT '+esc(wlv1Dot(__medFrom))+' – '+esc(wlv1Dot(__medTo))):'MEDICINE SALE';   /* 🆕 V847 */
  return '<div class="medTotBox"><div class="medTotL">'+label+'</div><div class="medTotN">'+money(tot)+' · '+rows.length+' '+(rows.length===1?'sale':'sales')+'</div><div class="medTotS">Cash '+money(cash)+' · Online '+money(onl)+'</div></div>';
}
function saveMedicinePayment(action){
  var cust=($('#medCust').value||'').trim(),prod=medCollect(),bill=Number($('#medBill').value||0),dep=Number($('#medDep').value||0),br=($('#medBranch')&&$('#medBranch').value)||user.branch;
  /* 🔴 V437 #15 — ফোনে তিনটে আলাদা বার্তা (FieldError.validate), ওয়েবে একটাই ছিল */
  if(!prod)return toast('Product দিন');
  if(!(bill>0))return toast('সঠিক Bill দিন');
  if(!(dep>0))return toast('সঠিক Deposit দিন');
  if(dep>bill&&!confirm('Deposit is more than bill. Continue?'))return;
  var row={id:uid('prd'),kind:__medType,   /* 🆕 V805 */ customer:cust||'Walk-in',product:prod,bill:bill,total:bill,deposit:dep,due:Math.max(0,bill-dep),mode:(String($('#medMode').value||'').toUpperCase()==='CASH'?'CASH':'ONLINE'),   /* 🔴 V437 — নিচের টীকা দেখুন */remarks:'',date:(__medActualDate||today()),branch:br,   /* 🔄 V849 */receivedBy:user.mobile,createdBy:user.mobile,createdAt:isoNow()};
  add('products',row);
  toast('Medicine payment saved');
  if(action==='share')medShareReceipt(row);
  else if(action==='print')medPrintReceipt(row);
  medicinePaymentHome();
}
window["saveMedicinePayment"]=saveMedicinePayment;
function medBranchAddr(br){var b=((typeof C!=='undefined'&&C.branches)||[]).find(function(x){return String(x.name||'').toLowerCase()===String(br||'').toLowerCase()});return b&&b.address?b.address:'';}
function medClinicName(br){return String(br)==='Kishanganj'?'TK BISWAS PILES CLINIC':'MAA AYURVED PILES CLINIC';}
function medReceiptText(x){
  var bill=Number(x.bill||x.total||0),dep=Number(x.deposit||0),due=Math.max(0,bill-dep);
  /* 🔴 V437 #16 — ফোনের বার্তায় (MedicinePaymentActivity.kt:757-772) ঠিকানার নিচে
     ব্রাঞ্চের **ফোন নম্বর** থাকে, তারিখের সঙ্গে **সময়**, আর শেষে
     "Thank you. Get well soon." — তিনটেই ওয়েবে বাদ পড়েছিল। */
  return '*'+medClinicName(x.branch)+'*\n'+(medBranchAddr(x.branch)?medBranchAddr(x.branch)+'\n':'')+(medBranchPhone(x.branch)?'Ph: '+medBranchPhone(x.branch)+'\n':'')+'--------------------------------\n*MEDICINE PAYMENT RECEIPT*\n\nPatient : '+(x.customer||'Walk-in')+'\nMedicine: '+(x.product||'-')+'\nBill    : '+money(bill)+'\nPaid    : '+money(dep)+'  ('+(x.mode||'CASH')+')\nDue     : '+money(due)+'\n\nDate    : '+fmtDateTime(x.createdAt||x.date||'')+'\nBranch  : '+(x.branch||'')+'\nReceived by: '+medStaffName(x.receivedBy||'')+'\n\nThank you. Get well soon.';
}
function medShareReceipt(x){try{window.open('https://wa.me/?text='+encodeURIComponent(medReceiptText(x)),'_blank')}catch(e){toast('Could not open WhatsApp')}}
function medPrintReceipt(x){
  var bill=Number(x.bill||x.total||0),dep=Number(x.deposit||0),due=Math.max(0,bill-dep);
  var html='<!doctype html><html><head><meta charset="utf-8"><title>Receipt</title><style>body{font-family:Arial;color:#111;padding:14mm;font-size:13px}.h{text-align:center;border-bottom:2px solid #0B2B59;padding-bottom:8px;margin-bottom:12px}.cn{font-size:20px;font-weight:800;color:#0B2B59}.tt{text-align:center;font-weight:800;color:#0B7A34;margin:8px 0 14px;letter-spacing:1px}table{width:100%;border-collapse:collapse}td{padding:7px 4px;border-bottom:1px solid #eee}td.k{color:#555;width:40%}td.v{font-weight:700}.due{color:#b0392b}</style></head><body>'+
    /* 🔴 V437 #16 — ফোনের কাগজে ব্রাঞ্চের ফোন নম্বরও থাকে ("Ph: …"), ওয়েবে ছিল না */
    '<div class="h"><div class="cn">'+esc(medClinicName(x.branch))+'</div><div>'+esc(medBranchAddr(x.branch))+'</div>'+(medBranchPhone(x.branch)?'<div>Ph: '+esc(medBranchPhone(x.branch))+'</div>':'')+'</div><div class="tt">MEDICINE PAYMENT RECEIPT</div><table>'+
    '<tr><td class="k">Patient</td><td class="v">'+esc(x.customer||'Walk-in')+'</td></tr>'+
    '<tr><td class="k">Medicine</td><td class="v">'+esc(x.product||'-')+'</td></tr>'+
    '<tr><td class="k">Total Bill</td><td class="v">'+money(bill)+'</td></tr>'+
    '<tr><td class="k">Paid ('+esc(x.mode||'CASH')+')</td><td class="v">'+money(dep)+'</td></tr>'+
    '<tr><td class="k">Due</td><td class="v due">'+money(due)+'</td></tr>'+
    '<tr><td class="k">Date &amp; Time</td><td class="v">'+esc(fmtDateTime(x.createdAt||x.date||''))+'</td></tr>'+   /* 🔴 V437 #16 */
    '<tr><td class="k">Branch</td><td class="v">'+esc(x.branch||'')+'</td></tr>'+
    '<tr><td class="k">Received by</td><td class="v">'+esc(medStaffName(x.receivedBy||''))+'</td></tr>'+
    '</table><div style="text-align:center;margin-top:22px;color:#0B7A34;font-weight:700">Thank you. Get well soon.</div></body></html>';   /* 🔴 V437 #16 — ফোনের হুবহু শেষ বাক্য */
  try{var w=window.open('','_blank');if(!w){toast('Allow pop-ups to print');return;}w.document.write(html);w.document.close();w.focus();setTimeout(function(){try{w.print()}catch(e){}},300);}catch(e){toast('Print not available')}
}
/* TK-REQUESTED (2026-07-26): match the native app exactly . non-Master staff
   may still correct an entry made TODAY or YESTERDAY (native
   PaymentActivity.isTodayOrYesterday); anything older is Master only. The web
   allowed today only, so a genuine yesterday correction was blocked here
   while it worked on the phone. */
function wlv1TodayOrYesterday(d){const s=String(d||'');if(!s)return false;if(s===today())return true;
  const y=new Date();y.setDate(y.getDate()-1);
  const p=n=>String(n).padStart(2,'0');
  return s===(y.getFullYear()+'-'+p(y.getMonth()+1)+'-'+p(y.getDate()));}
window["wlv1TodayOrYesterday"]=wlv1TodayOrYesterday;
function canEditPaymentEntry(x){if(!user)return false;if(isMaster())return true;if(x.branch&&!sameBranch(x.branch,user?.branch))return false;if(wlv1TodayOrYesterday(x.date))return true;/* 🆕 (03.08.2026, TK-অনুমোদনে) — Grant থাকলে আজ/গতকালের বাইরেও Edit চলবে, ফোনের একই যুক্তি */return wlv1IsBackdateGranted(x.date);}
function paymentEditNeedsMaster(x){return !!user&&!isMaster()&&!wlv1TodayOrYesterday(x.date);}
window["paymentEditNeedsMaster"]=paymentEditNeedsMaster;
window["canEditPaymentEntry"]=canEditPaymentEntry;
function paymentAuditLine(oldAmt,newAmt){let by=user?.name||codeName(user?.mobile||'')||'User';return `Payment Amount ${money(oldAmt)} থেকে ${money(newAmt)} করেছেন ${by} | Date: ${new Date().toLocaleString('en-IN')}`}
window["paymentAuditLine"]=paymentAuditLine;
function numFmt(n){return Number(n||0).toLocaleString('en-IN')}
window.numFmt=numFmt;
function ordinalSuffix(n){n=Number(n);let s=['th','st','nd','rd'],v=n%100;return s[(v-20)%10]||s[v]||s[0]}
window.ordinalSuffix=ordinalSuffix;
function copyToClipboard(text){
 try{
  navigator.clipboard.writeText(text).then(()=>toast('Copied')).catch(()=>fallbackCopy(text));
 }catch(e){fallbackCopy(text)}
}
function fallbackCopy(text){
 try{
  let ta=document.createElement('textarea');
  ta.value=text;ta.style.position='fixed';ta.style.opacity='0';
  document.body.appendChild(ta);ta.select();document.execCommand('copy');document.body.removeChild(ta);
  toast('Copied');
 }catch(e){}
}
window.copyToClipboard=copyToClipboard;
function paymentHistory(id,type='all'){
 /* TK (27.07.2026): রোগীর সারি ফোনে/ব্রাউজারে না থাকলেও যেন আগের মতোই id ধরে টাকা মেলে — তাই খালি {} নয়, id বসানো থাকে। */
 let p=load('patients').find(x=>x.id===id)||{id:id};
 let rows=load('payments').filter(x=>payOwnedBy(x,p)&&(type==='all'?true:(type==='treatment'?isTreatmentPaymentRow(x):(x.payType||'treatment')===type)));
 rows=wlv1MergeDailyTreatmentRows(rows).slice().sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));
 let bill=Number(p.bill||0);
 // 🔒 V217 (§B216): totalPaid/runningPaid এখন wlv1PayEffect দিয়ে — approved
 // refund সত্যিই বিয়োগ হয়, pending/rejected কোনো প্রভাব ফেলে না (ফোনের
 // অ্যাপের একই paidEffect নিয়ম)।
 let totalPaid=rows.reduce((s,x)=>s+wlv1PayEffect(x),0);
 let runningPaid=0;
 /* 🖥️🔵 V549: ফোনের V533-এর হুবহু — চেম্বারের "আসবে বলেছে" /
    হাজিরার দাগ / বিল-সংশোধনের সারি (টাকা ০) এই তালিকায় দেখানো হয় না।
    TK: *"জিরো পেমেন্ট আবার কেন দেখাবে এখানে"*।
    ⛔ টাকার হিসাব উপরের `totalPaid` আগের সারিগুলো ধরেই হয় — এক পয়সাও বদলায় না
       (এগুলোর টাকা এমনিতেই ০)। শুধু দেখানো বন্ধ। */
 let shownRows=rows.filter(x=>!['chamber_expected','attendance_mark','bill_edit'].includes(String(x.payType||'').trim().toLowerCase()));
 let tableRows=shownRows.map((x,i)=>{
  runningPaid+=wlv1PayEffect(x);
  let due=Math.max(0,bill-runningPaid);
  /* 🔒 খাতার সারি B121 (TK পাশ): টাকার সারির শেষে 🗑️ — ফোনের মতোই।
     ⛔ আগের তিনটে ঘর ও তাদের ৩-বার-চাপার Edit এক অক্ষরও বদলায়নি,
        শুধু একটা ঘর **যোগ** হলো। */
  return `<tr><td>${esc(fmtDate(x.date||''))}</td><td class="phRemarks" onclick="hiddenPaymentEditTap('${esc(x.id)}')">${esc(x.remarks||paymentDisplayLabel(x,i))}</td><td class="phPaid" onclick="hiddenPaymentEditTap('${esc(x.id)}')">${esc(numFmt(x.amount))}</td><td class="phDue">${esc(numFmt(due))}</td><td style="text-align:center;cursor:pointer" title="Delete" onclick="wlv1DeletePayment('${esc(x.id)}');event.stopPropagation();">🗑️</td></tr>`;
 }).join('')||`<tr><td colspan="5" class="mut" style="text-align:center !important;">No payment yet</td></tr>`;
 let photo=p.photo?`<img class="summaryPhoto vaPhoto" src="${esc(p.photo)}">`:`<div class="summaryPhoto vaPhoto blank">👤</div>`;
 let fu=load('followups').find(f=>(f.refId===p.id||mob(f.mobile)===mob(p.mobile))&&(f.stage==='Treatment'||f.stage==='Patient'));
 let nextFollow=fu?.nextFollow?fmtDate(fu.nextFollow):'--';
 modal(`<div class="phWrap">
  <div class="tiny mut" style="text-align:center !important;margin-bottom:8px !important;">Edit করতে Paid বা Remarks-এ ৩ বার চাপুন</div>
  <div class="card phIdentity">
   ${photo}
   <div class="phIdentityBody">
     <div class="phName">${esc(String(p.name||'').toUpperCase())}</div>
     <div class="phIdRow"><span class="phIdBadge">Patient ID: ${esc(p.patientId||'-')}</span><button type="button" class="phCopyBtn" onclick="copyToClipboard('${esc(p.patientId||'')}')" title="Copy">📋</button></div>
     <div class="phField phNoBreak"><span class="phIco" style="background:#0c9e33 !important;">📞</span><b>Mobile</b><span>${esc(normMob(p.mobile||''))}</span></div>
     ${(p.altMobile&&mob(p.altMobile).length===10)?`<div class="phField phNoBreak"><span class="phIco" style="background:#0e7c7b !important;">📱</span><b>Alternate Mobile</b><span>${esc(normMob(p.altMobile))}</span></div>`:''}
     <div class="phField"><span class="phIco" style="background:#1067d8 !important;">👤</span><b>Age / Gender</b><span>${esc(p.age||'-')} / ${esc(String(p.sex||'-').toUpperCase())}</span></div>
     <div class="phField"><span class="phIco" style="background:#6941c6 !important;">💊</span><b>Disease</b><span>${esc(p.disease||'-')}</span></div>
     <div class="phField"><span class="phIco" style="background:#f79009 !important;">📍</span><b>Address</b><span>${esc(p.address||'-')}</span></div>
     <div class="phField"><span class="phIco" style="background:#d92d20 !important;">⏰</span><b>First Visit</b><span>${esc(fmtDate(p.registrationDate||p.visitDate||p.date||'-'))}</span></div>
   </div>
  </div>
  <div class="phSectionTitle">📋 Payment &amp; Movement History</div>
  <div class="phTableWrap"><table class="phTable">
   <thead><tr><th>Date</th><th>Progress / Remarks</th><th>Paid (₹)</th><th>Due (₹)</th></tr></thead>
   <tbody>${tableRows}</tbody>
  </table></div>
  <div class="phSummaryGrid">
   <div class="phSumCard phSumBill"><span>💼</span><small>Estimated Amount</small><b>₹ ${numFmt(bill)}</b></div>
   <div class="phSumCard phSumPaid"><span>🤝</span><small>Total Paid</small><b>₹ ${numFmt(totalPaid)}</b></div>
   <div class="phSumCard phSumDue"><span>📄</span><small>Total Due</small><b>₹ ${numFmt(Math.max(0,bill-totalPaid))}</b></div>
  </div>
  <div class="phNextFollow"><span>⏰</span> Next Follow-up Date <b>${esc(nextFollow)}</b></div>
  <button style="background:linear-gradient(135deg,#b23a2e,#d9534f);margin-top:10px" onclick="openRefundFormWeb('${esc(p.id)}')">💸 Refund</button>
  <div class="actions"><button class="ghost" onclick="closeModal()">Close</button></div>
 </div>`)
}
window["paymentHistory"]=paymentHistory;
function viewPaymentEntry(id){let x=load('payments').find(p=>p.id===id);if(!x)return toast('Payment not found');modal(`<h2>Payment Details</h2><div class="card"><b>${esc(x.name||'')}</b><br>${esc(x.mobile||'')} · ${esc(x.branch||'')}<br>Date: ${esc(fmtDate(x.date||''))}<br>Amount: <b>${money(x.amount)}</b><br>Mode: ${esc(x.mode||'')}<br><small>${esc(x.remarks||'')}</small>${Array.isArray(x.editHistory)&&x.editHistory.length?`<div class="sectionTitle">Edit Log</div>${x.editHistory.map(h=>`<div class="tiny">${esc(h)}</div>`).join('')}`:''}</div>`)}
