window["pullBackupRecordsFromCloud"]=pullBackupRecordsFromCloud;
/* একটা ব্যাকআপের ভিতরের তথ্য — এই যন্ত্রে থাকলে সেটাই, নইলে ক্লাউড থেকে ওই
   একটামাত্র সারি। ⛔ না পেলে সৎভাবে খালি ফেরে, আন্দাজে কিছু বানায় না। */
async function wlv1BackupPayload(id){
  try{
    let local=backupRows().find(x=>x.id===id);
    if(local&&local.payload) return String(local.payload);
    let ok=await initCloudClientOnly(); if(!ok||!sb) return '';
    let r=await sb.from('backuprecords').select('payload').eq('id',id).limit(1);
    if(r&&r.error) return '';
    let p=(r&&Array.isArray(r.data)&&r.data[0])?r.data[0].payload:'';
    if(p&&typeof p!=='string'){ try{ p=JSON.stringify(p); }catch(e){ p=''; } }
    return String(p||'');
  }catch(e){ return ''; }
}
window["wlv1BackupPayload"]=wlv1BackupPayload;
async function syncPasswordRowsToCloud(){try{for(const r of userPasswordRows()){await cloudUpsertExtra('usercredentials',r)}}catch(e){}}
window["syncPasswordRowsToCloud"]=syncPasswordRowsToCloud;
function passwordCenter(){if(!isMaster())return page('Password Center','<div class="card redP">Only Master Admin</div>');let users=allUsers();let rows=userPasswordRows();let html=users.map(u=>{let mm=mob(u.mobile),r=rows.find(x=>mob(x.mobile)===mm),pw=r?.password||defaultPasswordFor(u.role,mm);return `<div class="card"><b>${esc(u.name||mm)}</b><br><small>${esc(u.role)} · ${esc(u.branch||'')} · ${esc(normMob(mm))}</small><label>Password</label><input id="pw_${mm}" class="input" data-nocaps="1" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" value="${esc(pw)}"><div class="actions"><button onclick="saveUserPassword('${mm}','${esc(u.role)}')">Save Password</button></div></div>`}).join('');page('Password Center',`<div class="card"><b>User Password Control</b><br><small>Master Admin can view/change every user password. Default password format is role prefix + last 4 digits until changed.</small></div>${html}`,true)}
window["passwordCenter"]=passwordCenter;
function saveUserPassword(mm,role){let el=$('#pw_'+mob(mm)),pw=String(el?.value||'').trim();if(!pw)return toast('Password required');let users=allUsers(),u=users.find(x=>mob(x.mobile)===mob(mm))||{};let rows=userPasswordRows().filter(x=>mob(x.mobile)!==mob(mm));let row={id:'cred_'+mob(mm),mobile:mob(mm),role:role||u.role||'',name:u.name||'',branch:u.branch||'',password:pw,changedBy:user?.mobile||'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};rows.unshift(row);saveUserPasswordRows(rows);cloudUpsertExtra('usercredentials',row);toast('Password saved');passwordCenter()}
window["saveUserPassword"]=saveUserPassword;

function backupRows(){try{return JSON.parse(localStorage.getItem('rk_backup_history')||'[]')}catch(e){return []}}
window["backupRows"]=backupRows;
function saveBackupRows(rows){
 try{
  let text=JSON.stringify((rows||[]).slice(0,30));
  localStorage.setItem('rk_backup_history',text);
  // V452 WORKING FIX (19.08.2026, TK-approved): a browser can reject
  // localStorage writes when its quota is full. Do not report success unless
  // the exact value can be read back from storage. No cloud call is added.
  return localStorage.getItem('rk_backup_history')===text;
 }catch(e){ return false; }
}
window["saveBackupRows"]=saveBackupRows;
function buildBackupPayload(reason='manual'){
 let data={};TABLES.forEach(t=>data[t]=load(t));
 return {meta:{app:'PILES CLINIC ERP',version:V,reason,date:today(),createdAt:new Date().toISOString(),createdBy:user?.mobile||'',tables:TABLES},data};
}
window["buildBackupPayload"]=buildBackupPayload;
function verifyBackupPayload(p){try{return !!(p&&p.meta&&p.data&&TABLES.every(t=>Array.isArray(p.data[t])))}catch(e){return false}}
window["verifyBackupPayload"]=verifyBackupPayload;
function recordBackup(reason='manual'){
 let payload=buildBackupPayload(reason),valid=verifyBackupPayload(payload),text=JSON.stringify(payload),rows=backupRows();
 // First write as Pending. "Verified" is allowed only after the exact payload
 // is persisted locally and successfully read/parsed back. This prevents a full
 // localStorage quota from falsely showing "Backup Verified". Existing backup
 // rows are never deleted or trimmed on failure.
 let row={id:uid('bak'),reason,date:today(),at:new Date().toISOString(),by:user?.mobile||'',status:'Pending',size:text.length,payload:text,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
 rows.unshift(row);
 let stored=false;
 if(valid && saveBackupRows(rows)){
  try{
   let chk=backupRows().find(x=>x&&x.id===row.id);
   let parsed=chk&&chk.payload?JSON.parse(String(chk.payload)):null;
   stored=!!(chk && String(chk.payload||'')===text && verifyBackupPayload(parsed));
  }catch(e){ stored=false; }
 }
 row.status=stored?'Verified':'Failed';
 if(stored){
  // Persist the final Verified label too. If even this tiny second write fails,
  // do not lie: the in-memory result becomes Failed and cloud metadata says Failed.
  rows[0]=row;
  if(!saveBackupRows(rows)) row.status='Failed';
 }
 try{cloudUpsertExtra('backuprecords',{...row,createdAt:row.createdAt,updatedAt:row.updatedAt})}catch(e){}
 return row;
}
window["recordBackup"]=recordBackup;
let AUTO_BACKUP_TIMER=null;
function scheduleAutoBackup(reason='auto'){
 try{
  clearTimeout(AUTO_BACKUP_TIMER);
  AUTO_BACKUP_TIMER=setTimeout(()=>{
   try{
    let key='rk_last_auto_backup_'+today();
    let last=localStorage.getItem(key)||'';
    if(!last||Date.now()-Number(last)>30*60*1000){recordBackup(reason);localStorage.setItem(key,String(Date.now()))}
   }catch(e){}
  },1400);
 }catch(e){}
}
window["scheduleAutoBackup"]=scheduleAutoBackup;
function backup(){
 try{pullBackupRecordsFromCloud().then(()=>{})}catch(e){}
 if(!isMaster())return page('Backup Center','<div class="card redP">Only Master Admin</div>');
 let rows=backupRows(),last=rows[0];
 let list=rows.slice(0,12).map(b=>`<div class="card"><b>${esc(b.reason||'Backup')}</b><br><small>${esc(fmtDateTime(b.at))} · ${esc(b.status)} · ${(Number(b.size||0)/1024).toFixed(1)} KB</small><div class="actions"><button onclick="downloadBackupId('${b.id}')">Download</button><button class="ghost" onclick="restoreBackupId('${b.id}')">Restore</button></div></div>`).join('')||'<div class="card mut">No backup history yet</div>';
 page('Backup Center',`<div class="card"><b>Status:</b> ${esc(last?.status||'Not started')}<br><b>Last Backup:</b> ${esc(last?fmtDateTime(last.at):'Never')}<br><small>Auto backup runs after important saves. Restore points are kept <b>on this device</b>. <b>Press "Download Full Backup" and keep the file safe (WhatsApp / Google Drive)</b> — that downloaded file is the only backup that survives if this device is lost.</small><br><small><b>Sync:</b> ${esc(syncStatusLabel())}</small><div class="actions"><button onclick="manualBackupNow()">Create Backup Now</button><button class="ghost" onclick="downloadBackup()">Download Full Backup</button></div></div><div class="card"><label>Restore JSON</label><input type="file" class="input" onchange="restoreBackup(this)"><small class="mut">Restore requires confirmation.</small></div><div class="sectionTitle">Backup History</div>${list}`)
}
window["backup"]=backup;
function manualBackupNow(){let b=recordBackup('manual');toast(b.status==='Verified'?'Backup Verified':'Backup Failed');backup()}
window["manualBackupNow"]=manualBackupNow;function downloadBackup(){let payload=buildBackupPayload('download');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload)],{type:'application/json'}));a.download='Backup_'+fmtDate(today()).replace(/\//g,'-')+'_PILES_CLINIC.json';a.click();toast('Backup downloaded')}
window.downloadBackup=downloadBackup;
/* 🔵 V418: ভিতরের তথ্য এখন চাপ দিলে তবেই নামে (উপরের নোট দেখুন)। */
async function downloadBackupId(id){let b=backupRows().find(x=>x.id===id);if(!b)return toast('Backup not found');let pay=await wlv1BackupPayload(id);if(!pay)return toast('Backup file not available — check internet');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([pay],{type:'application/json'}));a.download='piles_clinic_restore_point_'+(b.date||today())+'.json';a.click()}
window["downloadBackupId"]=downloadBackupId;
function applyBackupPayload(p){if(!verifyBackupPayload(p))throw new Error('Invalid backup');TABLES.forEach(t=>save(t,p.data[t],{skipCloud:true,skipBackup:true}));markAllTablesPendingCloud();recordBackup('before_restore');return true}
window["applyBackupPayload"]=applyBackupPayload;
function markAllTablesPendingCloud(){try{localStorage.setItem('rk_pending_cloud',JSON.stringify(TABLES))}catch(e){}}
window["markAllTablesPendingCloud"]=markAllTablesPendingCloud;
/* 🔵 V418: ভিতরের তথ্য আগে নামিয়ে নেওয়া হয়, **তারপর** জিজ্ঞাসা — তথ্য না পেলে
   পুরনো তথ্য মোছার কোনো সুযোগই থাকে না। ⛔ Restore-এর নিয়ম আগের মতোই। */
async function restoreBackupId(id){let b=backupRows().find(x=>x.id===id);if(!b)return toast('Backup not found');let pay=await wlv1BackupPayload(id);if(!pay)return toast('Backup file not available — check internet');if(!confirm('Restore selected backup? Current data will be replaced.'))return;try{applyBackupPayload(JSON.parse(pay));toast('Backup restored. Cloud sync pending.');dashboard()}catch(e){toast('Restore failed')}}
window["restoreBackupId"]=restoreBackupId;
function restoreBackup(inp){let f=inp.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let p=JSON.parse(r.result);if(!confirm('Restore uploaded backup? Current data will be replaced.'))return;applyBackupPayload(p);toast('Backup restored. Cloud sync pending.');dashboard()}catch(e){toast('Invalid backup')}};r.readAsText(f)}
window["restoreBackup"]=restoreBackup;
let wlv1TrashBranch='';   /* 🟢🔒 V398: মনে-রাখা মানের প্রতিচ্ছবি (wlv1BranchGet) */
let __wlv1TrashCloudVerifiedAt=0;
let __wlv1TrashRefreshPromise=null;

/* ══════════════════════════════════════════════════════════════════════════
   🔴🔴🔒 V511 (২১.০৮.২০২৬, TK-অনুমোদিত প্রুফ) — Trash Bin-এর নতুন ছোট কার্ড,
   👁 View, খোঁজা, আর একসাথে অনেকগুলো Restore/Delete।
   ⛔ ফোনের `TrashCardText.kt` + `TrashAdapter.kt`-এর হুবহু একই নিয়ম, যাতে
      দুই দিকে চেহারা ও তথ্য কখনো আলাদা না হয়।
   ⛔ কোনো নতুন ক্লাউড-অনুরোধ নেই — খোঁজা/বাছা সবই ব্রাউজারের ভিতরে।
   ⛔ Restore ও Delete Forever আসলে কী করে, সেই নিয়ম এক অক্ষরও বদলায়নি —
      একসাথে কয়েকটা করলে সেই **একই** ফাংশনগুলোই একটার পর একটা চলে।
   ══════════════════════════════════════════════════════════════════════════ */
var __wlv1TrashRows = [];
var __wlv1TrashQuery = '';
var __wlv1TrashSel = {};          /* id → true (বাছা সারি) */
var __wlv1TrashSelMode = false;

function wlv1TrashSrcLabel(t){
  var k=String(t||'').trim().toLowerCase();
  if(k==='followups')return 'FOLLOW-UP';
  if(k==='payments')return 'PAYMENT';
  if(k==='enquiries')return 'ENQUIRY';
  if(k==='patients')return 'PATIENT';
  if(k==='doctor_visits')return 'DR. VISIT';
  if(k==='medical')return 'MEDICINE';
  return (String(t||'RECORD')).toUpperCase();
}
function wlv1TrashWhen(x){
  try{
    var v=String((x&&x.deletedAt)||''); if(!v)return '';
    /* ⛔ deletedAt ফোনের নিজের ঘড়িতে লেখা (শেষে শুধু 'Z'), তাই UTC ধরে পড়লে
       সময় এগিয়ে যেত — 'Z' ফেলে দিয়ে স্থানীয় সময় হিসেবেই পড়া হয়। */
    var d=new Date(v.replace(/Z$/,''));
    if(isNaN(d))return '';
    var dd=String(d.getDate()).padStart(2,'0'), mm=String(d.getMonth()+1).padStart(2,'0');
    var h=d.getHours(), ap=h>=12?'PM':'AM'; h=h%12; if(h===0)h=12;
    return dd+'.'+mm+'.'+d.getFullYear()+' '+h+':'+String(d.getMinutes()).padStart(2,'0')+' '+ap;
  }catch(e){ return ''; }
}
function wlv1TrashDeletedBy(x){
  var v=String((x&&x.deletedBy)||''); if(!v)return '';
  try{ return codeName(v)||v; }catch(e){ return v; }
}
/* 🟢🔒🔒 V660 (২৫.০৮.২০২৬, TK-নির্দেশ, ছবি-প্রুফ পাশ) — "কবে মুছেছে" আর
   "কে মুছেছে" এখন একই লাইনে (Android-এর whenAndBy()-এর হুবহু একই যমজ)। */
function wlv1TrashWhenAndBy(x){
  var w=wlv1TrashWhen(x), by=wlv1TrashDeletedBy(x);
  if(w && by) return '🗑 '+w+' · Deleted by '+by;
  if(w) return '🗑 '+w;
  if(by) return '🗑 Deleted by '+by;
  return '';
}
function wlv1TrashExtraChip(x){
  var r=(x&&x.record)||{};
  var amt=String(r.amount||'').trim();
  if(amt && amt!=='0'){ var n=amt.replace(/[^0-9.]/g,''); if(n) return '₹'+n.replace(/\.$/,''); }
  var dis=String(r.disease||'').trim();
  return dis?dis.toUpperCase():'';
}
/* 🟢🔒 V660 (২৫.০৮.২০২৬, TK-নির্দেশ, ছবি-প্রুফ পাশ) — আইডি না থাকলে
   (Enquiry) এখন এই একই লাইনেই রেকর্ডের নিজের তারিখ বসে (dot-ফরম্যাটে) —
   Android-এর line1()-এর হুবহু একই বদল। */
function wlv1TrashLine1(x){
  var r=(x&&x.record)||{}, p=[];
  if(String(r.mobile||'').trim()) p.push('📞 '+String(r.mobile).trim());
  /* 🔴🔒 V773 (২৮.০৮.২০২৬) — TK: *"Patient ID ভুল কেন?"*
     ফোনে V762-এ এটা ঠিক করা হয়েছিল, **কম্পিউটারে করা হয়নি** — যাচাই করতে
     গিয়ে ধরা পড়ল। টেবিল-ভেদে ঘর দুটোর মানে উল্টো:
       · `patients` সারিতে → `patientId` = আসল আইডি (COB-28072026-003)
       · `payments` সারিতে → `patientId` = **ভিতরের সারি-আইডি** (`pat_7f62…`),
         আর আসল আইডি থাকে `patientCode`-এ।
     ⇒ তাই আগে সবসময় `patientId` দেখানোয় পেমেন্টের কার্ডে যন্ত্রের আইডি উঠত।
     এখন **যেটা মানুষের আইডির মতো দেখতে সেটাই** বাছা হয় — ভিতরের আইডিতে
     সবসময় `_` থাকে (pat_ · enq_ · rfnd_), আসল আইডিতে কখনো থাকে না।
     ⛔ কোনো তথ্য বদলানো হয়নি — শুধু কোনটা দেখানো হবে সেটা। (Android:
        TrashCardText.line1()-এর হুবহু একই নিয়ম।) */
  var __human=function(v){ v=String(v||'').trim(); return (v && v.indexOf('_')<0) ? v : ''; };
  var pid=__human(r.patientCode) || __human(r.patientId);
  if(pid) p.push(pid);
  else { var d0=String(r.date||'').trim(); if(d0) p.push(fmtDate(d0)); }
  return p.join('  ·  ');
}
/* 🟢🔒 V660 — সব তারিখ এখন dot-ফরম্যাটে (আগে raw ISO দেখাত, Android-এর
   line2()-এর হুবহু একই বদল)। Enquiry-র তারিখ এখন line1-এই বসে (উপরে)। */
function wlv1TrashLine2(x){
  var r=(x&&x.record)||{}, t=String((x&&x.table)||'').toLowerCase(), p=[];
  function ad(v){ v=String(v||'').trim(); if(v)p.push(v); }
  function adD(v){ v=String(v||'').trim(); if(v)p.push(fmtDate(v)); }
  if(t==='payments'){ ad(r.payType); adD(r.date); ad(r.mode);
    if(String(r.receivedBy||'').trim()) p.push('by '+String(r.receivedBy).trim()); }
  else if(t==='followups'){ ad(r.stage); ad(r.status);
    if(String(r.nextFollow||'').trim()) p.push('Next call '+fmtDate(r.nextFollow)); }
  else if(t==='patients'){ adD(r.registrationDate);
    if(String(r.bill||'').trim() && String(r.bill).trim()!=='0') p.push('Bill ₹'+String(r.bill).trim());
    ad(r.stage); }
  else if(t==='enquiries'){ ad(r.refBy); }
  else { adD(r.date); ad(r.stage); }
  return p.join('  ·  ');
}
function wlv1TrashHay(x){
  var r=(x&&x.record)||{};
  return [x&&x.id, x&&x.table, r.name, r.mobile, r.altMobile, r.patientId, r.patientCode, r.branch]
    .map(function(v){return String(v||'')}).join(' ').toLowerCase();
}
function wlv1TrashCardHtml(x){
  var r=(x&&x.record)||{}, id=String((x&&x.id)||'');
  var nm=esc(String(r.name||r.mobile||id));
  var br=String(r.branch||'').trim();
  var ex=wlv1TrashExtraChip(x), l1=wlv1TrashLine1(x), l2=wlv1TrashLine2(x);
  // 🟢🔒 V660 — when+by এখন একই লাইনে (উপরের wlv1TrashWhenAndBy), তাই
  // "wh"/"by" আলাদা করে পড়ার/দেখানোর দরকার নেই।
  var whenBy = wlv1TrashWhenAndBy(x);
  var tick = __wlv1TrashSelMode
    ? `<input type="checkbox" class="wlv1TrashCb" ${__wlv1TrashSel[id]?'checked':''}
         onclick="wlv1TrashTogglePick('${esc(id)}')">` : '';
  var acts = __wlv1TrashSelMode ? '' : `
    <div class="wlv1TrashBtns">
      <button class="wlv1TrashB v" onclick="wlv1TrashView('${esc(id)}')">👁 View</button>
      <button class="wlv1TrashB r" onclick="restoreTrash('${esc(id)}')">♻ Restore</button>
      <button class="wlv1TrashB d" onclick="wlv1TrashDeleteForever('${esc(id)}')">🗑 Delete</button>
    </div>`;
  return `<div class="card wlv1TrashCard${__wlv1TrashSel[id]?' pick':''}">
    <div class="wlv1TrashTop">${tick}<b class="wlv1TrashName">${nm}</b></div>
    <div class="wlv1TrashChips">
      <span class="wlv1TrashChip">${esc(wlv1TrashSrcLabel(x&&x.table))}</span>
      ${br?`<span class="wlv1TrashChip g">${esc(br.toUpperCase())}</span>`:''}
      ${ex?`<span class="wlv1TrashChip rd">${esc(ex)}</span>`:''}
    </div>
    ${l1?`<div class="wlv1TrashDet">${esc(l1)}</div>`:''}
    ${l2?`<div class="wlv1TrashDet">${esc(l2)}</div>`:''}
    ${whenBy?`<div class="wlv1TrashWhen">${esc(whenBy)}</div>`:''}
    ${acts}
  </div>`;
}
function wlv1TrashToolsHtml(){
  return `<div class="wlv1TrashTools">
    <input id="wlv1TrashSearch" class="wlv1TrashSearch" placeholder="🔍 Search name or mobile">
    <button class="wlv1TrashSel${__wlv1TrashSelMode?' on':''}" onclick="wlv1TrashToggleSelectMode()">${__wlv1TrashSelMode?'✕ Cancel':'☑ Select'}</button>
  </div>`;
}
function wlv1TrashBulkBarHtml(){
  if(!__wlv1TrashSelMode)return '';
  var n=Object.keys(__wlv1TrashSel).filter(function(k){return __wlv1TrashSel[k]}).length;
  if(!n)return '';
  return `<div class="wlv1TrashBulk">
    <span class="wlv1TrashCnt">${n} selected</span>
    <button class="wlv1TrashB r" onclick="wlv1TrashBulk(true)">♻ Restore (${n})</button>
    <button class="wlv1TrashB d" onclick="wlv1TrashBulk(false)">🗑 Delete (${n})</button>
  </div>`;
}
function wlv1TrashToggleSelectMode(){
  __wlv1TrashSelMode=!__wlv1TrashSelMode;
  if(!__wlv1TrashSelMode)__wlv1TrashSel={};
  wlv1RenderTrashBin();
}
window["wlv1TrashToggleSelectMode"]=wlv1TrashToggleSelectMode;
function wlv1TrashTogglePick(id){
  if(__wlv1TrashSel[id])delete __wlv1TrashSel[id]; else __wlv1TrashSel[id]=true;
  wlv1RenderTrashBin();
}
window["wlv1TrashTogglePick"]=wlv1TrashTogglePick;

/* 👁 View — TK: *"সেখানে চাপ দিলে অন্তত আমি একবার দেখে নিতে পারি যে এনাকে
   আমি রিস্টোর করবো না ডিলিট ফরএভার করব।"* ⛔ ক্লাউডে কিছু যায় না। */
function wlv1TrashViewFields(x){
  var r=(x&&x.record)||{}, t=String((x&&x.table)||'').toLowerCase(), out=[];
  function ad(label,key){ var v=String(r[key]||'').trim(); if(v)out.push([label,v]); }
  // 🟢🔒 V660 (২৫.০৮.২০২৬) — তারিখ-ঘরের জন্য, dot-ফরম্যাটে বসায় (Android-এর
  // addDate()-এর হুবহু একই যমজ)।
  function adD(label,key){ var v=String(r[key]||'').trim(); if(v)out.push([label,fmtDate(v)]); }
  out.push(['From', wlv1TrashSrcLabel(x&&x.table)]);
  ad('Name','name'); ad('Mobile','mobile'); ad('Alt. mobile','altMobile');
  ad('Patient ID','patientId'); ad('Patient code','patientCode'); ad('Branch','branch');
  if(t==='payments'){ ad('Pay type','payType'); ad('Amount','amount'); ad('Mode','mode');
    adD('Date','date'); ad('Received by','receivedBy'); ad('Remarks','remarks'); }
  else if(t==='followups'){ ad('Stage','stage'); ad('Status','status'); ad('Disease','disease');
    ad('Address','address'); ad('Last remark','lastRemark'); adD('Next call','nextFollow');
    ad('Call count','callCount'); adD('Record date','date'); }
  else if(t==='patients'){ ad('Age','age'); ad('Sex','sex'); ad('Address','address');
    ad('Disease','disease'); ad('Diagnosis','diagnosis'); ad('Stage','stage'); ad('Bill','bill');
    ad('Discount','discount'); ad('Referred by','refBy'); adD('Registration date','registrationDate'); }
  else if(t==='enquiries'){ ad('Disease','disease'); ad('Address','address'); ad('Referred by','refBy');
    adD('Date','date'); ad('Remarks','remarks'); }
  else { ad('Stage','stage'); ad('Status','status'); adD('Date','date'); ad('Remarks','remarks'); }
  ad('Created by','createdBy');
  var by=wlv1TrashDeletedBy(x); if(by)out.push(['Deleted by',by]);
  var wh=wlv1TrashWhen(x); if(wh)out.push(['Deleted at',wh]);
  if(String(r.id||'').trim())out.push(['Record ID',String(r.id).trim()]);
  return out;
}
/* 🟢🔒 V590 (২৩.০৮.২০২৬, TK-নির্দেশ, ছবিসহ: *"View-তে চাপার পর আগে যেখানে ছিল
   সেখানকার মতনই চেহারা দেখতে হতে হবে"*) — মুছে ফেলা সারিটা যে পর্দায় ছিল,
   সেখানকার **আসল কার্ডটাই** বানানো হয়।
   ⛔ কার্ড নতুন করে আঁকা হয়নি — ওই পর্দার নিজের ফাংশনকেই ডাকা হয়
      (`wlv1PayCardHtml` · `fuCard`), তাই চেহারা "মতন" নয়, **হুবহু এক**।
   ⛔ Trash সারির ভিতরে **আসল সারির হুবহু JSON** জমা থাকে, তাই ওই ফাংশনগুলো
      সেটাকে ঠিক সেভাবেই পড়তে পারে (কোড দেখে মিলিয়ে নেওয়া, আন্দাজ নয়)।
   ⛔ কার্ডের ভিতরের সব চাপ **নিষ্ক্রিয়** করা হয় (`pointer-events:none`) — Trash
      থেকে ভুল করে কল · WhatsApp · টাকা — কিছুই হতে পারে না।
   ⛔ চেনা না গেলে (patients ইত্যাদি) আগের সেই লেখার তালিকাই দেখায়। */
function wlv1TrashSourceCardHtml(x){
  try{
    var t=String(x.table||'').trim().toLowerCase();
    var r=x.record||{};
    var inner='';
    if(t==='payments' && typeof wlv1PayCardHtml==='function'){
      inner=wlv1PayCardHtml({...r, pidCode:(r.patientCode||r.pidCode||'')});
    }else if((t==='followups'||t==='enquiries') && typeof fuCard==='function'){
      inner=fuCard({...r, stage:String(r.stage||(t==='enquiries'?'Inquiry':'')), id:String(r.id||'')});
    }
    if(!inner) return '';
    return '<div class="wlv1TrashSrcLbl">As it was in '+esc(wlv1TrashSrcLabel(x.table))+'</div>'
         + '<div class="wlv1TrashSrc">'+inner+'</div>';
  }catch(e){ return '' }
}
window["wlv1TrashSourceCardHtml"]=wlv1TrashSourceCardHtml;

function wlv1TrashView(id){
  var x=(__wlv1TrashRows||[]).find(function(a){return String(a.id)===String(id)});
  if(!x)return;
  var card=wlv1TrashSourceCardHtml(x);
  var rows = card ? '' : wlv1TrashViewFields(x).map(function(kv){
    return `<div class="wlv1TrashVRow"><span class="k">${esc(kv[0])}</span><span class="v">${esc(kv[1])}</span></div>`;
  }).join('');
  /* 🗑 কে মুছেছেন ও কখন — Trash-এর নিজের তথ্য, কার্ডে থাকে না */
  var who=(typeof wlv1TrashDeletedBy==='function')?wlv1TrashDeletedBy(x):String(x.deletedBy||'');
  var whenT=(typeof wlv1TrashWhen==='function')?String(wlv1TrashWhen(x)||'').replace(/\n/g,'  '):'';
  var strip=[who,whenT].filter(Boolean).join('  ·  ');
  var del = isMaster()
    ? `<button class="red" onclick="closeModal();wlv1TrashDeleteForever('${esc(String(id))}')">🗑 Delete Forever</button>` : '';
  modal(`<h2>👁 ${esc(String((x.record&&x.record.name)||x.id))}</h2>
    ${card || `<div class="card">${rows}</div>`}
    ${strip?`<div class="wlv1TrashDelStrip">🗑 Deleted by ${esc(strip)}</div>`:''}
    <div class="actions">
      <button onclick="closeModal();restoreTrash('${esc(String(id))}')">♻ Restore</button>
      ${del}<button class="ghost" onclick="closeModal()">Close</button>
    </div>`);
}
window["wlv1TrashView"]=wlv1TrashView;

/* একসাথে অনেকগুলো — একটার পর একটা, **হুবহু সেই একই** Restore/Delete।
   ⛔ একটা ব্যর্থ হলে বাকিগুলো থামে না; শেষে কতগুলো হলো, কতগুলো হলো না
      সেটা পরিষ্কার করে বলা হয় (TK: *"সফল বলে দাবি করবেন না"*)। */
async function wlv1TrashBulk(restore){
  var ids=Object.keys(__wlv1TrashSel).filter(function(k){return __wlv1TrashSel[k]});
  if(!ids.length)return;
  var word = restore ? 'Restore' : 'Delete forever';
  if(!confirm(word+' '+ids.length+' record(s)?'+(restore?'':' This cannot be undone.')))return;
  var ok=0, fail=0;
  for(const id of ids){
    try{
      var done = restore ? await wlv1RestoreTrash(id, true)
                         : await wlv1TrashDeleteForeverSafe(id, true);
      if(done) ok++; else fail++;
    }catch(e){ fail++; }
  }
  __wlv1TrashSel={}; __wlv1TrashSelMode=false;
  toast((restore?'Restored ':'Deleted ')+ok+(fail?(' · '+fail+' failed'):''));
  trashBin(true);
}
window["wlv1TrashBulk"]=wlv1TrashBulk;

function wlv1RenderTrashBin(){
 if(!isMaster())return page('Trash Bin','<div class="card redP">Only Master Admin</div>');
 let tr=load('trash');
 wlv1TrashBranch=wlv1BranchGet();
 let branchWrap=`<div id="trashBranchWrap" class="wlv1HdrPick">${wlv1BranchSelectHtml('trashBin(true)')}</div>`;
 let __trAsk=false, __g=wlv1BranchGate(tr,{pick:x=>(x&&x.record&&x.record.branch)||''});
 if(__g===null){ __trAsk=true; tr=[]; } else { tr=__g; }
 /* 🔴🔴🔒 V511 (২১.০৮.২০২৬, TK-অনুমোদিত প্রুফ) — ফোনের হুবহু একই ছোট কার্ড।
    TK-এর কথা: *"এই কার্ডেই পেশেন্ট এর সম্পূর্ণ ডিটেলস ছোট আকারে দেখানো থাকবে...
    restore and delete forever এগুলি পাশাপাশি থাকবে... কার্ডগুলি যত ছোট রাখা যায়...
    অনেকগুলো একসাথে সিলেক্ট করা যাবে... ভিউ একটা অপশন থাকার দরকার ছিল।"*
    ⛔ নেভি ব্লু কোথাও নেই — View নীল · Restore সবুজ · Delete লাল।
    ⛔ সব লেখা ইংরেজি (TK: *"বাংলা থাকবে না"*)।
    ⛔ খোঁজা ও বাছা সম্পূর্ণ ব্রাউজারের ভিতরে — একটাও নতুন ক্লাউড-অনুরোধ নেই। */
 __wlv1TrashRows = tr;
 let q = String(__wlv1TrashQuery||'').trim().toLowerCase();
 let shown = q ? tr.filter(x=>wlv1TrashHay(x).indexOf(q)>=0) : tr;
 let body = shown.map(x=>wlv1TrashCardHtml(x)).join('')
   || (__trAsk ? wlv1BranchAskCard()
              : `<div class="card mut">${q?'No match':'Trash empty'}</div>`);
 page('Trash Bin', `${branchWrap}${wlv1TrashToolsHtml()}${body}${wlv1TrashBulkBarHtml()}`, true);
 setTimeout(function(){
   try{
     var box=document.getElementById('wlv1TrashSearch');
     if(box){ box.value=__wlv1TrashQuery||'';
       box.oninput=function(){ __wlv1TrashQuery=box.value; wlv1RenderTrashBin();
         try{ var b2=document.getElementById('wlv1TrashSearch'); if(b2){ b2.focus();
           b2.setSelectionRange(b2.value.length,b2.value.length); } }catch(e){} };
     }
   }catch(e){}
 },0);
 setTimeout(function(){
   try{
     if(window.innerWidth>=900){
       var slot=document.getElementById('wlv1TrashTopSlot');
       var bw=document.getElementById('trashBranchWrap');
       if(slot&&bw)slot.appendChild(bw);
     }
   }catch(e){}
 },0);
}
window["wlv1RenderTrashBin"]=wlv1RenderTrashBin;
async function wlv1RefreshTrashFromCloud(force=true){
 try{
  if(!isMaster())return false;
  /* Branch selector re-render / successful action should not re-download the whole
     Trash immediately. A real screen-open passes force=true. */
  if(!force && __wlv1TrashCloudVerifiedAt && (Date.now()-__wlv1TrashCloudVerifiedAt)<60*1000) return true;
  if(__wlv1TrashRefreshPromise) return await __wlv1TrashRefreshPromise;
  __wlv1TrashRefreshPromise=(async()=>{
    let ok=await initCloudClientOnly(); if(!ok||!sb)return false;
    let r=await wlv1FetchPaged('trash','*','',true);
    if(r&&r.error)return false;
    let rows=normalizeCloudRows((r&&Array.isArray(r.rows))?r.rows:[]);
    /* Cloud-authoritative only after a complete successful fetch. If the read fails,
       existing local Trash is untouched and destructive actions stay blocked. */
    save('trash',rows,{skipCloud:true,skipBackup:true});
    __wlv1TrashCloudVerifiedAt=Date.now();
    return true;
  })();
  try{return await __wlv1TrashRefreshPromise}finally{__wlv1TrashRefreshPromise=null}
 }catch(e){__wlv1TrashRefreshPromise=null;return false}
}
window["wlv1RefreshTrashFromCloud"]=wlv1RefreshTrashFromCloud;
async function trashBin(skipCloudRefresh=false){
 if(!isMaster())return page('Trash Bin','<div class="card redP">Only Master Admin</div>');
 if(skipCloudRefresh===true){ wlv1RenderTrashBin(); return; }
 page('Trash Bin','<div class="card mut">Checking current Trash from cloud…</div>',true);
 let ok=await wlv1RefreshTrashFromCloud(true);
 if(!ok){
   __wlv1TrashCloudVerifiedAt=0;
   return page('Trash Bin','<div class="card redP">Cloud could not be verified. Nothing can be Restore/Delete until internet/cloud is available.</div>',true);
 }
 wlv1RenderTrashBin();
}
window["trashBin"]=trashBin;function restoreTrash(id){let tr=load('trash'),x=tr.find(a=>a.id===id);if(x){add(x.table,x.record);save('trash',tr.filter(a=>a.id!==id));trashBin()}}
window["restoreTrash"]=restoreTrash;
/* 🖥️🔵 B668 (১৫.০৮.২০২৬, TK-অনুমোদিত): এই পর্দাটা কোডে লেখা ছিল কিন্তু **কোনো
   বোতাম থেকে খোলাই যেত না** (গোটা প্রজেক্টে `settings()`-এর মাত্র ২টা উল্লেখ —
   দুটোই সংজ্ঞা)। এখন ☰ মেনুতে ঘর বসেছে (master-only, ফোনের মতোই)।
   ভিতরে **শুধু সত্যি তথ্য** দেখানো হয় — কোনো নতুন সুইচ/নিয়ম বসানো হয়নি:
     · নিষ্ক্রিয়তায় লগ-আউট ১৫ মিনিট — কোডের আসল মান (app.js-এর শেষে `IDLE_MS`)
     · ক্লাউড সিঙ্ক কখন হয় — লগইনে · রাত ২টায় · হাতে "Sync Now"
   ⛔ ফোনের Settings-এ যে দুটো জিনিস আছে সেগুলো ব্রাউজারে সম্ভব নয় বলে রাখা
      হয়নি: auto-sync সুইচ ও crash log (দুটোই ফোনের নিজস্ব ব্যবস্থা)।
   ⛔ কোনো ক্লাউড-কল নেই — Free plan-এ এক পয়সাও খরচ হয় না। */
function settings(){page('App Settings',
  `<div class="card"><b>Clinic:</b> ${esc(C.clinicName)}<br><b>User:</b> ${esc(user.mobile)}<br><b>Branch:</b> ${esc(user.branch)}<br><b>Role:</b> ${esc(user.role)}</div>`
 +`<div class="card"><b>Auto sign-out:</b> after 15 minutes with no activity<br><b>Cloud sync:</b> on login · nightly 2 AM · or tap Sync Now</div>`
 +`<div class="actions"><button onclick="backup()">🗄️ Backup Center</button><button class="ghost" onclick="syncNow()">☁️ Sync Now</button></div>`
 +`<div class="tiny mut" style="text-align:center;margin-top:8px">App Version: ${esc(wlv1AppVersion())}</div>`)}
window["settings"]=settings;
function addMonthsSafe(dateStr,months=1){
 let d=dateStr?new Date(dateStr):new Date();
 if(isNaN(d))d=new Date();
 d.setMonth(d.getMonth()+months);
 return d.toISOString().slice(0,10)
}
window["addMonthsSafe"]=addMonthsSafe;
function dateAddDays(dateStr,days=30){
 let d=dateStr?new Date(dateStr):new Date();
 if(isNaN(d))d=new Date();
 d.setDate(d.getDate()+Number(days||0));
 return d.toISOString().slice(0,10)
}
window["dateAddDays"]=dateAddDays;
function doctorDefaultNextDate(){return dateAddDays(today(),30)}
window["doctorDefaultNextDate"]=doctorDefaultNextDate;
/* 🔴🔒 V912 (৩১.০৮.২০২৬) — Doctor Visit / RMP পর্দাতেও ফোনের মতো তাজা তথ্য।
   **ধরা পড়ল:** ফোন এই পর্দা খুললেই `doctor_visits` ক্লাউড থেকে টানে
   (`DoctorVisitActivity`), কম্পিউটার শুধু ব্রাউজারে জমা কপি পড়ত — তাই এক
   ফোনে যোগ করা RMP বা কলের তারিখ কম্পিউটারে পরের লগইনের আগে দেখাত না।
   **নিয়মটা Follow-up-এর প্রমাণিত pull-এর হুবহু নকল:** টেবিলের সই না বদলালে
   একটাও বাইট নামে না; বদলালে শুধু **গত ৩ ঘণ্টায় বদলানো** সারি (সর্বোচ্চ ৫০০)।
   ⛔ ৪৫ সেকেন্ডে দ্বিতীয়বার টানে না, তাই লুপ হয় না।
   ⛔ তথ্য কখনো মোছে না — `protectedRows` আগে, তারপর `mergeById`, আর
      `skipCloud:true` (কোনো নতুন আপলোড নয়)। */
let __wlv1DvPullAt=0;
async function wlv1DvCloudPull(){
  try{
    if(Date.now()-__wlv1DvPullAt<45000) return false;
    __wlv1DvPullAt=Date.now();
    let ok=false; try{ ok=await initCloudClientOnly(); }catch(e){ ok=false; }
    if(!ok||!sb) return false;
    if(await wlv1CloudUnchanged('dv|doctor_visits','doctor_visits',null)) return false;
    const since=new Date(Date.now()-3*3600*1000).toISOString();
    const r=await sb.from('doctor_visits').select('*').gte('updatedAt',since).limit(500);
    if(!r||r.error||!Array.isArray(r.data)) return false;
    wlv1SigCommit('dv|doctor_visits');
    if(!r.data.length) return false;
    const one=wlv1WebNotDeleted('doctor_visits',normalizeCloudRows(r.data));
    if(!one||!one.length) return false;
    save('doctor_visits', mergeById([].concat(protectedRows('doctor_visits'),one), load('doctor_visits')), {skipCloud:true});
    return true;
  }catch(e){ return false; }
}
window["wlv1DvCloudPull"]=wlv1DvCloudPull;
function doctorBranchListRows(q=''){
 let all=load('doctor_visits').filter(x=>!isSeededRecord(x));
 let query=String(q||'').toLowerCase().trim();
 if(isMaster()){
  let br=wlv1RmpBranch();   /* 🟢🔒 V398: মনে-রাখা ব্রাঞ্চ (এক জায়গা থেকে) */
  if(query)return all.filter(x=>String([x.name,x.mobile,x.area,x.branch].filter(Boolean).join(' ')).toLowerCase().includes(query));
  return br?all.filter(x=>!x.branch||sameBranch(x.branch,br)):[];
 }
 if(user?.role==='field'||user?.branch==='All')return all;
 if(query){
  // Cross-branch search is allowed: staff can find/view/call/write remarks with approval reminder.
  return all.filter(x=>String([x.name,x.mobile,x.area,x.branch].filter(Boolean).join(' ')).toLowerCase().includes(query));
 }
 // Normal daily workflow stays branch-wise so staff are not flooded with other branch records.
 return all.filter(x=>!x.branch||sameBranch(x.branch,user?.branch));
}
window["doctorBranchListRows"]=doctorBranchListRows;
function doctorDue(x){let n=x.nextCallDate||'';return !n||n<=today()}
window["doctorDue"]=doctorDue;
function doctorCalledThisMonth(x){let d=doctorLastCall(x);return !!(d&&String(d).slice(0,7)===today().slice(0,7))}
window["doctorCalledThisMonth"]=doctorCalledThisMonth;
function doctorSortList(rows){
 return [...rows].sort((a,b)=>{
  let ad=doctorDue(a)?0:1, bd=doctorDue(b)?0:1; if(ad!==bd)return ad-bd;
  let al=doctorLastCall(a)?1:0, bl=doctorLastCall(b)?1:0; if(al!==bl)return al-bl;
  let an=a.nextCallDate||'9999-12-31', bn=b.nextCallDate||'9999-12-31'; if(an!==bn)return an.localeCompare(bn);
  return String(a.name||'').localeCompare(String(b.name||''));
 })
}
