async function wlv1RmpMasterBranchChange(branch){
 if(!isMaster())return;
 wlv1BranchSet(branch||'');   /* 🟢🔒 V398: সব সেকশনের জন্য একটাই মনে-রাখা ব্রাঞ্চ */
 if(!branch){doctorVisit('home');return;}
 try{
  if(sb){
   let sel=(CLOUD_SAFE_COLS.doctor_visits||[]).join(',')||'*';
   let r=await sb.from('doctor_visits').select(sel).eq('branch',branch).limit(2000);
   if(r.error)throw r.error;
   let fresh=normalizeCloudRows(r.data||[]),old=load('doctor_visits')||[];
   let other=old.filter(x=>String(x.branch||'')!==String(branch));
   let protectedSame=(typeof protectedRows==='function'?protectedRows('doctor_visits'):[]).filter(x=>sameBranch(x.branch,branch))   /* 🔴 V436: ব্রাঞ্চ মেলানো ফোনের মতো সহনশীল */;
   save('doctor_visits',other.concat(mergeById(fresh,protectedSame)),{skipCloud:true});
  }
 }catch(e){toast('Could not load — check connection and try again')}
 doctorVisit('all');
}
window["wlv1RmpMasterBranchChange"]=wlv1RmpMasterBranchChange;
var __wlv1RmpCardCounts=null;
async function wlv1RefreshRmpCardCounts(){
 if(typeof window.webRmpCardCounts!=='function')return;
 let counts=await window.webRmpCardCounts();if(!counts)return;__wlv1RmpCardCounts=counts;
 document.querySelectorAll('[data-rmp-ref-count]').forEach(function(el){let id=el.getAttribute('data-rmp-ref-count');if(Object.prototype.hasOwnProperty.call(counts,id))el.textContent=String(counts[id]);});
}
