let wlv1RefTap={};
function wlv1ReferralTripleTap(docId,index){
  const key=docId+'_'+index,now=Date.now(),old=wlv1RefTap[key]||{n:0,t:0,timer:null};
  if(now-old.t>1200)old.n=0;old.n++;old.t=now;if(old.timer)clearTimeout(old.timer);
  if(old.n===2)toast('Tap once more to edit');
  if(old.n>=3){old.n=0;wlv1RefTap[key]=old;wlv1OpenReferralAtIndex(docId,index);return;}
  old.timer=setTimeout(()=>{old.n=0;const x=load('doctor_visits').find(a=>a.id===docId),r=doctorReferralPayments(x||{})[index],m=mob((r&&r.mobile)||(r&&r.patientMobile)||'');if(m.length===10)wlv1ReportCard(m);},1200);wlv1RefTap[key]=old;
}
function wlv1OpenReferralAtIndex(docId,index){
  let x=load('doctor_visits').find(a=>a.id===docId);if(!x)return toast('Doctor not found');let arr=doctorReferralPayments(x),r=arr[index];if(!r)return toast('Entry not found');
  if(!r.id){let hits=arr.filter(e=>!e.id&&String(e.date||'')===String(r.date||'')&&Number(e.amount||0)===Number(r.amount||0)&&String(e.status||'Unpaid').toLowerCase()===String(r.status||'Unpaid').toLowerCase()&&String(e.patient||'').trim().toLowerCase()===String(r.patient||'').trim().toLowerCase());if(hits.length!==1)return toast('Could not identify one exact entry — nothing changed');r.id='ref_legacy_'+Math.random().toString(36).slice(2)+Date.now().toString(36);arr[index]=r;let inc=doctorReferralTotals([{referralPayments:arr}]);upd('doctor_visits',docId,{referralPayments:arr,referralPaid:inc.paid,referralDue:inc.due});}
  openReferralEdit(docId,r.id);
}
