/* 🟢 B628 (11.08.2026) — ওয়েব parity: Referral Income এডিট/ডিলিট।
   নিয়ম (ফোনের DoctorVisitActivity.openReferralEdit-এর হুবহু):
   • Master অথবা একই-দিন (entry.date == আজ) → সরাসরি এডিট/ডিলিট।
   • স্টাফ/ডাক্তার + দিন পেরিয়ে গেছে → মাস্টারের অনুমোদনের জন্য অনুরোধ (referral_edit_requests)।
   Paid ও Due — দুটোই এডিটযোগ্য। ⛔ মূল referralPayments/মোট হিসাবের বাইরে কিছু ছোঁয় না। */
function openReferralEdit(docId,entryId){
 let x=load('doctor_visits').find(a=>a.id===docId);if(!x)return toast('Doctor not found');
 let arr=doctorReferralPayments(x),r=arr.find(e=>String(e.id)===String(entryId));
 if(!r)return toast('This entry could not be found');
 let master=isMaster(),sameDay=String(r.date||'')===today();
 let paid=String(r.status||'').toLowerCase()==='paid';
 let warn=(!master&&!sameDay)?`<div class="tiny" style="color:#B8860B;font-weight:700;margin-top:8px">This date has passed. Saving or deleting will require Master approval.</div>`:'';
 modal(`<h2>Edit Referral Income</h2><div class="card"><b>${esc(x.name||'')}</b> · ${esc(r.patient||'-')}<label>Referral Amount <span class="req">*</span></label><input id="reAmt" class="input" inputmode="numeric" value="${Number(r.amount||0)}"><label>Status</label><select id="reStatus" class="input"><option value="Unpaid"${paid?'':' selected'}>Due</option><option value="Paid"${paid?' selected':''}>Paid</option></select>${warn}<div class="actions"><button onclick="submitReferralChange('${esc(docId)}','${esc(entryId)}',false)">💾 Save</button><button class="ghost" style="color:#C0392B" onclick="submitReferralChange('${esc(docId)}','${esc(entryId)}',true)">🗑 Delete</button><button class="ghost" onclick="closeModal()">Cancel</button></div></div>`);
}
window["openReferralEdit"]=openReferralEdit;
async function submitReferralChange(docId,entryId,isDelete){
 let x=load('doctor_visits').find(a=>a.id===docId);if(!x)return toast('Doctor not found');
 let arr=doctorReferralPayments(x),idx=arr.findIndex(e=>String(e.id)===String(entryId));
 if(idx<0)return toast('This entry could not be found');
 let r=arr[idx];
 let master=isMaster(),sameDay=String(r.date||'')===today();
 let newAmt=Number(r.amount||0),newStatus=String(r.status||'Unpaid');
 if(!isDelete){
   newAmt=Number(($('#reAmt')?.value)||0);newStatus=$('#reStatus')?.value||'Unpaid';
   if(!(newAmt>0))return toast('Valid referral amount required');
 }else{ if(!confirm('Delete this referral entry?'))return; }
 let now=new Date().toISOString();
 if(master||sameDay){
   let narr=arr.slice();
   if(isDelete){ narr.splice(idx,1); }
   else { narr[idx]={...r,amount:newAmt,status:newStatus,editedAt:now,editedBy:user.mobile}; }
   let inc=doctorReferralTotals([{referralPayments:narr}]);
   upd('doctor_visits',docId,{referralPayments:narr,referralPaid:inc.paid,referralDue:inc.due,updatedAt:now});
   toast(isDelete?'Deleted.':'Saved.');closeModal();viewDoctorVisit(docId);
 }else{
   if(typeof sb==='undefined'||!sb)return toast('No internet connection');
   let row={ id:'refeditreq_'+Math.random().toString(36).slice(2)+Date.now().toString(36),
     docId:docId, entryId:entryId, docName:x.name||'', docMobile:normMob(x.mobile||''), branch:x.branch||'',
     patient:r.patient||'', patientMobile:normMob(r.mobile||r.patientMobile||''),
     oldAmount:Number(r.amount||0), newAmount:newAmt, oldStatus:String(r.status||'Unpaid'), newStatus:newStatus,
     isDelete:!!isDelete, reason:'',
     requestedBy:(user&&user.mobile)||'', requestedByName:(user&&user.name)||((user&&user.mobile)||''),
     requestedAt:now, status:'pending', createdAt:now, updatedAt:now };
   try{ let {error}=await sb.from('referral_edit_requests').insert(row); if(error)return toast('Could not send — try again');
     closeModal(); toast('Request sent for Master approval.'); }catch(e){ toast('Could not send — try again'); }
 }
}
window["submitReferralChange"]=submitReferralChange;
