/* 🖥️🔧 TK-নির্দেশে (১৫.০৮.২০২৬, "Android-এ যা আছে হুবহু মেলান"): Android-এর
   PrintCenterActivity.showProfessionalMobileDialog()-এর হুবহু নিয়ম — মোবাইল/
   নাম টাইপ করে খোঁজা, ১০ ডিজিট হলে সরাসরি প্রিন্ট, নাম হলে ১ জন মিললে
   সরাসরি প্রিন্ট, একাধিক মিললে তবেই তালিকা (নাম + আধা-লুকানো মোবাইল, Android-
   এর resolveMobileOrName/showNameMatchPicker-এর হুবহু) — ডেস্কটপে বড় স্ক্রিন
   বলে পাশাপাশি কয়েক কলামে (TK-অনুমোদিত)। Direct Print শুধু Prescription/
   Medicine Slip/Diet Chart-এ (Android-এর showClinicalPrintFromMobile-এর
   onDirect হুবহু — Payment Receipt-এ Android-এ direct print নেই, তাই ওয়েবেও
   এখানে দেওয়া হলো না)। ⛔ পুরনো choosePrintPatient() ফাংশন মোছা হয়নি (অন্য
   কোথাও ব্যবহার হলে ভাঙবে না), শুধু এই মেনু আর এটা ডাকে না। */
function printSearchPage(type){
  let cfg={
    prescription:{title:'Prescription Print',msg:"Enter the patient's mobile number or name to print their latest saved Prescription.",color:'#1557D6',icon:'℞'},
    medicine:{title:'Medicine Slip Print',msg:"Enter the patient's mobile number or name to print their latest saved Medicine Slip.",color:'#15913A',icon:'💊'},
    diet:{title:'Diet Chart Print',msg:"Enter the patient's mobile number or name to print their latest saved Diet Chart.",color:'#EF6C00',icon:'🥗'},
    blood:{title:'Blood Test Print',msg:"Enter the patient's mobile number or name to print their Blood Test report.",color:'#673AB7',icon:'🧪'},
    printReg:{title:'Patient Registration Print',msg:"Enter the patient's mobile number or name to print their Registration Slip.",color:'#0E7C86',icon:'📝'},
    printPaymentReceipt:{title:'Payment Receipt',msg:"Enter the patient's mobile number or name to print their latest Payment Receipt.",color:'#F79009',icon:'🧾'},
    wlv1PrintCheckup:{title:'Doctor Checkup Print',msg:"Enter the patient's mobile number or name to print their Doctor Checkup.",color:'#673AB7',icon:'🩺'},
    printDoctorVisit:{title:'Doctor Visit Print',msg:"Enter the patient's mobile number or name to print their Doctor Visit.",color:'#673AB7',icon:'👨\u200d⚕️'}
  }[type]||{title:'Print',msg:'Enter mobile number or name.',color:'#673AB7',icon:'🖨'};
  let directOk=(type==='prescription'||type==='medicine'||type==='diet');
  page(cfg.title,`<div class="printSearchCard" style="--accent:${cfg.color}"><div class="printSearchIcon">${cfg.icon}</div><p class="printSearchMsg">${esc(cfg.msg)}</p><input id="printSearchQ" class="input" placeholder="Mobile number or patient name" data-nocaps="1" onkeydown="if(event.key==='Enter')printSearchResolve('${type}')"><div class="printSearchActions"><button onclick="printSearchResolve('${type}')">🔎 FIND &amp; PRINT</button>${directOk?`<button class="ghost" onclick="openDirectPrintForm('${type}')">🖨️ Print without Patient</button>`:''}</div><div id="printSearchResults"></div></div>`,true);
}
window["printSearchPage"]=printSearchPage;
function printSearchResolve(type){
  let q=String(($('#printSearchQ')&&$('#printSearchQ').value)||'').trim();
  if(!q)return toast('Enter mobile number or name');
  let digits=q.replace(/\D/g,'');
  if(digits.length===10){
    let p=scoped(load('patients')).find(x=>mob(x.mobile)===digits);
    if(!p)return toast('No patient found for this mobile. Check the number.');
    runPrintAction(type,p.id);
    return;
  }
  let ql=q.toLowerCase();
  let matches=scoped(load('patients')).filter(x=>String(x.name||'').toLowerCase().includes(ql));
  if(matches.length===0){toast('No patient found with that name. Check the spelling or try the mobile number.');return}
  if(matches.length===1){runPrintAction(type,matches[0].id);return}
  let el=$('#printSearchResults');
  if(el)el.innerHTML=`<div class="sectionTitle" style="margin-top:16px">Select Patient</div><div class="printMatchGrid">${matches.slice(0,30).map(p=>{
    let m=mob(p.mobile||'');let masked=m.length===10?(m.slice(0,2)+'XXXXXX'+m.slice(-2)):'-';
    return `<button class="menuBtn printMatchBtn" onclick="runPrintAction('${type}','${esc(p.id)}')"><span>👤</span><b>${esc(p.name||'-')}</b><small>${esc(masked)}</small></button>`;
  }).join('')}</div>`;
}
