function printDirectDiet(){let p=directPatientFromForm();let items=selectedDietItems();if(!items.length)return toast('Select diet item');
 let __avoid = new Set((typeof DIET_ITEMS!=='undefined'?DIET_ITEMS:[]).filter(d=>String(d.cat||'').toLowerCase().indexOf('avoid')>=0).map(d=>d.text));
 let rows=items.map(x=>`<tr><td>${__avoid.has(x)?'&#10007;':'&#10003;'} ${esc(x)}</td></tr>`).join('');let remarks=$('#dtRem')?.value||'';closeModal();professionalDirectMedicalPrint(p,'DIET CHART',`<table class="printTable finalPrintTable"><tr><th>Diet Advice</th></tr>${rows}</table>`,remarks)}
