function printPaymentReceipt(id){let p=load('patients').find(x=>x.id===id);if(!p)return toast('Patient not found');let pays=load('payments').filter(x=>payOwnedBy(x,p));/* 🔵🔒 V520: রসিদে অন্য রোগীর টাকা যেন কখনো না ছাপে। */if(!pays.length)return toast('No payment data available for printing.');let rows=pays.map((x,i)=>`<tr><td>${esc(fmtDate(x.date||''))}</td><td>${esc(collectionPaymentLabel(x))}${(x.payType||'treatment')==='treatment'?` (${esc(paymentDisplayLabel(x,i))})`:''}</td><td>${esc(x.mode||'')}</td><td>${money(x.amount)}</td></tr>`).join('');let total=pays.reduce((s,x)=>s+Number(x.amount||0),0);
// 🔴 TK-অডিট-অনুরোধ (01.08.2026): রোগীর হাতে যাওয়া ছাপা রসিদে Refund সারিও
// যোগ হয়ে যাচ্ছিল — প্রতিটা সারি আলাদা করে দেখা যাক (স্বচ্ছতার জন্য), কিন্তু
// নিচের মোট থেকে approved refund বিয়োগ হওয়া উচিত।
try{ pays.filter(wlv1IsApprovedRefund).forEach(x=>{ total-=Number(x.amount||0); }); }catch(_e){}
/* 🔴 V430 (TK-সিদ্ধান্ত ১৮.০৮.২০২৬: "দুটোই রাখুন — একসাথে") — ফোনের রসিদে
   (PaymentActivity.kt:1114-1134) যে হিসাবটা থাকে — মোট বিল · মোট জমা · বাকি ·
   রোগ · ব্রাঞ্চ · কে নিলেন — সেটা ওয়েবের কাগজে ছিলই না; শুধু সব পেমেন্টের
   টেবিল ছিল। এখন **টেবিলের উপরে ফোনের সেই হিসাবটাও** বসে, তাই রোগী দুই
   জায়গা থেকেই একই তথ্য পান।
   ⛔ টেবিল ও তার মোট এক অক্ষরও বদলায়নি — শুধু উপরে একটা হিসাবের বাক্স যোগ। */
const __tt = (typeof treatmentTotals==='function') ? (treatmentTotals(p)||{}) : {};
const __bill = Number(__tt.bill||p.bill||0);
const __due  = __bill>0 ? Math.max(0, __bill-total) : 0;
const __last = pays[pays.length-1] || {};
const __by   = (typeof codeName==='function' ? (codeName(__last.receivedBy||__last.createdBy||'')||'') : '');
const __sumRow = (k,v,c)=>`<div class="rcpRow"><span>${k}</span><b${c?` style="color:${c}"`:''}>${v}</b></div>`;
const __summary = `<div class="rcpBox">`
  + __sumRow('Patient', esc(String(p.name||'')))
  /* 🔴🔴🆕🔒 V437 (নিজের অডিটে ধরা — ফোন-বনাম-ওয়েব তালিকার #৩)। ফোনের রসিদে
     (`PaymentActivity.kt:1168-1177`) সারিগুলোর ক্রম: Patient · **Patient ID** ·
     Disease · Total Bill · **This Payment (mode)** · Total Paid · Due · Date ·
     Branch · Received by। ওয়েবে **"This Payment" সারিটাই ছিল না**, লেখা ছিল
     শুধু "ID", আর তারিখে বসত **আজকের** তারিখ — পেমেন্টের নিজের তারিখ নয়।
     (পুরনো তারিখের রসিদ ছাপলে কাগজে ভুল তারিখ যেত।) এখন ফোনের হুবহু।
     ⛔ নিচের টেবিল ও মোট এক অক্ষরও বদলায়নি। */
  + (p.patientId?__sumRow('Patient ID', esc(p.patientId)):'')
  + (p.disease?__sumRow('Disease', esc(p.disease)):'')
  + (__bill>0?__sumRow('Total Bill', money(__bill)):'')
  + (Number(__last.amount||0)>0?__sumRow('This Payment'+(__last.mode?` (${esc(String(__last.mode))})`:''), money(__last.amount)):'')
  + __sumRow('Total Paid', money(total), '#0A7C3F')
  + (__bill>0?__sumRow('Due', money(__due), __due>0?'#B42318':'#0A7C3F'):'')
  + __sumRow('Date', esc(fmtDate(__last.date||today())))
  + __sumRow('Branch', esc(String(p.branch||'')))
  + (__by?__sumRow('Received by', esc(__by)):'')
  + `</div>`;
app().innerHTML=printReturnBar(id)+printHead(p,'TREATMENT PAYMENT RECEIPT')+__summary+`<table class="printTable finalPrintTable"><tr><th>Date</th><th>Type</th><th>Mode</th><th>Amount</th></tr>${rows}<tr><th colspan="3">Total</th><th>${money(total)}</th></tr></table>`+printFoot('',p,'TREATMENT PAYMENT RECEIPT');safePrintNoHome(id)}
