function printDoctorsHtml(p,type=''){
 const t=String(type||'').toUpperCase();
 const vc=printVerifyCenter(p);
 if(t==='PRESCRIPTION'||t==='Prescription')return `<div class="docLeft"><b>TK BISWAS</b><small>Founder &amp; Consultant</small></div>${vc}<div class="docRight"><b>Dr. K.H MANDAL</b><small>(B.A.M.S) Regd 12386</small></div>`;
 if(isKishanganjBranchName(p?.branch))return `<div class="docLeft"><b>TK BISWAS</b><small>Founder &amp; Consultant</small></div>${vc}<div class="docRight emptyDoc"></div>`;
 /* 🔒 গ্লোবাল রুল (TK-নির্দেশ, ১৬.০৮.২০২৬): "কোথায় কোথায় এটা নেই, বসিয়ে দিন"।
    আগে এই পথে (কিশানগঞ্জ ছাড়া অন্য ব্রাঞ্চের Prescription-বহির্ভূত প্রিন্ট — যেমন
    Medicine Slip, Blood Test, Payment Receipt) **দুই পাশই ফাঁকা** থাকত, TK BISWAS-এর
    লাইনটাই ছাপা হত না। এখন বাঁ-পাশে ওটা বসে।
    ⛔ ডান পাশ (ডাক্তারের সই) আগের মতোই ফাঁকা — কোন কাগজে কোন ডাক্তারের নাম বসবে
       সেটা আন্দাজে ঠিক করিনি; আপনি বললে বসাব। */
 return `<div class="docLeft"><b>TK BISWAS</b><small>Founder &amp; Consultant</small></div>${vc}<div class="docRight emptyDoc"></div>`;
}
