/* 🔴 V430 (TK-নির্দেশ ১৮.০৮.২০২৬) — ফোনের ভাগ করার নিয়মে **দুটো** ধরন আছে
   (ClinicalRepository.kt:78-92), ওয়েবে শুধু প্রথমটা ছিল:
     ১) "2-0-2 After Food" → Dose 2-0-2 · When After Food
     ২) "Local application twice daily" → Dose L/A · When Twice daily
   দ্বিতীয়টা না থাকায় Metrogyl · Betadine ধরনের ওষুধে ছাপা কাগজের WHEN ঘরটা
   ফাঁকা পড়ে থাকত আর গোটা বাক্যটা সরু DOSE ঘরে ঢুকে যেত।
   ⛔ সেভ করা কোনো লেখা বদলায় না — শুধু দেখানো ও ছাপার সময় ভাগ হয়। */
/* 🖥️🔵 V548 (২২.০৮.২০২৬, TK-নির্দেশ ছাপা কাগজসহ):
   *"সমস্ত তথ্য থাকা সত্ত্বেও প্রেসক্রিপশনে symptom · duration · chief complaint
     ফাঁকা কেন আসছে"* — Check-up না হওয়া রোগীর ক্ষেত্রে।
   রেজিস্ট্রেশন একটাই ঘরে লেখে: complaint = "<উপসর্গের তালিকা> | <টাইপ করা কথা>"
   (app.js-এর নিজের রেজিস্ট্রেশন কোড: `[symptoms,compNote].filter(Boolean).join(' | ')`)।
   তাই ছাপার সময় ওই একটাই লেখা দুই ভাগে ভাগ করে বসানো হয় — ফোনেও (V548) হুবহু এই নিয়ম।
   ⛔ Doctor Check-up থাকলে তার মানই আগে; এটা শুধু ফাঁকা ঘরের জন্য।
   ⛔ কোনো তথ্য বদলানো/মোছা হয় না — শুধু যা আছে তাই দেখানো হয়। */
function rxRegSplit(p){
  try{
    if(Array.isArray(p&&p.symptoms)&&p.symptoms.length) return {sym:p.symptoms.join(', '),note:String((p&&p.complaint)||'').trim()};
    var raw=String((p&&p.complaint)||'').trim();
    var i=raw.indexOf(' | ');
    return (i>=0)?{sym:raw.slice(0,i).trim(),note:raw.slice(i+3).trim()}:{sym:raw,note:''};
  }catch(e){ return {sym:'',note:''} }
}
function rxRegSymptoms(p){return rxRegSplit(p).sym}
function rxRegComplaint(p){return rxRegSplit(p).note}
window["rxRegSymptoms"]=rxRegSymptoms;window["rxRegComplaint"]=rxRegComplaint;
/* 🖥️🔵 V548: মনে-রাখা ডোজ থেকে When হারিয়ে গেলে প্রজেক্টের আদত When
   (`RX_DOSE_MAP`) ফিরিয়ে দেওয়া হয় — ফোনের `rxWhenFor`-এর হুবহু জোড়া।
   ⛔ তালিকায় নেই এমন ওষুধে ফাঁকাই থাকে, কিছুই বানানো হয় না। */
function rxWhenFor(name){try{return splitRxDoseWhen(RX_DOSE_MAP[String(name||'').trim()]||'').whenText}catch(e){return ''}}
/* 🍯🔒 V956 (০১.০৯.২০২৬, TK-নির্দেশ) — TK: *"অনেক সময় কোন মেডিসিন মধু দিয়ে খেতে
   বলতে হয়, মাখন দিয়ে খেতে বলতে হয় … একবার সেট করে থাকলে সারা জীবন যেন একই রকম
   থাকে"*। আগে Dose ও When জোড়া লেখা থেকে ভাগ করা হত আর `splitRxDoseWhen` শুধু
   হুবহু "After Food"/"Before Food" চিনত — তাই "After Food with Honey" পরের বার
   Dose-এর ঘরে ঢুকে যেত ও When আগেরটাই ফিরে আসত। এই ঘরটা **জমা করা আলাদা
   whenText**-কেই আগে ধরে (ফোনের `rxDoseWhenFor`-এর হুবহু জোড়া)।
   ⛔ কিছু জমা না থাকলে আগের নিয়মই চলে — পুরনো কোনো ডিফল্ট নষ্ট হয় না। */
function rxDoseWhenFor(name){
  try{
    let key=String(name||'').trim(), d=rxDefaultFor(key), fb=splitRxDoseWhen(rxDoseFor(key));
    let sd=String(d&&d.dose||'').trim(), sw=String(d&&d.whenText||'').trim();
    return {dose:sd||fb.dose, whenText:sw||fb.whenText||rxWhenFor(key)};
  }catch(e){return {dose:'',whenText:''}}
}
window["rxWhenFor"]=rxWhenFor;
function splitRxDoseWhen(v){
  let s=String(v||'').trim();
  let m=s.match(/^([\d\-]+)\s+(After Food|Before Food)$/i);
  if(m) return {dose:m[1],whenText:m[2]};
  /* 🔵 V548: প্রজেক্টের নিজের তালিকায় লেখা আছে "Local App. Morning & Evening"
     (RX_DOSE_MAP), কিন্তু এখানে শুধু "Local application" চেনা হত — তাই ওই ওষুধের
     When ফাঁকা পড়ে থাকত। এখন দুটো লেখাই চেনে (ফোনে ClinicalRepository-তে
     "Local application" আগে থেকেই চেনা)। ⛔ আর কিছুই বদলায়নি। */
  let la=s.match(/^Local App(?:lication|\.)?\s+(.+)$/i);
  if(la){ let rest=la[1].trim(); return {dose:'L/A', whenText:rest.charAt(0).toUpperCase()+rest.slice(1)}; }
  return {dose:s,whenText:''};
}
function combinedRxDose(x){return [String(x?.dose||'').trim(),String(x?.whenText||'').trim()].filter(Boolean).join(' ')}
const RX_FIXED_COMMON=[
 {name:'Arshakuthar Rasa',medicineType:'Tab',dose:'2-0-2',whenText:'After Food',days:'5'},
 {name:'Kankayan Vati Arsha',medicineType:'Tab',dose:'2-0-2',whenText:'After Food',days:'5'},
 {name:'Abhayadi Modak',medicineType:'Tab',dose:'0-0-1',whenText:'After Food',days:'5'},
 {name:'Jatyadi Ghritam',medicineType:'Oint',dose:'Local App.',whenText:'Morning & Evening',days:'5'},
 {name:'Qurs Alkali',medicineType:'Tab',dose:'2-0-2',whenText:'Before Food',days:'5'},
 {name:'Habb-e-Kabid Naushadri',medicineType:'Tab',dose:'1-0-1',whenText:'Before Food',days:'5'}
];
function rxDefaultFor(name){let key=String(name||'').trim(),m=rxDefaultsMap(),x=m[key];if(x)return x;let f=RX_FIXED_COMMON.find(x=>x.name===key);return f?Object.assign({updatedAt:''},f):null}
function rxTypeFor(name){return String(rxDefaultFor(name)?.medicineType||'')}
function rxDaysFor(name){return rxCleanDays(rxDefaultFor(name)?.days||'5')}
async function rxStableId(name){try{let b=new TextEncoder().encode(String(name||'').trim().toLowerCase()),d=await crypto.subtle.digest('SHA-256',b),h=[...new Uint8Array(d)].slice(0,16).map(x=>x.toString(16).padStart(2,'0')).join('');return h?'rx_'+h:''}catch(e){return ''}}
async function rxDefaultCloudUpsert(row){try{let ok=await initCloudClientOnly();if(!ok||!sb)return false;let id=await rxStableId(row.name);if(!id)return false;let payload={id,name:row.name,medicineType:row.medicineType||'',dose:row.dose||'',whenText:row.whenText||'',days:rxDaysForPrint(row.days),updatedAt:row.updatedAt};let r=await sb.from('medicine_defaults').upsert([payload],{onConflict:'id'});return !r.error}catch(e){return false}}
function rememberRxDefault(name,type,doseText,days,whenExplicit){try{let key=String(name||'').trim();if(!key||!type)return false;/* 🔴 V425: When আলাদা ঘরে লেখা হলে সেটাই ধরা হয় (ফ্রি-টেক্সট When যেন split-এ হারিয়ে না যায়); না দিলে আগের নিয়মেই ভাগ হয় — পুরনো সব ডাক অপরিবর্তিত। */let p=(whenExplicit!==undefined&&String(whenExplicit).trim())?{dose:String(doseText||'').trim(),whenText:String(whenExplicit).trim()}:splitRxDoseWhen(doseText),m=rxDefaultsMap(),row={name:key,medicineType:String(type),dose:p.dose,whenText:p.whenText,days:rxCleanDays(days),updatedAt:new Date().toISOString()};m[key]=row;saveRxDefaultsMap(m);rxDefaultCloudUpsert(row);return true}catch(e){return false}}
async function rxDefaultsRefreshFromCloud(force,cloudReady){try{let last=Number(localStorage.getItem('rxDefaultsLastPull')||0);if(!force&&Date.now()-last<15*60*1000)return false;if(!cloudReady){let ok=await initCloudClientOnly();if(!ok||!sb)return false}let r=await sb.from('medicine_defaults').select('id,name,medicineType,dose,whenText,days,updatedAt').limit(500);if(r.error||!Array.isArray(r.data))return false;let local=rxDefaultsMap(),remote={};r.data.forEach(x=>{let k=String(x.name||'').trim();if(!k)return;remote[k]=x;let l=local[k],ls=String(l?.updatedAt||''),rs=String(x.updatedAt||'');if(!l||!ls||rs>=ls)local[k]={name:k,medicineType:x.medicineType||'',dose:x.dose||'',whenText:x.whenText||'',days:rxCleanDays(x.days),updatedAt:rs}});saveRxDefaultsMap(local);localStorage.setItem('rxDefaultsLastPull',String(Date.now()));for(const k of Object.keys(local)){let l=local[k],rr=remote[k];if(!rr||String(l.updatedAt||'')>String(rr.updatedAt||''))rxDefaultCloudUpsert(l)}return true}catch(e){return false}}
window["rxDefaultsRefreshFromCloud"]=rxDefaultsRefreshFromCloud;
/* 🔴 V430 (TK-নির্দেশ ১৮.০৮.২০২৬) — ফোনে ওষুধ বাছার পর্দায় একটা
   **🔍 Search ঘর** ও **"N selected" গোনা** থাকে (MedicinePickerDialog.kt:284,353);
   ওয়েবে দুটোরই কিছু ছিল না — লম্বা তালিকায় ওষুধ খুঁজে বার করতে হত চোখে।
   ⛔ তালিকা বা কোনো ডোজ বদলায়নি — শুধু খোঁজা সহজ হলো, আর কটা বাছা হয়েছে
      সেটা এক নজরে দেখা যায়। */
function rxSearchFilter(v){
  try{
    const q=String(v||'').trim().toLowerCase();
    document.querySelectorAll('.rxMedRow2').forEach(function(row){
      const nm=String(row.getAttribute('data-med-row')||'').toLowerCase();
      row.style.display = (!q || nm.indexOf(q)>=0) ? '' : 'none';
    });
    /* 🖥️🔵 V546 (২২.০৮.২০২৬, TK-নির্দেশ — ফোন ও ওয়েব একই দিনে, প্যাকেজিং-নিয়ম):
       *"যখন মেডিসিন সেখানে কিছু লিখব তখন উপরের এত কিছু বিস্তারিত থাকার তো কোনো দরকার নেই ...
         সেখান থেকে ব্যাক করলে আবার এই স্ক্রিনে আসবে"*
       খোঁজার ঘরে লেখা থাকলেই উপরের কার্ডটা (Sitz Bath · Diet · Disease Name · Symptoms ·
       Since When · Chief Complaint · "+ Choose More Information") লুকোয়; ঘর ফাঁকা হলেই
       (× / Esc / মুছে দিলে) হুবহু আগের অবস্থায় ফিরে আসে।
       ⛔ কোনো টিক বা লেখা হারায় না — কার্ডটা শুধু দেখানো বন্ধ থাকে, DOM-এ আগের মতোই
          থাকে, তাই rxSaveOptions() আগের মতোই সব পড়ে।
       ⛔ Medicine Slip / Direct-print পর্দায় এই কার্ডই নেই — সেখানে কিছুই বদলায় না। */
    document.querySelectorAll('.rxCompactOptions').forEach(function(card){
      card.style.display = q ? 'none' : '';
    });
  }catch(e){}
}
window["rxSearchFilter"]=rxSearchFilter;
function rxSelectedCount(){
  try{
    const n=document.querySelectorAll('.rxChk:checked').length;
    const b=document.getElementById('rxSelCount');
    if(b) b.textContent = n+' selected';
  }catch(e){}
}
window["rxSelectedCount"]=rxSelectedCount;
function medCheckList(list){return `<div class="rxPickTop"><input id="rxSearchBox" class="input rxSearchBox" type="search" placeholder="&#128269; Search" oninput="rxSearchFilter(this.value)"><b id="rxSelCount">0 selected</b></div><div class="checkGrid premiumChecks rxCheckGrid rxCheckGridV2">${list.map((x,i)=>`<div class="rxMedRow2" data-med-row="${esc(x)}">
  <label class="rxTickItem2"><input type="checkbox" class="rxChk" value="${esc(x)}" onchange="onRxMedicineChange();rxSelectedCount()"><select class="rxTypeInput" data-med="${esc(x)}" onclick="event.stopPropagation()">${rxTypeOptions(rxTypeFor(x))}</select><span class="rxMedName">${esc(x)}</span></label>
  <div class="rxDoseRow2"><span class="rxDoseLabel2">Dose:</span><input type="text" class="rxDoseInput rxDoseInput2" id="rxDoseFor_${i}" data-med="${esc(x)}" value="${esc(rxDoseWhenFor(x).dose)}"><span class="rxWhenLabel2">When:</span><input type="text" class="rxWhenInput rxWhenInput2" id="rxWhenFor_${i}" data-med="${esc(x)}" value="${esc(rxDoseWhenFor(x).whenText)}"><input type="text" class="rxDaysInput rxDaysInput2" id="rxDaysFor_${i}" data-med="${esc(x)}" value="${esc(rxDaysForPrint(rxDaysFor(x)))}" inputmode="text"></div>
</div>`).join('')}</div>`}
window["medCheckList"]=medCheckList;
const RX_DOSE_MAP={
 'Arshakuthar Rasa':'2-0-2 After Food','Kankayan Vati Arsha':'2-0-2 After Food','Bolbadha Rasa':'1-0-1 After Food','Raktasthambhak Vati':'1-0-1 After Food','Rasamanikya':'1-0-1 After Food','Sameerpanag Rasa':'1-0-1 After Food','Arogyadhadi kashayam':'15 ml with equal water twice daily after food','Septilin':'1-0-1 After Food','Abhyaristram':'15 ml with equal water twice daily after food','Jatyadi Ghritam':'Local App. Morning & Evening','Abhayadi Modak':'0-0-1 After Food','Qurs Alkali':'2-0-2 Before Food','Habb-e-Kabid Naushadri':'1-0-1 Before Food','Nityam':'1 at bedtime','Trivrilehan':'1 tsp at bedtime with warm water',
 'Omez DSR':'1-0-0 Before Food','Rabekind DSR':'1-0-0 Before Food','Pantop DSR':'1-0-0 Before Food','Aciloc 300':'0-0-1 After Food','P-40':'1-0-0 Before Food','Voveran SR 100':'0-0-1 After Food','Voveran 50':'1-0-1 After Food','Zerodol SP':'1-0-1 After Food','Clavam 625':'1-0-1 After Food','Monocef O CV 200':'1-0-1 After Food','Taxim O CV 200':'1-0-1 After Food','Taxim 200':'1-0-1 After Food','Roclav 625 LB':'1-0-1 After Food','Bicosul':'1-0-0 After Food','Zincovit':'1-0-0 After Food','RB Tone 200 ml':'2 tsp twice daily after food','Celin 500':'1-0-0 After Food','Metrogyl P 2% 20 gm':'Local application twice daily','Betadine 5% 25 gm':'Local application as advised'
};
function rxDoseMemoryMap(){try{return JSON.parse(localStorage.getItem('rxDoseMemory')||'{}')}catch(e){return {}}}
function rxDoseFor(name){let key=String(name||'').trim(),def=rxDefaultFor(key);if(def){let full=combinedRxDose(def);if(full)return full}let mem=rxDoseMemoryMap();if(mem[key])return mem[key];return RX_DOSE_MAP[key]||'As advised'}
function rememberRxDose(name,dose){try{let key=String(name||'').trim();if(!key||!dose)return;let mem=rxDoseMemoryMap();mem[key]=dose;localStorage.setItem('rxDoseMemory',JSON.stringify(mem))}catch(e){}}
window["rememberRxDose"]=rememberRxDose;
window["rxDoseFor"]=rxDoseFor;
function onRxMedicineChange(){let checked=$$('.rxChk:checked');let last=checked[checked.length-1];let d=$('#rxDose'),days=$('#rxDays');if(d&&last)d.value=rxDoseWhenFor(last.value).dose;/* 🍯 V956: শুধু ডোজটুকু — When আলাদা ঘর থেকেই আসে */if(days&&last)days.value=rxDaysFor(last.value)}
