/* একটা সারি — ইংরেজি/বাংলা/হিন্দি তিন লাইনে (ফোনের CheckBox-এর মতোই) */
function wlv1DietA4Row(txt,mark){
  var q=String(txt||'').split('\n');
  return '<li><span class="mk">'+mark+'</span><span>'
    +'<span class="en">'+esc(q[0]||'')+'</span>'
    +(q[1]?'<span class="bn">'+esc(q[1])+'</span>':'')
    +(q[2]?'<span class="hi">'+esc(q[2])+'</span>':'')+'</span></li>';
}
window["wlv1DietA4Row"]=wlv1DietA4Row;

function wlv1DietA4Html(p, picked, remarks){
  p=p||{};
  var b=(typeof branch==='function')?branch(p.branch):{};
  var isK=(typeof isKishanganjBranchName==='function')&&isKishanganjBranchName(p.branch);
  var logo=isK?'assets/kishanganj-final-logo.jpg':'assets/maa-ayurved-final-logo.jpg';
  var clinic=(typeof clinicPrintTitle==='function')?clinicPrintTitle(p):'MAA AYURVED PILES CLINIC';
  var brLine=isK?'':('<div class="br">'+esc(String(p.branch||'').toUpperCase())+' BRANCH</div>');
  picked=picked||[];
  // ⛔ কোনটা "খাবেন" আর কোনটা "এড়িয়ে চলুন" — অ্যাপের নিজের দুই তালিকা ধরেই ঠিক হয়
  var ok=picked.filter(function(x){return WLV1_DIET_ALLOWED.indexOf(x)>=0;});
  var no=picked.filter(function(x){return WLV1_DIET_AVOID.indexOf(x)>=0;});
  var okHtml=ok.map(function(x){return wlv1DietA4Row(x,'✓')}).join('') || '<li><span class="mk"></span><span><span class="en">—</span></span></li>';
  var noHtml=no.map(function(x){return wlv1DietA4Row(x,'✗')}).join('') || '<li><span class="mk"></span><span><span class="en">—</span></span></li>';
  var pid=esc(p.patientId||'-');
  var addr=(typeof wlv1AddrTwo==='function')?wlv1AddrTwo(p.address||''):esc(p.address||'-');
  var dt=(typeof fmtDate==='function')?fmtDate(today()):today();
  return '<!DOCTYPE html><html><head><meta charset="utf-8"><style>'+wlv1DietA4Css()+'</style></head><body><div class="sheet">'
  +'<img class="wm" src="'+logo+'">'
  +'<div class="head"><img src="'+logo+'"><div class="hc"><h1>'+esc(clinic)+'</h1>'+brLine
  +'<div class="rule"></div><div class="ad">'+esc(b.address||'')+' &nbsp;|&nbsp; Mob: '+esc(b.mobile||'')+' &nbsp;|&nbsp; Helpline: '+esc(WLV1_HELPLINE)+'</div>'
  +'<div class="tag"><b>WE PROVIDE AYURVEDA KSHAR SUTRA THERAPY IN PILES, FISSURE &amp; FISTULA</b>'
  +'<span>MOST SUCCESSFUL TREATMENT WITH HIGH SUCCESS RATE</span></div></div></div><div class="sep"></div>'
  +'<div class="title"><b>DIET &amp; LIFESTYLE CHART</b><span>PILES &nbsp;·&nbsp; FISSURE &nbsp;·&nbsp; FISTULA</span></div>'
  +'<div class="pt">'
  +'<div><b>Patient Name</b> : '+esc(String(p.name||'').toUpperCase())+'</div>'
  +'<div><b>Age / Sex</b> : '+esc(p.age||'-')+' / '+esc(String(p.sex||'').toUpperCase()||'-')+'</div>'
  +'<div><b>Date</b> : '+esc(dt)+'</div>'
  +'<div><b>Patient ID</b> : '+pid+'</div>'
  +'<div><b>Mobile</b> : '+esc((typeof normMob==='function')?normMob(p.mobile||''):(p.mobile||''))+'</div>'
  +'<div><b>Branch</b> : '+esc(p.branch||'')+'</div>'
  +'<div class="full"><b>Address</b> : '+addr+'</div></div>'
  +'<div class="tg">'
  +'<div><div class="ic">🌾</div><div class="vl">25–30 g</div><div class="lb">FIBRE / DAY<br>আঁশ · फाइबर</div></div>'
  +'<div><div class="ic">💧</div><div class="vl">6–8 glasses</div><div class="lb">WATER / DAY<br>জল · पानी</div></div>'
  +'<div><div class="ic">🛁</div><div class="vl">10 min × 2–3</div><div class="lb">WARM SITZ BATH<br>সিটজ বাথ · सिट्ज़ बाथ</div></div>'
  +'<div><div class="ic">🚶</div><div class="vl">30 min</div><div class="lb">WALK / DAY<br>হাঁটা · सैर</div></div></div>'
  +'<div class="cols">'
  +'<div class="box ok"><h3>✓ &nbsp;EAT / DO &nbsp;— &nbsp;খাবেন ও করবেন</h3><ul>'+okHtml+'</ul></div>'
  +'<div class="box no"><h3>✗ &nbsp;AVOID &nbsp;— &nbsp;এড়িয়ে চলুন</h3><ul>'+noHtml+'</ul></div></div>'
  +'<div class="gold"><h4>★ GOLDEN RULES &nbsp;— &nbsp;সোনালি নিয়ম</h4><ol>'
  +'<li><b>1</b>Go to the toilet as soon as you feel the urge — never hold it. <i>বেগ এলেই যাবেন, চেপে রাখবেন না।</i></li>'
  +'<li><b>2</b>Do not strain or push. Do not sit longer than needed. <i>জোর করবেন না, বেশিক্ষণ বসে থাকবেন না।</i></li>'
  +'<li><b>3</b>Rest your feet on a low stool so knees stay above hips. <i>পায়ের নিচে টুল রাখুন, হাঁটু কোমরের উপরে।</i></li>'
  +'<li><b>4</b>Increase fibre slowly over 1–2 weeks, with extra water. <i>আঁশ ধীরে ধীরে বাড়ান, সঙ্গে বেশি জল।</i></li>'
  +'<li><b>5</b>Keep the area clean and dry; pat, do not rub. <i>জায়গাটা পরিষ্কার ও শুকনো রাখুন, ঘষবেন না।</i></li>'
  +'<li><b>6</b>Take medicines exactly as written on the prescription. <i>ওষুধ প্রেসক্রিপশন মতোই খাবেন।</i></li>'
  +'</ol></div>'
  +(remarks?'<div class="warn rem"><b>Advice / Remarks:</b> '+esc(remarks)+'</div>':'')
  +'<div class="warn"><b>⚠ Report at once</b> if there is heavy bleeding, fever, increasing pain, pus discharge, or you cannot pass stool or urine. &nbsp;'
  +'<b>এখনই জানান</b> — বেশি রক্তপাত, জ্বর, ব্যথা বাড়া, পুঁজ, বা পায়খানা-প্রস্রাব বন্ধ হলে।</div>'
  /* 🔒 V391 (TK-নির্দেশ, ১৬.০৮.২০২৬): নিচের সই-সারি — বাঁয়ে TK BISWAS,
     মাঝে বারকোড, ডানে Dr. K.H MANDAL। অ্যাপের Prescription প্রিন্টেও
     ঠিক এই দুজনই বসে (`printDoctorsHtml`), তাই কাগজে-কাগজে মিল থাকল। */
  +'<div class="sign"><div class="ln"><b>TK BISWAS</b><small>Founder &amp; Consultant</small></div>'
  +'<div class="vfy"><b>Document Digitally Verified</b><small>No Physical Signature Required</small><div class="bar"></div><div class="id">'+pid+'</div></div>'
  +'<div class="ln"><b>Dr. K.H MANDAL</b><small>(B.A.M.S) Regd 12386</small></div></div>'
  +'<div class="next"><span>Next Follow-up Date : <b>_____________________</b></span><span>Chart valid for : <b>30 days</b></span></div>'
  +'<div class="thanks">All treatments are Ayurvedic &amp; Natural &nbsp;|&nbsp; Bring this chart on your next visit</div>'
  +'<div class="src">Daily targets follow published patient guidance — fibre 25–30 g/day and warm sitz bath ~10 minutes several times daily (UCSF Health); fluid 6–8 glasses/day and footstool position (Cambridge University Hospitals NHS); increase fibre gradually with fluids (NIDDK, NIH). This chart is general advice and does not replace your doctor’s instructions.</div>'
  +'</div></body></html>';
}
