function printSimple(id,type){
 if(!medDraft.length)addRxItem();
 let p=patientById(id);
 if(!p)return toast('Patient not found');
 medDraft.forEach(x=>rememberRxDefault(x.name,x.medicineType,combinedRxDose(x)||x.dose,x.days));
 let list=medDraft.length?medDraft.map((m,i)=>{let dw=(m&&m.whenText&&String(m.whenText).trim())?{dose:String(m.dose||'').trim(),whenText:String(m.whenText).trim()}:splitRxDoseWhen(combinedRxDose(m)||m.dose);if(!dw.whenText)dw={dose:dw.dose,whenText:rxWhenFor(m&&m.name)};/* 🔵 V548: When যেন ফাঁকা না ছাপে *//* 🔴 V425: When আলাদা লেখা থাকলে হুবহু সেটাই When কলামে */return `<tr><td>${i+1}</td><td><span class="rxPrintType">${esc(m.medicineType||'')}</span>${esc(m.name)}</td><td>${esc(dw.dose)}</td><td>${esc(dw.whenText)}</td><td>${esc(rxDaysForPrint(m.days))}</td></tr>`}).join(''):'<tr><td colspan="5">No item selected</td></tr>';
 closeModal();
 if(type==='PRESCRIPTION'||type==='Prescription'){
  let o=rxOptions(id),n=p.doctorFullNote||{},values={disease:p.disease||'',symptoms:rxRegSymptoms(p),since:p.sinceWhen||p.duration||n.duration||'',complaint:n.complaint||rxRegComplaint(p),previousTreatment:n.previousTreatment||p.previousTreatment||'',previousResult:n.previousResult||p.previousResult||'',onset:n.acuteChronic||'',treatmentDuration:n.treatmentDuration||p.treatmentDuration||''};
  let labels=Object.fromEntries(RX_HISTORY_FIELDS.concat(RX_MORE_FIELDS)),history=o.fields.map(k=>`<div><b>${esc(labels[k])}</b><span>${esc(values[k]||'')}</span></div>`).join('');/* 🔴 V425 (TK-নির্দেশ ১৭.০৮.২০২৬: "Not Recorded লেখা থাকবে না · প্রয়োজনে ফাকা প্রিন্ট হবে · যাতে প্রিন্ট আউট এর পরে লেখাও যায়") — ফোনের PrescriptionOptionsStore.kt-এর হুবহু একই বদল। ফাঁকা ঘরে হাতে লেখার জায়গা styles.css-এ (span:empty) */
  /* 🔵 V406 (TK-অনুমোদিত V397 লেআউট) — ADVICE · Diet · Next Follow-up Date
     এখন **বাঁ ঘরের একদম তলায়** (`.anRxBot`), আগে টেবিলের নিচে ডান দিকে ছিল।
     Diet-এর লেখা `Diet — x` থেকে `<b>Diet:</b> x` হলো (অনুমোদিত নকশা)। */
  let advice=`<div class="rxPrintAdvice"><span><b>ADVICE:</b> Sitz Bath — 2 Times Daily</span>${o.diet?`<span class="rxDietLine"><b>Diet:</b> ${esc(o.diet)}</span>`:''}</div>`;
  let nextBox=`<div class="anRxNext"><b>Next Follow-up Date</b><span>${p.nextFollow?esc(wlv1Dot(p.nextFollow)):'_______________'}</span></div>`;
  let bot=`<div class="anRxBot">${advice}${nextBox}</div>`;
  professionalMedicalPrint(id,'PRESCRIPTION',`<div class="rxApprovedGrid" style="--clinic-watermark:url('${branchPrintLogoPath(p)}')"><aside class="rxComplaintHistory">${history}${bot}</aside><section><div class="rxGridMark">℞</div><table class="printTable finalPrintTable"><tr><th>SL</th><th>Medicine Name</th><th>Dose</th><th>When</th><th>Duration</th></tr>${list}</table></section></div>`);
  return;
 }
 /* 🔵 V406 — **Medicine Slip এখন প্রেসক্রিপশনের হুবহু একই গঠনে** (TK-অনুমোদিত)।
    ⛔ আগে এখানে একটা **আসল দোষ** ছিল: উপরের `list` ৫টা ঘরের সারি বানায়
       (SL · নাম · Dose · When · Duration), অথচ নিচের টেবিলের মাথায় ছিল মাত্র
       ৩টে — তাই Slip-এ SL নামের ঘরে, নাম Dose-এর ঘরে বসত, দুটো ঘর মাথা ছাড়িয়ে
       বেরিয়ে যেত। এখন মাথা ও সারি দুটোই ৫ ঘরের, তাই ওই গোলমালও শেষ।
    ⛔ ডাক্তারের নাম Slip-এ বসছে না — TK: "আগে কি ছিল তাই থাকবে"। */
 if(String(type||'').toUpperCase()==='MEDICINE SLIP'){
  professionalMedicalPrint(id,type,`<div class="rxApprovedGrid" style="--clinic-watermark:url('${branchPrintLogoPath(p)}')"><aside class="rxComplaintHistory">${wlv1SlipHistoryHtml(p)}<div class="anRxBot"><div class="rxPrintAdvice"><span><b>ADVICE:</b> Sitz Bath — 2 Times Daily</span></div><div class="anRxNext"><b>Next Follow-up Date</b><span>${p.nextFollow?esc(wlv1Dot(p.nextFollow)):'_______________'}</span></div></div></aside><section><div class="rxGridMark">℞</div><table class="printTable finalPrintTable"><tr><th>SL</th><th>Medicine Name</th><th>Dose</th><th>When</th><th>Duration</th></tr>${list}</table></section></div>`);
  return;
 }
 professionalMedicalPrint(id,type,`<table class="printTable finalPrintTable"><tr><th>Medicine Name</th><th>Dose / Advice</th><th>Duration</th></tr>${list}</table>`);
}
