/* 🔵🔒 TK-অনুমোদিত প্রুফ (09.08.2026): Registration A4 এখন পূর্ণ ফর্ম — সব রেজিস্ট্রেশন-ঘর
   (নাম/ID/বয়স-লিঙ্গ/পেশা/ব্রাঞ্চ/মোবাইল/Alt/রোগ/ঠিকানা · Referred By · Medical · Fee) +
   নিচে ফাঁকা "DOCTOR'S CHECK-UP" (ডাক্তার হাতে লেখেন)। ⛝ ছাপা-লেবেল হালকা-ধূসর, ভরা-তথ্য
   গাঢ়-বোল্ড (প্রফেশনাল নিয়ম — .k হালকা, .v গাঢ়)। Advance to Pay / Patient's Decision শুধু
   প্রিন্ট থেকে বাদ — সিস্টেম/চেকআপ-ফর্মে অটুট। ⛔ payment receipt-এর shared shell ছোঁয়া হয়নি। */
function wlv1RegA4Html(p, o){
  o=o||{};
  var dt=(o.date||today())+' · '+(o.time||wlv1NowTime());
  var clinic=(typeof medClinicName==='function')?medClinicName(p.branch):'MAA AYURVED PILES CLINIC';
  var br=(typeof branch==='function')?branch(p.branch):{};
  var logo=(typeof isKishanganjBranchName==='function'&&isKishanganjBranchName(p.branch))?'assets/kishanganj-final-logo.jpg':'assets/maa-ayurved-final-logo.jpg';
  var pid=esc(p.patientId||'-');
  var ageSex=esc([p.sex,p.age].filter(Boolean).join(' / ')||'-');
  var addr2=p.address?wlv1AddrTwo(String(p.address)):'-';
  var photoCell=p.photo?('<div class="pphoto" style="background-image:url(\''+esc(p.photo)+'\')"></div>'):'<div class="pphoto">🧑</div>';
  var extraCss='.sh{display:flex;justify-content:space-between;align-items:center}.sh .hint{color:#9a7b28;font-weight:700;font-size:10px;letter-spacing:.5px}.docsec .cell{align-items:flex-end}.vb{flex:1;min-height:26px}';
  function rc(k,v,full){return '<div class="cell'+(full?' full':'')+'"><span class="k">'+esc(k)+'</span><span class="v">'+esc((v==null||v==='')?'-':v)+'</span></div>';}
  function rb(k,full){return '<div class="cell'+(full?' full':'')+'"><span class="k">'+esc(k)+'</span><span class="vb"></span></div>';}
  var refRows='';
  if((p.refBy&&String(p.refBy).trim())||(p.refDoctor&&String(p.refDoctor).trim())||(p.refDoctorMobile&&String(p.refDoctorMobile).trim())){
    refRows='<div class="sec"><div class="sh"><span>REFERRED BY</span></div><div class="g">'+
      rc('Referred By',p.refBy)+(p.refDoctor?rc('Doctor Name',p.refDoctor):'')+(p.refDoctorMobile?rc('Doctor Mobile',normMob(p.refDoctorMobile)):'')+'</div></div>';
  }
  var medRows='';
  if((p.complaint&&String(p.complaint).trim())||(p.sinceWhen&&String(p.sinceWhen).trim())||(p.previousTreatment&&String(p.previousTreatment).trim())){
    medRows='<div class="sec"><div class="sh"><span>MEDICAL DETAILS (at Registration)</span></div><div class="g">'+
      (p.complaint?rc('Complaint',p.complaint,true):'')+(p.sinceWhen?rc('Since When',p.sinceWhen):'')+(p.previousTreatment?rc('Previous Treatment',p.previousTreatment):'')+'</div></div>';
  }
  var feeRows='';
  if(Number(o.regFee||0)>0||o.regFeeMode||o.regMode){
    feeRows='<div class="sec"><div class="sh"><span>REGISTRATION FEE</span></div><div class="g">'+
      (Number(o.regFee||0)>0?rc('Registration Fee',wlv1A4Money(o.regFee)):'')+((o.regFeeMode||o.regMode)?rc('Payment Mode',o.regFeeMode||o.regMode):'')+'</div></div>';
  }
  var docRows='<div class="sec docsec"><div class="sh"><span>DOCTOR\'S CHECK-UP</span><span class="hint">TO BE FILLED BY DOCTOR</span></div><div class="g">'+
    rb('Examination / DRE',true)+rb('Grade')+rb('On Probing')+rb('Other Findings',true)+rb('Investigation Advised',true)+rb('Treatment Plan',true)+rb('Estimated Cost')+rb('Recovery Time')+rb("Doctor's Remarks / Advice",true)+'</div></div>';
  return '<!DOCTYPE html><html><head><meta charset="utf-8"><style>'+wlv1DocA4CSS()+extraCss+'</style></head><body>'+
    '<div class="gold"></div><div class="lh"><img src="'+logo+'"><div><div class="cn">'+esc(clinic)+'</div><div class="tag">Ayurveda &amp; Anorectal Diseases</div>'+
    '<div class="addr"><b>'+esc(p.branch||'')+':</b> '+esc(br.address||'')+' &nbsp;|&nbsp; <b>&#9742;</b> '+esc(br.mobile||'')+'</div></div></div><div class="gbar"></div>'+
    '<div class="tb"><span class="t">PATIENT REGISTRATION FORM</span><span class="r">Reg. No: '+pid+'<br>Date: '+esc(dt)+'</span></div>'+
    '<div class="pi">'+photoCell+
      '<div class="c"><div class="r"><b>Name</b> : '+esc(String(p.name||'-')).toUpperCase()+'</div><div class="r"><b>Patient ID</b> : '+pid+'</div><div class="r"><b>Age / Sex</b> : '+ageSex+'</div><div class="r"><b>Occupation</b> : '+esc(p.occupation||'-')+'</div><div class="r"><b>Branch</b> : '+esc(p.branch||'-')+'</div></div>'+
      '<div class="c"><div class="r"><b>Mobile</b> : '+esc(normMob(p.mobile||'')||'-')+'</div><div class="r"><b>Alt Mobile</b> : '+esc(normMob(p.altMobile||'')||'-')+'</div><div class="r"><b>Disease</b> : '+esc(p.disease||'-')+'</div><div class="r"><b>Address</b> : <span style="display:inline-block;vertical-align:top">'+addr2+'</span></div></div></div>'+
    '<div class="wrap">'+refRows+medRows+feeRows+docRows+
      '<div class="note">📌 Please keep your Patient ID ('+pid+') safe for future visits and follow-ups.</div></div>'+
    '<div class="foot"><div class="stamp">Clinic Seal</div><div class="sign"><div class="ln"></div><div class="dn">Doctor\'s Signature</div><div class="rl">'+esc(clinic)+'</div></div></div>'+
    '<div class="fn">This is a computer-generated document from '+esc(clinic)+' &middot; No physical signature required.</div>'+
    '</body></html>';
}
function wlv1PayA4Html(p, o){
  o=o||{}; var dt=esc((o.date||today())+' · '+(o.time||wlv1NowTime()));
  var bill=Number(o.bill||0), paid=Number(o.paid||0), due=Math.max(0,bill-paid);
  var inner='<div class="wrap"><div class="sec"><div class="amtBig"><span class="lbl">AMOUNT RECEIVED</span><span class="val">'+wlv1A4Money(o.amount)+'</span></div><div class="g">'+
    /* 🔵 TK-অনুমোদিত (১৫.০৮.২০২৬, "ক করেন") — ফোনের রসিদে থাকা **Purpose** (কীসের টাকা)
       ঘরটা এখানেও যোগ। ⛔ ফোনের `PrintMappersCloud.paymentReceipt()`-এর **হুবহু একই নিয়ম**:
       `payLabel` → না থাকলে `paymentLabel` → তাও না থাকলে `"Payment"`।
       ⛔ ফোনের মতো এটাই তালিকার **প্রথম** ঘর। ⛔ অন্য কোনো ঘর সরানো/বদলানো হয়নি —
       Total Bill · Total Paid · Due · Date & Time সবই আগের মতোই আছে (TK-এর সিদ্ধান্ত:
       "কোনো ভালো কাজ যেন খারাপ না হয়")। */
    '<div class="cell"><span class="k">Purpose</span><span class="v">'+esc(o.payLabel||o.paymentLabel||'Payment')+'</span></div>'+
    '<div class="cell"><span class="k">Payment Mode</span><span class="v">'+esc(o.mode||'-')+'</span></div>'+
    '<div class="cell"><span class="k">Date &amp; Time</span><span class="v">'+dt+'</span></div>'+
    (bill>0?('<div class="cell"><span class="k">Total Bill</span><span class="v">'+wlv1A4Money(bill)+'</span></div>'+
    '<div class="cell"><span class="k">Total Paid</span><span class="v">'+wlv1A4Money(paid)+'</span></div>'+
    '<div class="cell"><span class="k">Due</span><span class="v">'+wlv1A4Money(due)+'</span></div>'):'')+
    (o.receivedBy?('<div class="cell"><span class="k">Received By</span><span class="v">'+esc(o.receivedBy)+'</span></div>'):'')+
    '</div></div>'+
    '<div class="note">🧾 This is your payment receipt. Please keep it for your records.</div></div>';
  var rno=esc(o.receiptNo||p.patientId||'-');
  return wlv1DocA4Shell(p,'PAYMENT RECEIPT','Receipt No: '+rno+'<br>Date: '+dt, inner);
}
function wlv1ShowDocA4(html, titleLabel){
  var b64=(function(){try{return btoa(encodeURIComponent(html))}catch(e){return ''}})();
  // 🔒 B594 (TK-অনুমোদিত ফ্লো, 09.08.2026): A4 পর্দা থেকেই স্টাফ (১) প্রিন্ট/PDF সেভ,
  // (২) রোগীর WhatsApp খুলে সেভ-করা PDF অ্যাটাচ করতে পারে। ⛔ নতুন ক্লাউড-কল নেই।
  var meta=window.__wlv1MsgMeta||{};
  // 🔒 B595/B596 (TK-নির্দেশ 09.08.2026): A4 পর্দার সব লেখা/বোতাম ইংরেজিতে —
  // এখানে বাংলা থাকবে না। সব বোতাম একই সাইজের বক্সে (grid), আলাদা করে:
  // WhatsApp · Save · Print · Close। কম্পিউটার-মোবাইল দুই জায়গায় একই সাজ।
  var hasMob=(meta.mobile&&String(meta.mobile).length===10);
  var bs='border:none;margin:0;width:100%;padding:12px 0;border-radius:11px;font-size:14px;font-weight:700';
  var btnWA=hasMob?('<button style="'+bs+';background:#25a95a;color:#fff" onclick="wlv1A4OpenWhatsApp(\''+String(meta.mobile)+'\')">💬 WhatsApp</button>'):'';
  var btnSave='<button style="'+bs+';background:#1976d2;color:#fff" onclick="wlv1PrintCheckupA4(\''+b64+'\')">💾 Save</button>';
  var btnPrint='<button style="'+bs+';background:#0f5132;color:#fff" onclick="wlv1PrintCheckupA4(\''+b64+'\')">🖨️ Print</button>';
  var btnClose='<button style="'+bs+';background:#eceff3;color:#42505e" onclick="goBackOnePage()">✕ Close</button>';
  var actsHtml='<div style="display:grid;grid-template-columns:1fr 1fr;gap:9px">'+btnWA+btnSave+btnPrint+btnClose+'</div>';
  var noteHtml='💡 <b>WhatsApp</b> — send to the patient (save the PDF and attach it). <b>Save</b> — keep as PDF. <b>Print</b> — print on paper. (An A4 PDF cannot be sent by SMS.)';
  /* 🖥️🔵 A4 Document — পপ-আপ থেকে **পূর্ণ পাতা** (TK-অনুমোদিত, ১৫.০৮.২০২৬ — "Android-এ যেমন
     ঠিক তেমনভাবে অনুসরণ করুন")। Android-এ এটা পূর্ণ পর্দা `print/PrintPreviewActivity.kt`
     (+ `activity_print_preview.xml`) — চারটে বোতাম **💬 WhatsApp · 💾 Save · 🖨 Print · ✕ Close**,
     যা ওয়েবে **আগে থেকেই হুবহু একই** (সারি B595/B596-এ TK-অনুমোদিত)।
     ⛔ **সৎভাবে জানানো:** Android-এ উপরে `◀ PREV / Page 1 of 1 / NEXT ▶` আছে, কারণ ফোনে
        PDF-এর প্রতিটা পাতা আলাদা ছবি করে দেখানো হয়। ওয়েবে প্রিভিউ একটাই HTML পাতা —
        সেখানে "কত পাতা" বলে কিছু নেই। তাই ঐ দুটো বোতাম **বানানো হয়নি** — না বুঝে নকল
        বোতাম বসালে সেটা কাজ করত না (আন্দাজে কিছু করা নিষেধ)।
     ⛔ ভিতরের সবকিছু — সবুজ হেডার · প্রিভিউর মাপ · হলুদ সাহায্য-লেখা · চারটে বোতাম ও
        তাদের কাজ — **এক অক্ষরও বদলায়নি**; শুধু ফ্রেম পাতা হলো ও ✕ Close ফেরত যায়। */
  /* 🔧 প্রথম চেষ্টায় শিরোনাম **দুবার** উঠছিল (পাতার নিজের শিরোনাম + ভিতরের সবুজ বার) —
     প্রুফে ধরা পড়ল ও ঠিক করা হলো। Android-এ শিরোনাম **একবারই** (toolbar), তাই ভিতরের
     ডুপ্লিকেট সবুজ বারটা বাদ; পাতার শিরোনামই থাকল। */
  page(esc(titleLabel||'A4 Document'), '<div class="nkWrap a4Page">'+
    '<div style="max-height:60vh;overflow:auto;border:1px solid #e3e9f1;border-radius:10px;margin:0 0 10px;background:#eef2f6;padding:8px;text-align:center"><div style="width:365px;height:516px;overflow:hidden;display:inline-block"><iframe scrolling="no" style="width:794px;height:1123px;transform:scale(0.46);transform-origin:top left;border:0" srcdoc="'+esc(html)+'"></iframe></div></div>'+
    '<div style="background:#FFF7E6;border:1px dashed #E2C877;border-radius:9px;padding:8px 11px;margin:0 0 10px;font-size:12px;color:#5C4A12;line-height:1.5">'+noteHtml+'</div>'+
    actsHtml+'</div>', true);
}
